function Utils.now()
    return os.clock()
end

function Utils.json(fuseFodder)
    local ok, res = pcall(HttpService.JSONEncode, HttpService, fuseFodder)
    return ok and res or "{}"
end

function Utils.unjson(res)
    local ok, res2 = pcall(HttpService.JSONDecode, HttpService, res)
    return ok and res2 or nil
end

function Utils.readJson(path)
    local ok, text = pcall(function()
        return isfile(path) and readfile(path) or nil
    end)
    return ok and text and Utils.unjson(text) or nil
end

-- JSON has no inf/nan. Replaces them in a copy so a save never fails or leaves
-- a file that can't be read back (which would reset the farm's memory).
function Utils.finiteCopy(value, depth)
    if type(value) == "number" then
        if value ~= value then
            return 0
        elseif value == math.huge then
            return 1e300
        elseif value == -math.huge then
            return -1e300
        end
        return value
    end
    if type(value) ~= "table" or (depth or 0) > 60 then
        return value
    end
    local copy = {}
    for key, item in pairs(value) do
        copy[key] = Utils.finiteCopy(item, (depth or 0) + 1)
    end
    return copy
end

-- Bare words after ":", "," or "[" other than true/false/null mean an inf/nan slipped in.
function Utils.jsonLooksValid(text)
    for word in text:gmatch("[:,%[]%s*%-?(%a[%w%.#]*)") do
        if word ~= "true" and word ~= "false" and word ~= "null" then
            return pcall(HttpService.JSONDecode, HttpService, text)
        end
    end
    return true
end

function Utils.encodeJson(data)
    local encoded, text = pcall(HttpService.JSONEncode, HttpService, data)
    if encoded and Utils.jsonLooksValid(text) then
        return true, text
    end
    local cleaned, text2 = pcall(HttpService.JSONEncode, HttpService, Utils.finiteCopy(data))
    if cleaned then
        return true, text2
    end
    return false, encoded and "the saved data can't be turned into JSON" or text
end

function Utils.writeJson(path, data)
    pcall(function()
        if not isfolder(Core.FOLDER) then
            makefolder(Core.FOLDER)
        end
    end)
    local encoded, text = Utils.encodeJson(data)
    if not encoded then
        return false, text
    end
    local written, errorMessage = pcall(writefile, path, text)
    if written and errorMessage == false then
        return false, "writefile returned false for " .. path
    end
    return written, errorMessage, text
end

function Utils.fmt(arg1)
    arg1 = tonumber(arg1) or 0
    if arg1 >= 1e6 then
        return string.format("%.2fM", arg1 / 1e6)
    end
    if arg1 >= 1e4 then
        return string.format("%.1fk", arg1 / 1e3)
    end
    return tostring(math.floor(arg1 + 0.5))
end

function Utils.clamp(arg1, arg2, arg3)
    return math.max(arg2, math.min(arg3, arg1))
end

function Utils.count(arg1)
    local count = 0
    for _ in pairs(arg1 or {
    }) do
        count = count + 1
    end
    return count
end

function Utils.list(arg1)
    if type(arg1) ~= "table" then
        return {
        }
    end
    if # arg1 > 0 then
        return arg1
    end
    local list = {
    }
    for key in pairs(arg1) do
        table.insert(list, key)
    end
    table.sort(list, function(arg1, arg2)
        return (tonumber(arg1) or 0) < (tonumber(arg2) or 0)
    end)
    local list2 = {
    }
    for _, item in ipairs(list) do
        table.insert(list2, arg1 [item])
    end
    return list2
end

function Utils.flat(vec)
    return Vector3.new(vec.X, 0, vec.Z)
end

function Utils.plain(arg1, arg2)
    local kind = type(arg1)
    if kind == "number" or kind == "string" or kind == "boolean" then
        return arg1
    end
    if kind ~= "table" or (arg2 or 0) > 6 then
        return nil
    end
    local list = {
    }
    for key, value in pairs(arg1) do
        if type(key) == "number" or type(key) == "string" then
            list [key] = Utils.plain(value, (arg2 or 0) + 1)
        end
    end
    return list
end

-- Planner lines are queued and written with the main log every few seconds,
-- instead of one file write per line while the planner is busy.
function App.writePlannerLog(entry)
    LogBuffer.planPending = LogBuffer.planPending or {}
    table.insert(LogBuffer.planPending, os.date("%Y-%m-%d ") .. entry)
end

-- Appends to a log file. Past LOG_MAX_BYTES the file moves to "<name>.old" (one
-- generation is kept), so logs no longer grow without limit over days of farming.
function App.appendLog(path, text)
    LogBuffer.sizes = LogBuffer.sizes or {}
    local size = LogBuffer.sizes[path]
    if size == nil then
        local ok, current = pcall(function()
            return isfile(path) and readfile(path) or ""
        end)
        size = ok and type(current) == "string" and #current or 0
    end
    if size > 0 and size + #text > Core.LOG_MAX_BYTES then
        pcall(function()
            writefile(path .. ".old", readfile(path))
        end)
        writefile(path, text)
        size = #text
    elseif size > 0 and type(appendfile) == "function" and isfile(path) then
        appendfile(path, text)
        size = size + #text
    elseif size > 0 and isfile(path) then
        writefile(path, readfile(path) .. text)
        size = size + #text
    else
        writefile(path, text)
        size = #text
    end
    LogBuffer.sizes[path] = size
end

function App.log(arg1, log, arg3)
    local visible = arg1 <= (Config.logLevel or 1)
    if not visible and log ~= "PLAN" then
        return
    end
    local text = string.format("[%s] %-7s %s", os.date("%H:%M:%S"), log, tostring(arg3))
    if log == "PLAN" then
        App.writePlannerLog(text)
    end
    if not visible then return end
    table.insert(LogBuffer.lines, text)
    if GUI.activityLog then
        pcall(function()
            GUI.activityLog:Push(GUI.escape(text), arg1 == 0 and "Error" or nil)
        end)
    end
    if # LogBuffer.lines > 250 then
        table.remove(LogBuffer.lines, 1)
    end
    table.insert(LogBuffer.pending, text)
    local arg32 = tostring(arg3):lower()
    if arg32:find("refused") or arg32:find("error") or arg32:find("timeout") or log == "FATAL" then
        LogBuffer.problems = LogBuffer.problems or {
        }
        table.insert(LogBuffer.problems, text)
        if # LogBuffer.problems > 30 then
            table.remove(LogBuffer.problems, 1)
        end
    end
    if Config.logConsole then
        print("[AA] " .. text)
    end
end

function App.status(arg1, arg2)
    Status [arg1] = arg2
end

function App.flush()
    local plan = LogBuffer.planPending
    if plan and # plan > 0 then
        local text = table.concat(plan, "\n") .. "\n"
        LogBuffer.planPending = {}
        local ok, err = pcall(function()
            assert(type(writefile) == "function" and type(isfile) == "function", "file writing is unavailable")
            if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(Core.FOLDER) then
                makefolder(Core.FOLDER)
            end
            App.appendLog(Core.PLAN_LOGFILE, text)
        end)
        if not ok and not App.plannerFileWarning then
            App.plannerFileWarning = true
            App.log(0, "LOG", "Could not write " .. Core.PLAN_LOGFILE .. ": " .. tostring(err))
        end
    end
    if # LogBuffer.pending == 0 then
        return
    end
    local text = table.concat(LogBuffer.pending, "\n") .. "\n"
    table.clear(LogBuffer.pending)
    pcall(function()
        if not isfolder(Core.FOLDER) then
            makefolder(Core.FOLDER)
        end
        App.appendLog(Core.LOGFILE, text)
    end)
end
