function App.saveNow()
    local settingsSaved, settingsError = Utils.writeJson(Core.SETTINGS, Config)
    local brainSaved, brainError, brainText = Utils.writeJson(Core.BRAIN, Brain)
    -- A second copy every 10 minutes: if the game closes in the middle of a write,
    -- the farm's memory comes back from it instead of starting over.
    if brainSaved and brainText and os.time() - (App.backupAt or 0) >= 600 then
        if pcall(writefile, Core.BRAIN_BACKUP, brainText) then
            App.backupAt = os.time()
        end
    end
    if not settingsSaved or not brainSaved then
        App.log(1, "SAVE", tostring(not brainSaved and brainError or settingsError))
        App.saveAt = Utils.now() + 10
    end
    App.flush()
    return brainSaved
end
