function Units.field(unitId, arg2)
    local unit = Core.Units [unitId]
    local minimum = arg2 == "upgrade" and Core.FUSION_MIN_UPGRADES[unitId]
    if minimum then
        local live = unit and unit.upgrade
        if type(live) == "table" and #live >= minimum then return live end
        local learned = Brain.unitData[unitId] and Brain.unitData[unitId].upgrade
        if type(learned) == "table" and #learned >= minimum then return learned end
        local fallback = Core.FILL_UNITS[unitId].upgrade
        local partial = type(live) == "table" and live or learned
        if type(partial) ~= "table" or #partial == 0 then return fallback end
        local combined = table.clone(fallback)
        for index, row in ipairs(partial) do combined[index] = row end
        return combined
    end
    if type(unit) == "table" and unit [arg2] ~= nil then
        return unit [arg2]
    end
    local value = Brain.unitData [unitId]
    if value then
        return value [arg2]
    end
    local ok, res = pcall(Reports.hiveStat, unitId)
    if ok and res and res [arg2] ~= nil then
        return res [arg2]
    end
    local fillUnit = Core.FILL_UNITS [unitId]
    return fillUnit and fillUnit [arg2]
end

function Units.hidden(unitId)
    local unit = Core.Units [unitId]
    if not (type(unit) == "table" and unit.upgrade == nil and (tonumber(unit.cost) or 0) > 0) then
        return false
    end
    if (Brain.unitData [unitId] and Brain.unitData [unitId].upgrade) or Core.FILL_UNITS [unitId] then
        return false
    end
    local ok, res = pcall(Reports.hiveStat, unitId)
    return not (ok and res and res.upgrade)
end

function Units.markHidden()
    local count = 0
    for unitKey, unit in pairs(Core.Units) do
        if type(unit) == "table" and unit.upgrade == nil and (tonumber(unit.cost) or 0) > 0 then
            Brain.hidden [unitKey] = true
            count = count + 1
        end
    end
    return count
end

function Units.capture()
    local list = {
    }
    for key in pairs(Brain.hidden) do
        local unit = Core.Units [key]
        if type(unit) == "table" and type(unit.upgrade) == "table" then
            local list2 = {
            }
            for _, value in ipairs(Units.KEEP) do
                if unit [value] ~= nil then
                    list2 [value] = Utils.plain(unit [value])
                end
            end
            if not Brain.unitData [key] then
                table.insert(list, Units.name(key))
            end
            Brain.unitData [key] = list2
            Units._rows [key] = nil
            if Units._effects then
                Units._effects [key] = nil
            end
        end
    end
    if # list > 0 then
        App.log(1, "UNITS", "learned the hidden upgrade stats of " .. table.concat(list, ", ") .. " (the game only sends them in a match)")
        App.saveSoon()
    end
end
