Units.CC_COOLDOWN = {
    slow = 3,
    stun = 8,
    freeze = 10,
    haki_stun = 15,
    knockback = 30,
    walk_back = 10,
    walk_back_time = 10
}
Units._fill = {
}

function Units.fillAlias(arg1)
    local match, match2 = tostring(arg1):match("^(.-):([^:]+)$")
    if not match or match:find("|", 1, true) then
        return nil
    end
    local value
    for fillAttackKey, fillAttack in pairs(Core.FILL_ATTACKS) do
        if fillAttackKey:match(":([^:]+)$") == match2 then
            if fillAttackKey:sub(1, # match + 1) == match .. "|" then
                return fillAttack
            end
            if fillAttackKey:sub(1, # match + 1) == match .. "_" and fillAttackKey:find("|", # match + 2, true) then
                value = value or fillAttack
            end
        end
    end
    return value
end

function Units.fillAttack(field)
    if Units._fill [field] ~= nil then
        return Units._fill [field]
    end
    local fillAttack = Core.FILL_ATTACKS [field] or Units.fillAlias(field)
    local flag = false
    if fillAttack then
        local value = fillAttack.k == "c" and {
            type = "circle",
            radius = fillAttack.r
        } or fillAttack.k == "n" and {
            type = "cone",
            angle = fillAttack.r
        } or fillAttack.k == "f" and {
            type = "full_aoe"
        } or fillAttack.k == "l" and {
            type = "straight"
        } or {
        }
        local list = {
        }
        if fillAttack.slow then
            table.insert(list, {
                name = "slow",
                time = fillAttack.t,
                params = {
                    slow_percent = fillAttack.slow
                }
            })
        end
        if fillAttack.stun then
            table.insert(list, {
                name = "stun",
                time = fillAttack.stun,
                params = {
                }
            })
        end
        if fillAttack.freeze then
            table.insert(list, {
                name = "freeze",
                time = fillAttack.freeze,
                params = {
                }
            })
        end
        if fillAttack.knock then
            table.insert(list, {
                name = "knockback",
                time = fillAttack.knock,
                params = {
                }
            })
        end
        if fillAttack.amp then
            table.insert(list, {
                name = "amplify",
                time = 1,
                params = {
                    amplification = fillAttack.amp,
                    persistent = fillAttack.keep
                }
            })
        end
        if fillAttack.dot then
            table.insert(list, {
                name = fillAttack.dot,
                time = fillAttack.ticks,
                params = {
                    damage_rate = fillAttack.rate
                }
            })
        end
        local h = fillAttack.h or 1
        local list2 = {
        }
        for i = 1, h do
            list2 [i] = {
                aoe_type = value,
                hit = {
                    damage = 1 / h,
                    buffs = i == 1 and list or nil
                }
            }
        end
        flag = {
            aoe = list2
        }
    end
    Units._fill [field] = flag
    return flag
end

function Units.attackInfo(atk, range)
    local text = tostring(atk) .. ":" .. tostring(range and math.floor(range) or "")
    if Units._atk [text] then
        return Units._atk [text]
    end
    local info = {
        n = 1,
        dot = 0,
        slow = 0,
        stun = 0,
        amp = 0,
        ampPersist = false,
        hits = 0,
        bleed = false,
        slowPct = 0,
        slowTime = 0
    }
    local attack = atk and (Core.Attacks [atk] or Units.fillAttack(atk))
    if type(attack) ~= "table" then
        info.hits = 1
        Units._atk [text] = info
        return info
    end
    local count = 0
    local function helper(arg1, arg2)
        if type(arg1) ~= "table" then
            return
        end
        local aoeType = type(arg1.aoe_type) == "table" and arg1.aoe_type or {
        }
        local hit = type(arg1.hit) == "table" and arg1.hit or {
        }
        local damage = tonumber(hit.damage) or 1
        if hit.break_shields then
            info.breakShields = true
        end
        local num = 1
        if aoeType.type == "target_aoe_circ" or aoeType.type == "circle" or aoeType.type == "circ" then
            num = 1 + (tonumber(aoeType.radius) or 4) / 5
        elseif aoeType.type == "cone" then
            num = 1 + (tonumber(aoeType.angle) or 45) / 60
        elseif aoeType.type == "full_aoe" or aoeType.type == "full" then
            num = 3
            if not arg1.hit_allies then
                info.full = true
            end
        elseif aoeType.type == "straight" or aoeType.type == "line" then
            num = 1 + (tonumber(aoeType.length) or tonumber(range) or 10) / 15
        end
        if not arg1.hit_allies then
            count = count + damage * arg2 * math.min(num, 4)
            info.hits = info.hits + arg2
        end
        for _, buff in pairs(hit.buffs or {
        }) do
            if type(buff) == "table" and type(buff.name) == "string" then
                local params = type(buff.params) == "table" and buff.params or {
                }
                local time = tonumber(buff.time) or 0
                if arg1.hit_allies then
                    if buff.name:find("^damage_buff__") and type(params.damage_types) == "table" then
                        local list = {
                        }
                        for damageTypeKey, damageType in pairs(params.damage_types) do
                            list [damageTypeKey] = type(damageType) == "table" and tonumber(damageType.rate) or 0
                        end
                        info.ally = {
                            types = list,
                            time = time
                        }
                    elseif buff.name == "attack_cooldown_buff" then
                        info.allyCd = {
                            reduce = tonumber(params.attack_cooldown_reduce) or 0,
                            time = time
                        }
                    elseif buff.name == "range_buff" then
                        info.allyRange = {
                            add = tonumber(params.range_add) or 0,
                            time = time
                        }
                    end
                else
                    if tonumber(params.damage_rate) then
                        info.dot = info.dot + tonumber(params.damage_rate) * math.max(1, time)
                    end
                    if buff.name:find("bleed") or buff.name:find("wither") or buff.name:find("decay") then
                        info.bleed = true
                    end
                    if buff.name == "slow" then
                        info.slow = math.max(info.slow, (tonumber(params.slow_percent) or 0.3) * time)
                        info.slowPct, info.slowTime = math.max(info.slowPct, tonumber(params.slow_percent) or 0.3), math.max(info.slowTime, time)
                    elseif buff.name == "stun" or buff.name == "freeze" or buff.name == "haki_stun" then
                        info.stun = math.max(info.stun, time)
                    elseif buff.name == "knockback" or buff.name == "walk_back" or buff.name == "walk_back_time" then
                        info.stun = math.max(info.stun, time * 0.5)
                    elseif tonumber(params.amplification) then
                        info.amp = math.max(info.amp, tonumber(params.amplification))
                        if params.persistent then
                            info.ampPersist = true
                        end
                    end
                    if Units.CC_COOLDOWN [buff.name] then
                        info.ccCd = math.max(info.ccCd or 0, Units.CC_COOLDOWN [buff.name])
                    end
                end
            end
        end
    end
    for _, value in pairs(type(attack.aoe) == "table" and attack.aoe or {
    }) do
        helper(value, 1)
    end
    for _, value in pairs(type(attack.aoe_dot) == "table" and attack.aoe_dot or {
    }) do
        if type(value) == "table" and type(value.aoe) == "table" then
            helper(value.aoe, (tonumber(value.time) or 1) / math.max(0.1, tonumber(value.interval) or 1))
            if type(value.first_aoe) == "table" then
                helper(value.first_aoe, 0)
            end
        end
    end
    for _, value in pairs(type(attack.hit) == "table" and attack.hit or {
    }) do
        if type(value) == "table" and value.damage then
            info.hits = info.hits + 1
        end
    end
    info.globalCd = attack.global_cooldown and true or false
    for _, value in pairs(type(attack.global_hit) == "table" and attack.global_hit or {
    }) do
        if type(value) == "table" then
            info.wholeMap = true
            helper({
                hit = value,
                hit_allies = value.hit_allies,
                aoe_type = {
                    type = "full_aoe"
                }
            }, 0)
        end
    end
    for _, value in pairs(type(attack.buff) == "table" and attack.buff or {
    }) do
        for _, value in pairs(type(value) == "table" and value or {
        }) do
            local buffConfig = type(value) == "table" and value.buff_config
            local params = type(buffConfig) == "table" and type(buffConfig.params) == "table" and buffConfig.params or {
            }
            if tonumber(params.damage_add) and not params.persistent then
                info.selfDmg = {
                    add = tonumber(params.damage_add),
                    time = tonumber(buffConfig.time) or 0
                }
            end
        end
    end
    if type(attack.on_base_hit) == "table" and attack.on_base_hit.prevent_hit then
        info.baseSafe = tonumber(attack.on_base_hit.time) or 0
    end
    info.n = math.max(0.3, count > 0 and count or (info.ally and 0.3 or 1))
    info.dot = math.min(1.5, info.dot)
    info.hits = math.max(1, info.hits)
    Units._atk [text] = info
    return info
end

function Units.aoe(atk, range)
    local attackInfo = Units.attackInfo(atk, range)
    return attackInfo.n * (1 + attackInfo.dot)
end

function Units.teamEffect(atk, range, cd, arg4)
    local attackInfo = Units.attackInfo(atk, range)
    local cd2 = math.max(cd or 1, attackInfo.ccCd or 0, 0.5)
    local value = math.min(1, attackInfo.n / 4)
    local num = arg4 and 0 or math.min(1, (attackInfo.slow + attackInfo.stun) / cd2) * value
    local amp = attackInfo.amp * (attackInfo.ampPersist and 1 or math.min(1, 5 / cd2)) * value
    return num * 0.5 + amp
end
Units._pas = {
}

function Units.passive(id)
    if Units._pas [id] then
        return Units._pas [id]
    end
    local list = {
    }
    local unit = Core.Units [id]
    for _, passive in pairs(type(unit) == "table" and type(unit.passives) == "table" and unit.passives or {
    }) do
        if type(passive) == "table" then
            local replaced = tostring(passive.description or ""):gsub("<[^>]+>", "")
            if passive.name == "Pact of Frailty" then
                list.mark = list.mark or {
                    amp = 0,
                    max = 1,
                    dot = 0
                }
                list.mark.amp = (tonumber(replaced:match("(%d+)%%")) or 0) / 100
                list.mark.max = tonumber(replaced:match("up to (%d+)")) or 1
            elseif passive.name == "Pact of Relevation" or passive.name == "Pact of Revelation" then
                list.mark = list.mark or {
                    amp = 0,
                    max = 1,
                    dot = 0
                }
                local match, match2 = replaced:match("(%d+)%%.-every ([%d%.]+)")
                list.mark.dot = (tonumber(match) or 0) / 100 / math.max(0.1, tonumber(match2) or 1)
            end
        end
    end
    Units._pas [id] = list
    return list
end
