        hits = 1,
        early = {
            dmg = 0.25,
            cd = 8,
            life = 60
        },
        late = {
            dmg = 0.25,
            cd = 8,
            life = 60
        }
    }
}

function Units.critMul(unitId)
    local unit = Core.Units [unitId]
    return 1 + (tonumber(type(unit) == "table" and unit.physical_crit_chance) or 0) * 0.5
end
Units._bleeds = {
}

function Units.bleeds(unitId)
    local bleed = Units._bleeds [unitId]
    if bleed ~= nil then
        return bleed or nil
    end
    local rows = Units.rows(unitId)
    local flag = false
    if rows then
        for i = 0, rows.max do
            local row = rows [i]
            if row and row.atk then
                local ok, res = pcall(Units.attackInfo, row.atk, row.range)
                if ok and res and res.bleed then
                    flag = i
                    break
                end
            end
        end
    end
    Units._bleeds [unitId] = flag
    return flag or nil
end

function Units.bestBleeder(arg1)
    local session = Core.session()
    if not session then
        return nil
    end
    local list = {
    }
    for _, unitData in ipairs(arg1 or {
    }) do
        list [unitData.unit_id] = true
    end
    local value, value2
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and not list [ownedUnit.unit_id] and Units.rows(ownedUnit.unit_id) and not Units.hidden(ownedUnit.unit_id) and Units.bleeds(ownedUnit.unit_id) then
            local ok, res = pcall(Core.USC.calculate_level, ownedUnit.unit_id, tonumber(ownedUnit.xp) or 0)
            if ok and (tonumber(res) or 0) >= 50 then
                local unitObj = session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit
                local ok, res = pcall(Units.score, unitObj)
                if ok and (not value2 or res > value2) then
                    value, value2 = unitObj, res
                end
            end
        end
    end
    return value
end

function Units.allyBuff(arg1)
    local unit = Core.Units [arg1]
    if type(unit) ~= "table" or not unit.active_attack then
        return nil
    end
    local attackInfo = Units.attackInfo(unit.active_attack)
    if not attackInfo.ally then
        return nil
    end
    local attackCooldown = tonumber(unit.active_attack_stats and unit.active_attack_stats.attack_cooldown) or 60
    return {
        types = attackInfo.ally.types,
        time = attackInfo.ally.time,
        cd = attackCooldown,
        uptime = math.min(1,
        (attackInfo.ally.time or 0) / math.max(1,
        attackCooldown)),
        attack = unit.active_attack,
        chain = arg1 == "erwin" or arg1 == "wendy" or arg1 == "leafa_evolved",
    }
end

function Units.buffAverage(buff, copies, base, chainAllowed)
    local capacity = copies * buff.uptime
    local regular = base * math.min(1, capacity)
    if not (buff.chain and chainAllowed) or copies < 2 then return regular end
    -- Forecast a relay with limited coverage. The live test measures the actual buff.
    local peak = math.min(1, (1 + base) ^ (copies - 1) - 1)
    return math.max(regular, peak * math.min(1, capacity) * 0.65)
end

function Units.buffCopies(allyBuff)
    local value = math.max(1, math.ceil((tonumber(allyBuff.cd) or 60) / math.max(1, tonumber(allyBuff.time) or 30) - 0.001))
    if allyBuff.chain and Config.actives and Config.community then return math.max(value, 5) end
    local value2 = Brain.stack [allyBuff.attack]
    if value2 and value2.stacks then
        local count = 0
        for _, value in pairs(allyBuff.types or {
        }) do
            count = math.max(count, tonumber(value) or 0)
        end
        if count > 0 and allyBuff.uptime > 0 then
            value = math.max(value, math.ceil((tonumber(value2.cap) or 1) / (count * allyBuff.uptime) - 0.001))
        end
    end
    return value
end

Units._effects = {
}

-- What a unit brings besides its own damage, read only from data the game really sends:
-- its attacks at every upgrade and its active ability. Used so a support is never
-- dropped for low personal DPS before the simulator has measured what it adds.
-- `useful` = at least one effect the simulator can play; `unmodeled` = seen in the data, not simulated.
function Units.effects(id)
    local cached = Units._effects [id]
    if cached then
        return cached
    end
    local unit = Core.Units [id]
    local rows = type(unit) == "table" and Units.rows(id) or nil
    local profile = {
        tags = {
        },
        unmodeled = {
        },
        score = 0,
        useful = false
    }
    if not rows then
        profile.missing = true
        return profile
    end
    local activeId, activeFrom, activeCd
    for level = 0, rows.max do
        local row = rows [level]
        if row then
            local ok, info = pcall(Units.attackInfo, row.atk, row.range)
            if ok and info then
                if (info.stun or 0) > 0 and (info.stun or 0) > (profile.stun or 0) then
                    profile.stun, profile.ccFrom = info.stun, profile.ccFrom or level
                    profile.ccCd = info.ccCd or 8
                end
                if (info.slowTime or 0) > 0 and (info.slowPct or 0) * info.slowTime > (profile.slow or 0) * (profile.slowTime or 0) then
                    profile.slow, profile.slowTime, profile.ccFrom = info.slowPct, info.slowTime, profile.ccFrom or level
                    profile.ccCd = profile.ccCd or info.ccCd or 3
                end
                if (info.amp or 0) > (profile.amp or 0) then
                    profile.amp = info.amp
                end
                if info.bleed then
                    profile.bleed = true
                end
            end
            if row.active and not activeId then
                activeId, activeFrom = row.active, level
            end
            if row.active then
                activeCd = tonumber(row.activeCd) or activeCd
            end
        end
    end
    if activeId then
        profile.active, profile.activeFrom, profile.activeCd = activeId, activeFrom, activeCd or 60
        if Core.Attacks [activeId] or Units.fillAttack(activeId) then
            local ok, info = pcall(Units.attackInfo, activeId)
            if ok and info then
                if info.ally then
                    profile.ally = info.ally
                end
                if info.allyCd then
                    profile.allyCd = info.allyCd
                end
                if info.allyRange then
                    profile.allyRange = info.allyRange
                    table.insert(profile.unmodeled, "its ability widens allies' range")
                end
                if info.selfDmg then
                    profile.selfDmg = info.selfDmg
                end
                if info.baseSafe then
                    profile.baseSafe = info.baseSafe
                end
                if (info.stun or 0) > 0 then
                    profile.activeStun, profile.activeWide = info.stun, info.wholeMap and true or false
                end
                if (info.amp or 0) > (profile.amp or 0) then
                    profile.amp = info.amp
                end
            end
        elseif not Units.FUSION or not Units.FUSION.attacks [id] then
            profile.activeUnknown = true
            table.insert(profile.unmodeled, "ability \"" .. tostring(activeId) .. "\" has no data here")
        end
    end
    local passiveCount = 0
    for _, passive in pairs(type(unit.passives) == "table" and unit.passives or {
    }) do
        if type(passive) == "table" and passive.name and not tostring(passive.name):find("^Pact of") then
            passiveCount = passiveCount + 1
        end
    end
    if passiveCount > 0 then
        profile.passives = passiveCount
        table.insert(profile.unmodeled, passiveCount .. (passiveCount == 1 and " passive" or " passives") .. " not simulated")
    end
    local score = 0
    if profile.stun then
        table.insert(profile.tags, string.format("stuns %.1fs", profile.stun))
        score = score + profile.stun / (profile.stun + (profile.ccCd or 8))
    end
    if profile.slow then
        table.insert(profile.tags, string.format("slows %d%% for %.0fs", math.floor(profile.slow * 100 + 0.5), profile.slowTime))
        score = score + profile.slow * profile.slowTime / (profile.slowTime + (profile.ccCd or 3))
    end
    if (profile.amp or 0) > 0 then
        table.insert(profile.tags, string.format("enemies take +%d%%", math.floor(profile.amp * 100 + 0.5)))
        score = score + profile.amp
    end
    if profile.ally then
        local kinds, best = {
        }, 0
        for kind, rate in pairs(profile.ally.types or {
        }) do
            table.insert(kinds, tostring(kind))
            best = math.max(best, tonumber(rate) or 0)
        end
        table.sort(kinds)
        profile.buffKinds = kinds
        table.insert(profile.tags, string.format("+%d%% %s damage to allies", math.floor(best * 100 + 0.5), table.concat(kinds, "/")))
        score = score + best
    end
    if profile.allyCd then
        table.insert(profile.tags, string.format("allies attack %d%% faster", math.floor((profile.allyCd.reduce or 0) * 100 + 0.5)))
        score = score + (profile.allyCd.reduce or 0)
    end
    if profile.activeStun then
        table.insert(profile.tags, string.format("ability stops %s for %.0fs", profile.activeWide and "every enemy" or "enemies in range", profile.activeStun))
        score = score + profile.activeStun / math.max(1, profile.activeCd or 60) * (profile.activeWide and 3 or 1)
    end
    if profile.baseSafe then
        table.insert(profile.tags, string.format("ability shields the base for %.0fs", profile.baseSafe))
        score = score + 0.2
    end
    profile.score = score
    profile.useful = score > 0
    profile.control = (profile.stun or profile.slow or profile.activeStun) and true or false
    Units._effects [id] = profile
    return profile
end

-- One short word for the planner view and its log.
function Units.roleName(id)
    if Units.isFarm(id) then
        return "farm"
    end
    local _, base = Units.types(id)
    local buff = Units.allyBuff(id)
    if buff then
        local kinds = {
        }
        for kind in pairs(buff.types or {
        }) do
            table.insert(kinds, tostring(kind))
        end
        table.sort(kinds)
        return table.concat(kinds, "/") .. " buffer"
    end
    if Units.FUSION and Units.FUSION.attacks [id] then
        return "fusion · " .. tostring(base)
    end
    local effects = Units.effects(id)
    if effects.control then
        return "control · " .. tostring(base)
    end
    if effects.useful and (effects.amp or effects.allyCd or effects.baseSafe) then
        return "support · " .. tostring(base)
    end
    return tostring(base) .. " attacker"
end

function Units.idol(id)
    local unit = Core.Units [id]
    if type(unit) ~= "table" or not (unit._NO_ATTACKS_UNIT and unit._show_as_buff_unit) then
        return false
    end
    for _, passive in pairs(unit.passives or {
    }) do
        local str = type(passive) == "table" and tostring(passive.description or ""):lower() or ""
        if str:find("upgrade") and str:find("cost") then
            return true
        end
    end
    return false
end

function Units.mult(unitData, arg2)
    local trait, tier = Units.trait(unitData)
    local joined = table.concat({tostring(unitData.uuid), tostring(unitData.unit_id), tostring(unitData.xp), tostring(trait), tostring(tier), arg2}, ":")
    local value = Units._mult [joined]
    if value and Utils.now() - value.t < 60 then
        return value.v
    end
    local ok, res = pcall(Core.USC.calculate_static_stat_multiplier, unitData, unitData.xp, arg2, Core.session())
    res = ok and tonumber(res) or 1
    Units._mult [joined] = {
        v = res,
        t = Utils.now()
    }
    return res
end

function Units.types(arg1)
    local unit = Core.Units [arg1] or {
    }
    local list = {
        [unit._base_damage_type or "physical"] = true
    }
    for secondaryDamageTypeKey in pairs(unit._secondary_damage_types or {
    }) do
        list [secondaryDamageTypeKey] = true
    end
    return list, unit._base_damage_type or "physical"
end

function Units.elem(unitId, portalMod)
    if not portalMod then
        return 1
    end
    local types, types2 = Units.types(unitId)
    local num = 1
    for typeKey in pairs(types) do
        if portalMod.weak [typeKey] then
            num = math.max(num, portalMod.weak [typeKey])
        end
    end
    if portalMod.strong [types2] then
        num = num * 0.5
    end
    if portalMod.res and portalMod.res [types2] then
        num = num * portalMod.res [types2]
    end
    return num
end

function Units.relic(unitData)
    local session = Core.session()
    if not (session and unitData._equipped_relic) then
        return 1
    end
    local ok, res = pcall(function()
        return session.inventory:get_item_by_uuid(unitData._equipped_relic)
    end)
    local uniqueRelicData = ok and res and res._unique_item_data and res._unique_item_data._unique_relic_data
    if not (uniqueRelicData and uniqueRelicData._core_damage_type_buffs) then
        return 1
    end
    local types = Units.types(unitData.unit_id)
    local num = 1
    for _, coreDamageTypeBuff in pairs(uniqueRelicData._core_damage_type_buffs) do
        if type(coreDamageTypeBuff) == "table" and types [coreDamageTypeBuff.damage_type] and tonumber(coreDamageTypeBuff.mul) then
            num = num + coreDamageTypeBuff.mul
        end
    end
    return num
end

function Units.relicName(unitObj)
    local session = Core.session()
    if not (session and unitObj._equipped_relic) then
        return nil
    end
    local ok, res = pcall(function()
        return session.inventory:get_item_by_uuid(unitObj._equipped_relic)
    end)
    local item = ok and res and Core.Items [res.item_id]
    return item and item.name or (ok and res and res.item_id) or nil
end

function Units.nudge(unitId)
    local value = Brain.learn [unitId]
    if not (value and value.n and value.n >= 3) then
        local hiveUnit = Reports.hiveUnit(unitId)
        return hiveUnit and Utils.clamp(math.sqrt(hiveUnit.eff), 0.8, 1.35) or 1
    end
    return Utils.clamp(math.sqrt(value.eff or 1), 0.8, 1.35)
end

function Units.trait(unitObj)
    for _, trait in pairs(unitObj.traits or {
    }) do
        if type(trait) == "table" then
            return trait.trait, trait.tier
        end
    end
    return nil
end

function Units.cap(unitData)
    local field = tonumber(Units.field(unitData.unit_id, "spawn_cap")) or 1
    if Units.trait(unitData) == "unique" then
        field = 1
    end
    local cap = tonumber(Brain.caps [unitData.uuid])
    if cap then
        field = math.min(field, cap)
    end
    return math.max(1, field)
end
Units.GALE = {
    rukia_bankai_evolved = {
        from = 1,
        tick = 1 / 3,
        duty = 1 / 3,
        targets = 3,
        freezeEvery = 13,
        freeze = 2,
        chill = 3,
        immune = 10
    }
}
Units._galeOf = {
}

function Units.galeOf(id)
    local value = Units.GALE [id]
    if not value then
        return nil
    end
    local toggle = Brain.toggles and Brain.toggles [id]
    if not (toggle and (toggle.nf or 0) >= 5 and (toggle.nd or 0) >= 5 and (toggle.fill or 0) > 0 and (toggle.drain or 0) > 0) then
        return value
    end
    local ratio = toggle.fill / (toggle.fill + toggle.drain)
    local value2 = Units._galeOf [id]
    if not (value2 and math.abs(value2.duty - ratio) < 0.01) then
        value2 = table.clone(value)
        value2.duty = ratio
        Units._galeOf [id] = value2
    end
    return value2
end

function Units.toggleOf(id)
    if Units.GALE [id] then
        return {
            from = Units.GALE [id].from,
            known = true
        }
    end
    local toggle = Brain.toggles and Brain.toggles [id]
    if toggle then
        return toggle
    end
    local ok, res = pcall(Reports.hiveToggle, id)
    return ok and res or nil
end

function Units.galeDps(unitId, upgradeValue)
    local galeOf = Units.galeOf(unitId)
    if not galeOf or (upgradeValue or 0) < galeOf.from then
        return 0
    end
    return galeOf.duty * galeOf.targets * (galeOf.tick + 1 / galeOf.freezeEvery)
end

function Units.dps(u, upgradeValue, mod, arg4)
    local rows = Units.rows(u.unit_id)
    local row = rows and rows [math.min(upgradeValue, rows.max)]
    if not row or (row.cd or 0) <= 0 then
        return 0
    end
    local damage = row.damage * Units.mult(u, "damage")
    local num = arg4 and 0 or damage * Units.galeDps(u.unit_id, upgradeValue)
    return (damage / (row.cd * math.max(0.1, Units.mult(u, "attack_cooldown"))) * Units.aoe(row.atk, row.range) * Units.critMul(u.unit_id) + num) * Units.elem(u.unit_id, mod) * Units.relic(u) * Units.nudge(u.unit_id)
end
Units._skinMul = {
}

function Units.skinMul(item, skinSet)
    local skinId = skinSet and item.skin and item.skin._skin_id
    local value = skinId and (Core.data("Skins") or {
    }) [skinId]
    if not (value and value._skin_set == skinSet) then
        return 1
    end
    local damageBoost = tonumber(value._damage_boost) or 0
    if damageBoost <= 0 then
        return 1
    end
    local text = tostring(item.uuid or skinId) .. ":" .. tostring(skinSet) .. ":" .. tostring(App.where)
    local value = Units._skinMul [text]
    if value and Utils.now() - value.t < 60 then
        return value.v
    end
    local value = 1 + damageBoost
    local ok, res = pcall(table.clone, item)
    if ok and type(res) == "table" then
        res.skin = nil
        local session = Core.session()
        local ok, res2 = pcall(Core.USC.calculate_static_stat_multiplier, item, item.xp, "damage", session)
        local ok2, res3 = pcall(Core.USC.calculate_static_stat_multiplier, res, item.xp, "damage", session)
        res2, res3 = ok and tonumber(res2), ok2 and tonumber(res3)
        if res2 and res3 and res3 > 0 and res2 / res3 > 1 + damageBoost * 0.5 then
            value = 1
        end
    end
    Units._skinMul [text] = {
        v = value,
        t = Utils.now()
    }
    return value
end

function Units.range(u, max)
    local rows = Units.rows(u.unit_id)
    local row = rows and rows [math.min(max, rows.max)]
    return (row and row.range or 10) * Units.mult(u, "range")
end

function Units.farm(u, arg2)
    local rows = Units.rows(u.unit_id)
    local row = rows and rows [math.min(arg2, rows.max)]
    return (row and row.farm or 0) * Units.mult(u, "farm_amount")
end

function Units.score(u, mod)
    local rows = Units.rows(u.unit_id)
    if not rows then
        return 0
    end
    local max = rows.max
    return Units.dps(u, max, mod) * math.sqrt(math.max(1, Units.range(u, max)) / 20) * math.sqrt(Units.cap(u))
end

function Units.name(arg1)
    local ui = Core.Units [arg1]
    return ui and ui.name or tostring(arg1)
end

function Units.isEvolvedForm(unitId)
    if not Units._evolvedForms then
        Units._evolvedForms = {
        }
        for _, unit in pairs(Core.Units) do
            if type(unit) == "table" and type(unit.evolve) == "table" and unit.evolve.evolve_unit then
                Units._evolvedForms [unit.evolve.evolve_unit] = true
            end
        end
    end
    return Units._evolvedForms [unitId] == true
end

function Units.equipped()
    local session = Core.session()
    local list = {
    }
    if not session then
        return list
    end
    for equippedUnitKey, equippedUnit in pairs(session.profile_data.collection.equipped_units or {
    }) do
        local unitObj = session.collection:get_unit_by_uuid(equippedUnit)
        if unitObj and Core.Units [unitObj.unit_id] then
            table.insert(list, {
                slot = tonumber(equippedUnitKey) or 0,
                uuid = equippedUnit,
                u = unitObj,
                id = unitObj.unit_id,
                data = Core.Units [unitObj.unit_id]
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.slot < arg2.slot
    end)
    return list
end

function Units.owns(arg1)
    local session = Core.session()
    if not session then
        return false
    end
    for _, ownedUnit in pairs(session.profile_data.collection.owned_units or {
    }) do
        if ownedUnit.unit_id == arg1 or (Core.Units [ownedUnit.unit_id] and Core.Units [ownedUnit.unit_id].evolved and Core.Units [ownedUnit.unit_id].evolved.from == arg1) then
            return true
        end
    end
    return false
end
Modes.PRIOR_MIN = {
    story = 4.5,
    challenge = 5,
    daily = 10,
    event = 28,
    raid = 6,
    infinite = 30,
    dungeon = 8,
    artifact = 12
}
Modes.PRIOR_WIN = {
    story = 0.9,
    hard = 0.8,
    new = 0.65,
    challenge = 0.75,
    daily = 0.7,
    event = 0.75,
    raid = 0.6,
    infinite = 1,
    dungeon = 0.85,
    artifact = 0.5
}
Modes.OVERHEAD = 0.7
Modes.CHAIN_MIN = 0.6
Modes._levelMod = {
}

function Modes.levelMod(level)
    if level == nil then
        return nil
    end
    if Modes._levelMod [level] ~= nil then
        return Modes._levelMod [level] or nil
    end
    Modes._levelMod [level] = false
    local level2 = Core.Levels [level]
    local wave = type(level2) == "table" and Core.Waves [level2.waves or level]
    local initialUnitConfigs = type(wave) == "table" and wave.initial_unit_configs
    if type(initialUnitConfigs) ~= "table" then
        return nil
    end
    local list, list2, count = {
    }, {
    }, 0
    for _, initialUnitConfig in pairs(initialUnitConfigs) do
        local value = type(initialUnitConfig) == "table" and type(initialUnitConfig.override_stats) == "table" and (initialUnitConfig.override_stats [1] or initialUnitConfig.override_stats ["1"]) or nil
        if type(value) == "table" then
            local health = tonumber(value.health) or 20
            count = count + health
            table.insert(list, {
                hp = health,
                st = value
            })
            for key in pairs(value) do
                local match = tostring(key):match("^_dmg_amp_(.+)$") or tostring(key):match("^_dmg_res_(.+)$")
                if match then
                    list2 [match] = true
                end
            end
        end
    end
    if not next(list2) or count <= 0 then
        return nil
    end
    local info = {
        weak = {
        },
        strong = {
        },
        res = {
        }
    }
    for itemKey in pairs(list2) do
        local count2 = 0
        for _, item in ipairs(list) do
            local ratio = (1 + (tonumber(item.st ["_dmg_amp_" .. itemKey]) or 0)) * 100 / (100 + math.max(0, tonumber(item.st ["_dmg_res_" .. itemKey]) or 0))
            count2 = count2 + item.hp / math.max(0.05, ratio)
        end
        local ratio = count / math.max(1, count2)
        if ratio > 1.02 then
            info.weak [itemKey] = ratio
        elseif ratio < 0.98 then
            info.res [itemKey] = ratio
        end
    end
    if not (next(info.weak) or next(info.res)) then
        return nil
    end
    Modes._levelMod [level] = info
    return info
end

function Modes.dailyMod(challengeUuid, dailyChallengeWeakAgainst, dailyChallengeStrongAgainst)
    challengeUuid = tonumber(challengeUuid)
    local value = challengeUuid and Random.new(challengeUuid) or nil
    local info = {
        weak = {
        },
        strong = {
        },
        res = {
        }
    }
    for _, value2 in pairs(dailyChallengeWeakAgainst or {
    }) do
        info.weak [value2] = value and 1 + value:NextNumber(0.5, 0.7) or 1.5
    end
    for _, value2 in pairs(dailyChallengeStrongAgainst or {
    }) do
        if value then
            info.res [value2] = 100 / (100 + value:NextNumber(100, 150))
        else
