function Modes.itemValue(item, arg2)
    if Brain.goalItems [item] then
        local arg22 = arg2 or 1
        local arg222 = math.min(arg22, tonumber(Brain.goalNeed [item]) or arg22)
        return Brain.goalItems [item] * arg222 + (Core.ITEM_VALUE [item] or Core.ITEM_DEFAULT) * math.max(0, arg22 - arg222)
    end
    if Config.team and Strategy.itemWorth then
        local ok, res = pcall(Strategy.itemWorth, item)
        if ok and res then
            return res * (arg2 or 1)
        end
    end
    local itemCap = Core.GS.ITEM_CAPS and Core.GS.ITEM_CAPS [item]
    local session = Core.session()
    local count = 0
    pcall(function()
        count = session.inventory:get_number_of_owned_item(item)
    end)
    if itemCap and count >= itemCap then
        return 0
    end
    return (Core.ITEM_VALUE [item] or Core.ITEM_DEFAULT) * (arg2 or 1)
end

function Modes.rewardValue(currentReward)
    local count = 0
    for _, reward in pairs((currentReward and currentReward._rewards) or {
    }) do
        if type(reward) == "table" then
            count = count + (tonumber(reward.gem_reward) or 0) + (tonumber(reward.gold_reward) or 0) * Core.GOLD_VALUE
            local list = Utils.list(reward.item)
            local num = 1
            if reward._item_multichoice and # list > 0 then
                num = math.min(1, (tonumber(reward._item_multichoice.min) or # list) / # list)
            end
            for _, item in ipairs(list) do
                local amount = tonumber(item.amount) or ((tonumber(item.min_amount) or 1) + (tonumber(item.max_amount) or tonumber(item.min_amount) or 1)) / 2
                local chance = (tonumber(item.chance) or 1) * (1 - (tonumber(item._zero_chance) or 0))
                count = count + Modes.itemValue(item.item_id, amount) * chance * num
            end
        end
    end
    return count
end

function Modes.done(levelData, id, arg3)
    if Brain.cleared [id .. ":" .. tostring(arg3 or "Normal")] then
        return true
    end
    local completedStoryLevel = levelData.completed_story_levels and levelData.completed_story_levels [id]
    if not completedStoryLevel then
        return false
    end
    if arg3 and completedStoryLevel.difficulty_completed_data then
        local value = completedStoryLevel.difficulty_completed_data [arg3]
        return value and (value.times_completed or 0) > 0 or false
    end
    return (completedStoryLevel.times_completed or 0) > 0
end

