function Modes.artifactLeft(level)
    local level2, artifact, prof = Core.Levels [level], Brain.live.artifact or {
    }, Core.prof()
    local artifactData = prof and prof.artifact_data
    if not (type(artifactData) == "table" and artifactData._interval == artifact.interval) and type(artifact.ad) == "table" then
        artifactData = artifact.ad
    end
    local value = type(artifactData) == "table" and artifact.interval ~= nil and artifactData._interval == artifact.interval
    local value2 = value and type(artifactData._completed) == "table" and artifactData._completed [level]
    local hard = type(value2) == "table" and type(value2.difficulty_completed_data) == "table" and value2.difficulty_completed_data.Hard
    local timesCompleted = type(hard) == "table" and tonumber(hard.times_completed) or 0
    local hard = value and type(artifactData._clear_rewards) == "table" and type(artifactData._clear_rewards [level]) == "table" and artifactData._clear_rewards [level].Hard or {
    }
    local count, count2 = 0, 0
    for _, value in pairs(level2 and level2.clear_rewards and level2.clear_rewards.Hard or {
    }) do
        local clears = tonumber(value.clears) or 0
        if clears > count2 then
            count2 = clears
        end
        if clears > timesCompleted and not hard [value._id] then
            local reward = value.reward or {
            }
            count = count + (tonumber(reward.gem_reward) or 0)
            for _, item in ipairs(Utils.list(reward.item)) do
                if type(item) == "table" and item.item_id then
                    count = count + Modes.itemValue(item.item_id, tonumber(item.amount) or 1)
                end
            end
        end
    end
    return timesCompleted, count, count2, hard
end

