function Hunt.fx(weatherNow)
    local info = {
        dmg = 1,
        cd = 1,
        range = 1,
        cost = 1,
        hp = 1,
        speed = 1,
        regen = 0,
        crit = 0,
        kinds = {
        },
        shield = 0,
        fly = 0,
        ice = 0
    }
    if weatherNow == "rain" then
        info.speed = 1.2
    elseif weatherNow == "windy" then
        info.fly, info.speed = 0.2, 1.25
    elseif weatherNow == "snow" then
        info.ice = 0.5
    elseif weatherNow == "downpour" then
        info.range, info.dmg = 0.7, 0.85
    elseif weatherNow == "mana" then
        info.kinds.physical, info.kinds.magic = 100 / 250 - 1, 0.25
    elseif weatherNow == "fire" then
        info.speed, info.noCC = 1.5, true
    elseif weatherNow == "underwater" then
        info.speed = 1.25
    elseif weatherNow == "sandstorm" then
        info.kinds.magic, info.kinds.physical, info.shroud = 100 / 175 - 1, 0.25, 0.2
    elseif weatherNow == "meteor_shower" then
        info.starfall = Hunt.starfall()
    end
    return info
end

function Hunt.starfall()
    local starfall = type(Brain.hunt) == "table" and Brain.hunt.starfall
    if type(starfall) ~= "table" or (tonumber(starfall.runs) or 0) < 1 or not tonumber(starfall.perWave) then
        return nil
    end
    return starfall
end

function Match.noteStar(arg1, arg2)
    Match.stars = Match.stars or setmetatable({
    }, {
        __mode = "k"
    })
    if Match.stars [arg1] then
        return
    end
    Match.stars [arg1] = true
    local wave = Match.wave()
    Match.starRun = Match.starRun or {
        n = 0,
        waves = {
        },
        hpK = {
        }
    }
    local starRun = Match.starRun
    starRun.n = starRun.n + 1
    starRun.waves [wave] = (starRun.waves [wave] or 0) + 1
    local starGolem1 = Match.info and Match.info.cfgById and Match.info.cfgById.star_golem_1
    local ok, res = pcall(Simulator.enemy, Match.info, starGolem1, wave)
    local maxHealth = arg2 and tonumber(arg2.MaxHealth) or 0
    if starGolem1 and ok and res and (res.hp or 0) > 0 and maxHealth > 0 then
        table.insert(starRun.hpK, maxHealth / res.hp)
    end
end

function Hunt.starfallRecord()
    local starRun = Match.starRun
    if not (starRun and starRun.n > 0) then
        return
    end
    local value = math.max(1, Match.wave())
    local ratio = starRun.n / value
    local value2
    if # starRun.hpK > 0 then
        local hpK = table.clone(starRun.hpK)
        table.sort(hpK)
        value2 = hpK [math.floor(# hpK / 2) + 1]
    end
    local starfall = type(Brain.hunt.starfall) == "table" and Brain.hunt.starfall or {
    }
    local runs = (tonumber(starfall.runs) or 0) + 1
    local ratio2 = 1 / math.min(runs, 5)
    Brain.hunt.starfall = {
        runs = runs,
        perWave = starfall.perWave and (starfall.perWave + (ratio - starfall.perWave) * ratio2) or ratio,
        hpK = value2 and (starfall.hpK and (starfall.hpK + (value2 - starfall.hpK) * ratio2) or value2) or starfall.hpK,
        at = os.time()
    }
    local value3, value4
    for waveKey in pairs(starRun.waves) do
        value3 = math.min(value3 or waveKey, waveKey)
        value4 = math.max(value4 or waveKey, waveKey)
    end
    App.log(1, "STARFALL", string.format("%d Star Golems over %d waves (about %.2f a wave, from wave %s to %s), their HP ×%.2f the simulator's for a Star Golem · the simulator plays Starfall with them from now on", starRun.n, value, ratio, tostring(value3), tostring(value4), value2 or 0))
    return {
        n = starRun.n,
        waves = value,
        hpK = value2 and math.floor(value2 * 100 + 0.5) / 100 or nil
    }
end

function Hunt.perWave(i)
    local level = Core.Levels [Hunt.ID]
    local summerPearls = level and level.infinite_resource_rewards and level.infinite_resource_rewards.SummerPearls
    for _, summerPearl in ipairs(summerPearls or {
    }) do
        if i <= (tonumber(summerPearl.wave_up_to) or 0) then
            return tonumber(summerPearl.reward) or 0
        end
    end
    return 0
end

function Hunt.pearlsFrom(arg1, num)
    local count = 0
    for i = arg1, num do
        count = count + Hunt.perWave(i)
    end
    return count
end

function Hunt.board()
    local core = Core.core("Summer2MapBoardCore")
    local prof = Core.prof()
    if not (core and prof) then
        return nil
    end
    local board = core.get_board(LocalPlayer.UserId)
    if not board then
        return nil
    end
    local summer2HuntWins = type(prof._summer2_hunt_wins) == "table" and prof._summer2_hunt_wins or {
    }
    local maps, weathers, summer2MapBoardClaimedLines = summer2HuntWins.maps or {
    }, summer2HuntWins.weathers or {
    }, prof._summer2_map_board_claimed_lines or {
    }
    local count, count2, count3 = 0, 0, 0
    for _, value in ipairs(board) do
        if maps [value] then
            count = count + 1
        end
    end
    for _ in pairs(core.get_completed_lines(board, maps)) do
        count2 = count2 + 1
    end
    for _ in pairs(weathers) do
        count3 = count3 + 1
    end
    return {
        core = core,
        board = board,
        maps = maps,
        weathers = weathers,
        claimed = summer2MapBoardClaimedLines,
        squares = count,
        lines = count2,
        weathersWon = count3,
        total = # core.LINES,
        claimable = core.get_claimable_lines(board,
        maps,
        summer2MapBoardClaimedLines)
    }
end

function Hunt.lineGems()
    return 2000 * Config.pearlValue + 10 * (Core.ITEM_VALUE.star_remnant_limited or 25)
end

function Hunt.firstValue(map, weather)
    local board = Hunt.board()
    if not board then
        return 0, {
        }
    end
    local count, list = 0, {
    }
    local value = map and table.find(board.board, map)
    if value and not board.maps [map] then
        local count2 = 0
        for _, line in ipairs(board.core.LINES) do
            if table.find(line.cells, value) then
                count2 = count2 + 1
            end
        end
        count = count + count2 * Hunt.lineGems() / board.core.SIZE
        table.insert(list, "a new bingo square")
    end
    if weather and weather ~= "clear" and not board.weathers [weather] then
        count = count + (1000 + 5000 * Config.pearlValue + 50 * (Core.ITEM_VALUE.star_remnant_limited or 25)) / Hunt.WEATHERS
        table.insert(list, "a new weather for the quest")
    end
    if not next(board.maps) then
        count = count + 500 + 4500 * Config.pearlValue + 200
        table.insert(list, "the first Explosion Mage")
    end
    return count, list
end

function Hunt.row(rec)
    local event = Brain.live.event
    local simRe = Brain.simRes ["ev:" .. tostring(event.level)]
    local num = simRe and (simRe.won and 50 or tonumber(simRe.wave)) or 50
    local ratio = rec.runs > 0 and rec.coins / rec.runs or Hunt.pearlsFrom(1, num) * Hunt.MULT_GUESS
    local firstValue, firstValue2 = Hunt.firstValue(event.map, event.weather)
    local value = Core.data("Weather") or {
    }
    local info = {
        key = "ev:" .. tostring(event.level),
        kind = "event",
        level = event.level,
        diff = "Hard",
        value = ratio * Config.pearlValue,
        coins = ratio,
        p0 = 0.5,
        rec = rec,
        label = "Summer Hunt"
    }
    local num = 1
    if firstValue > 0 then
        local ok, res = pcall(Modes.winP, info)
        num = ok and Utils.clamp(tonumber(res) or 0.5, 0, 1) or 0.5
        info.value = info.value + firstValue * num
    end
    info.why = string.format("≈%d Summer Pearls a run%s%s", math.floor(ratio), event.weather and value [event.weather] and (" · " .. value [event.weather].name) or "", # firstValue2 > 0 and (" · a win adds " .. table.concat(firstValue2, ", ") .. string.format(" (win ≈%d%%)", math.floor(num * 100 + 0.5))) or "")
    return info
end

