function Adventure.fodderOrder(unitId)
    local count, list, unitId2 = 0, {
    }, unitId
    while unitId2 and Core.Units [unitId2] and not list [unitId2] do
        list [unitId2] = true
        if Adventure.role(unitId2) then
            return nil
        end
        local _, _, tier3 = Adventure.tier(unitId2)
        count = math.max(count, tier3)
        local unit = Core.Units [unitId2]
        unitId2 = unit.evolve and unit.evolve.evolve_unit
    end
    if count >= Adventure.TIER_RANK.A then
        return nil
    end
    local _, tier2 = Adventure.tier(unitId)
    if (tier2 and tier2.overall == "D") or count == Adventure.TIER_RANK.D then
        return 1
    end
    return 2 + count
end

function Adventure.strongest(arg1)
    if Adventure._strong and Adventure._strongN == arg1 and Utils.now() - Adventure._strongAt < 60 then
        return Adventure._strong
    end
    local session = Core.session()
    local list = {
    }
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local ok, res = pcall(Units.score, session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit)
        if ok and tonumber(res) then
            table.insert(list, {
                uuid = ownedUnitKey,
                sc = res
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.sc > arg2.sc
    end)
    local list2 = {
    }
    for i = 1, math.min(arg1, # list) do
        list2 [list [i].uuid] = true
    end
    Adventure._strong, Adventure._strongN, Adventure._strongAt = list2, arg1, Utils.now()
    return list2
end

function Adventure.communityText()
    if not Config.community then
        return "Off (Settings → Community tips)."
    end
    local prof = Core.prof()
    if not prof then
        return "…"
    end
    local list = {
    }
    local function helper(arg1, arg2, arg3)
        local banner = Core.Banners [arg2]
        local list2 = {
        }
        for _, rateupUnit in pairs(banner and banner.rateup_units or {
        }) do
            if type(rateupUnit) == "table" and type(rateupUnit.possible_units_set) == "table" then
                for key in pairs(rateupUnit.possible_units_set) do
                    table.insert(list2, key)
                end
            end
        end
        local list3 = {
        }
        for _, item in ipairs(list2) do
            local tierBest, tierBest2 = Adventure.tierBest(item)
            table.insert(list3, {
                r = tierBest2,
                text = string.format("%s %s%s",
                Units.name(tierBest),
                (Adventure.tier(tierBest)) or "unrated",
                Units.owns(item) and " (you have it)" or "")
            })
        end
        table.sort(list3, function(arg1, arg2)
            return arg1.r > arg2.r
        end)
        local list2 = {
        }
        for _, item in ipairs(list3) do
            table.insert(list2, item.text)
        end
        if # list2 > 0 then
            table.insert(list, string.format("%s (%s): %s", arg1, arg3, table.concat(list2, " · ")))
        end
    end
    helper("April banner", "April2025", "150 AprilCoins a pull")
    helper("Sakamoto banner", "SakamotoEvent", "10 Assassin Tokens a pull")
    helper("Gem banner", "EventClover", "50 gems a pull")
    local list2 = {
    }
    for _, value in ipairs(Units.equipped()) do
        if not Units.isFarm(value.id) and not Units.allyBuff(value.id) then
            local _, types2 = Units.types(value.id)
            if types2 then
                list2 [types2] = true
            end
        end
    end
    local list3, list4 = {
    }, {
    }
    for _, ownedUnit in pairs(prof.collection.owned_units) do
        local tierBest, tierBest2 = Adventure.tierBest(ownedUnit.unit_id)
        if tierBest2 >= 4 and not list4 [tierBest] then
            list4 [tierBest] = true
            local str = ""
            local allyBuff = Units.allyBuff(tierBest)
            if allyBuff then
                local flag = false
                for typeKey in pairs(allyBuff.types or {
                }) do
                    if list2 [typeKey] then
                        flag = true
                    end
                end
                if not flag then
                    for typeKey in pairs(allyBuff.types or {
                    }) do
                        str = string.format(" (buffs %s units: your damage dealers aren't)", typeKey)
                    end
                end
            end
            if tierBest ~= ownedUnit.unit_id then
                str = str .. " (evolve " .. Units.name(ownedUnit.unit_id) .. ")"
            end
            table.insert(list3, {
                r = tierBest2,
                text = Units.name(tierBest) .. " " .. ((Adventure.tier(tierBest)) or "") .. str
            })
        end
    end
    table.sort(list3, function(arg1, arg2)
        return arg1.r > arg2.r
    end)
    local list2 = {
    }
    for i, item in ipairs(list3) do
        if i <= 8 then
            table.insert(list2, item.text)
        end
    end
    if # list2 > 0 then
        table.insert(list, "Yours rated A or better: " .. table.concat(list2, " · "))
    end
    table.insert(list, "The guides rank evolved, fully upgraded units and ignore traits (a strong trait can move a unit a whole tier). " .. "Their advice: save gems and commit to one banner.")
    return table.concat(list, "\n")
end

function Adventure.pullGoal()
    local pullGoal = Config.pullGoal
    if type(pullGoal) ~= "string" or pullGoal == "" or type(Core.Units [pullGoal]) ~= "table" then
        return nil
    end
    local prof = Core.prof()
    if not prof then
        return nil
    end
    local unit = Core.Units [pullGoal]
    local evolveUnit = unit.evolve and unit.evolve.evolve_unit or pullGoal
    local info = {
        id = pullGoal,
        to = evolveUnit,
        coins = Core.cur("AprilCoins"),
        itemCost = 0,
        needCoins = 0
    }
    for _, value in pairs(unit.evolve and unit.evolve.normal and unit.evolve.normal.item_requirement or {
    }) do
        local value2 = Core.SaleEvent [value.item_id]
        if value2 and type(value2.resource_cost) == "table" and value2.resource_cost.id == "AprilCoins" then
            info.item, info.itemCost = value.item_id, tonumber(value2.resource_cost.amount) or 0
        end
    end
    info.haveItem = info.item ~= nil and Adventure.have(info.item) > 0
    local flag, flag2 = FarmHub.hatched [pullGoal] or false, false
    for _, ownedUnit in pairs(prof.collection.owned_units) do
        if ownedUnit.unit_id == pullGoal then
            flag = true
        end
        if ownedUnit.unit_id == evolveUnit then
            flag2 = true
        end
    end
    if flag2 then
        info.step = "done"
    elseif not flag then
        info.step, info.needCoins = "pull", 1
    elseif info.item and not info.haveItem then
        info.step, info.needCoins = "item", math.max(0, info.itemCost - info.coins)
    else
        info.step = "evolve"
    end
    return info
end

function Adventure.goalText()
    local pullGoal = Adventure.pullGoal()
    if not pullGoal then
        return "No main goal set (Settings: pull goal)."
    end
    local prof = Core.prof()
    local text = string.format("%s%s · ", Units.name(pullGoal.to), (Adventure.tier(pullGoal.to)) and (" (tier " .. Adventure.tier(pullGoal.to) .. ")") or "")
    if pullGoal.step == "pull" then
        if not Core.Banners.April2025 then
            return text .. string.format("the April banner isn't in the game right now, so there's nothing to pull %s from. This waits until it comes back.", Units.name(pullGoal.id))
        end
        local aprilFloor = math.max(Config.aprilFloor, pullGoal.haveItem and 0 or pullGoal.itemCost)
        local april2025 = prof and prof.pity_data and prof.pity_data.April2025
        local opensSinceMythic = april2025 and tonumber(april2025.opens_since_mythic)
        return text .. string.format("step 1 of 3: pull %s from the April banner. You have %s AprilCoins: %d ten-pulls above the %s kept for its evolve item. " .. "Each Mythic from this banner is one of 3 limited units (1 in 3 is %s), and one is guaranteed every 200 pulls%s. " .. "The farm plays Fool's Hunt for AprilCoins (worth %.2f gems each to the ranking while this goal needs them)%s.", Units.name(pullGoal.id), Utils.fmt(pullGoal.coins), math.max(0, math.floor((pullGoal.coins - aprilFloor) / 1500)), Utils.fmt(aprilFloor), Units.name(pullGoal.id), opensSinceMythic and string.format(" (%d pulls since the last Mythic)", opensSinceMythic) or "", math.max(Config.aprilValue, Config.goalCoinValue), Config.summonApril and " and pulls 10 at a time" or "; April pulls are off (Units → Summon)")
    elseif pullGoal.step == "item" then
        return text .. string.format("step 2 of 3: you have %s! Its evolve item costs %s AprilCoins in the event shop; you have %s. The farm buys it when the coins are in.", Units.name(pullGoal.id), Utils.fmt(pullGoal.itemCost), Utils.fmt(pullGoal.coins))
    elseif pullGoal.step == "evolve" then
        return text .. "step 3 of 3: its takedowns come from training (it joins easy runs), then smart evolve evolves it."
    end
    return text .. "done, it's yours!"
end

function FarmHub.eventShop()
    local pullGoal = Adventure.pullGoal()
    if not (Config.summonApril and pullGoal and pullGoal.step == "item" and pullGoal.coins >= pullGoal.itemCost and pullGoal.itemCost > 0) then
        return
    end
    if App.req.back.eshop and Utils.now() < App.req.back.eshop then
        return
    end
    local ok, res = App.request("eshop", "buy_item_generic", pullGoal.item, "event", "event_shop", "1")
    local now = Utils.now()
    while Utils.now() - now < 4 and Adventure.have(pullGoal.item) < 1 do
        task.wait(0.25)
    end
    local name = (Core.Items [pullGoal.item] or {
    }).name or pullGoal.item
    if Adventure.have(pullGoal.item) > 0 then
        Spending.add(name, pullGoal.itemCost, "AprilCoins", "evolve item for " .. Units.name(pullGoal.to))
        if App.notify then
            App.notify("Main goal", "Bought " .. name .. " for " .. Units.name(pullGoal.id), "success")
        end
        pcall(Adventure.refresh)
    else
        App.log(1, "SHOP", "event shop refused " .. tostring(pullGoal.item) .. " (" .. tostring(ok and res or "no answer") .. ")")
        App.backoff("eshop", 900)
    end
end

function FarmHub.codes()
    if not Config.codes then
        return App.status("Codes", "off (Settings)")
    end
    local prof = Core.prof()
    if not prof then
        return
    end
    local redeemedCodes = prof.redeemed_codes or {
    }
    local list, list2 = {
    }, {
    }
    for _, code in ipairs(Core.CODES) do
        local code2 = tonumber(Brain.codes [code])
        if redeemedCodes [code] then
            if code2 and code2 > 0 then
                table.insert(list2, code)
                Brain.codes [code] = - 1
            end
        elseif os.time() - (code2 or 0) > 86400 and (code2 or 0) >= 0 then
            Brain.codes [code] = os.time()
            local ok = App.request("code", "redeem_code", code)
            if ok then
                table.insert(list, code)
            end
            task.wait(1)
        end
    end
    if # list2 > 0 then
        App.log(1, "CODES", "the game confirms " .. table.concat(list2, ", "))
    end
    if # list > 0 then
        App.log(1, "CODES", "sent " .. table.concat(list, ", ") .. " (the game confirms a code after the next teleport; one it refuses is tried again tomorrow)")
    end
    App.saveSoon()
    local count = 0
    for _, code in ipairs(Core.CODES) do
        if not redeemedCodes [code] then
            count = count + 1
        end
    end
    App.status("Codes", # list > 0 and ("sent " .. table.concat(list, ", ")) or (count == 0 and "every known code is redeemed ✓" or (count .. " codes not taken yet, trying again tomorrow")))
end

