function Modes.portalPer(portalKey)
    local value = Brain.portalPay [portalKey]
    if value and (tonumber(value.n) or 0) > 0 then
        return tonumber(value.per), true
    end
    local portal = Modes.PORTALS [portalKey]
    local ok, res = pcall(Reports.hiveDrops, portal.level)
    if ok and res and res [portal.item] then
        return res [portal.item], true
    end
    return portal.per, false
end

function Modes.portalDrops(portalKey)
    local value = Brain.portalPay ["drop:" .. portalKey]
    if value and (tonumber(value.n) or 0) > 0 then
        return tonumber(value.per), true
    end
    local portal = Modes.PORTALS [portalKey]
    local ok, res = pcall(Reports.hiveDrops, portal.from)
