Modes._spawns = {
}

function Modes.levelSpawns(arg1, unitIds)
    local arg12 = tostring(arg1)
    local spawn = Modes._spawns [arg12]
    if spawn and os.time() - spawn.at < 3600 then
        return spawn.n
    end
    local count = 0
    pcall(function()
        local level = Core.Levels [arg1]
        local info = Simulator.info(Simulator.slim and Simulator.slim(level) or level, "count:" .. arg12)
        local flag = false
        for configKey, config in pairs(info.configs or {
        }) do
            if unitIds [configKey] or (type(config) == "table" and unitIds [config.unit_id or ""]) then
                flag = true
                break
            end
        end
        if not flag then
            return
        end
        local infReach = info.infinite and math.floor(Modes.infReach("inf:" .. arg12) + 0.5) or info.total
        local function helper(arg1)
            local config = info.configs [arg1]
            return unitIds [arg1] or (type(config) == "table" and unitIds [config.unit_id or ""])
        end
        for i = 1, math.min(infReach or 30, 200) do
            if info.infinite then
                local ok, res = pcall(Core.LU.Infinite.infinite_amt_scale, i, info.ld)
                local count2, count3 = 0, 0
                for configKey, config in pairs(info.configs) do
                    if type(config) == "table" and config.spawn_tier_normal then
                        local ok, res = pcall(Core.LU.Infinite.infinite_get_normal_unit_chance, config, i)
                        res = ok and tonumber(res) or 0
                        count2 = count2 + res
                        if helper(configKey) then
                            count3 = count3 + res
                        end
                    end
                end
                if count2 > 0 then
                    count = count + (ok and tonumber(res) or 10) * count3 / count2
                end
            else
                local item = info.list [i]
                for _, item in ipairs(Utils.list(item and item.wave)) do
                    if helper(item.unit) then
                        count = count + (tonumber(item.amount) or 1)
                    end
                end
            end
        end
        count = math.floor(count + 0.5)
    end)
    Modes._spawns [arg12] = {
        n = count,
        at = os.time()
    }
    return count
end

function Modes.missionValue(arg1)
    local session = Core.session()
    local count, text = 0, nil
    for _, quest in pairs(session and session.quest_handler.quest_profile_data.quests or {
    }) do
        local questInfo = quest.quest_info
        local questClass = questInfo and questInfo.quest_class
        if questClass and questClass.class == "kill_unit_multi" and type(questClass.unit_ids) == "table" then
            local amount = tonumber(questClass.amount) or 0
            local amount2 = amount - (tonumber(quest.quest_progress and quest.quest_progress.amount) or 0)
            if amount2 > 0 then
                local levelSpawns = Modes.levelSpawns(arg1, questClass.unit_ids)
                if levelSpawns > 0 then
                    local gemReward = tonumber(questInfo.quest_reward and questInfo.quest_reward.gem_reward) or 0
                    for _, value in pairs(questInfo.quest_reward and questInfo.quest_reward.item or {
                    }) do
                        if type(value) == "table" and value.item_id then
                            gemReward = gemReward + Modes.itemValue(value.item_id, tonumber(value.max_amount or value.amount or value.min_amount) or 1)
                        end
                    end
                    count = count + gemReward * math.min(1, levelSpawns / amount2)
                    text = string.format("%s: %s/%s, ≈%s a run", tostring(questInfo.quest_name), Utils.fmt(amount - amount2), Utils.fmt(amount), Utils.fmt(math.min(levelSpawns, amount2)))
                end
            end
        end
    end
    return count, text
end

function Modes.portalKinds()
    if Modes._kinds then
        return Modes._kinds
    end
    local list = {
    }
    for itemKey, item in pairs(Core.Items) do
        if type(item) == "table" and type(item.usage) == "table" and item.usage.type == "open_portal" then
            local list2 = {
            }
            if item.usage.level_id then
                table.insert(list2, item.usage.level_id)
            end
            if type(item._unique_portal_levels) == "table" then
                for uniquePortalLevelKey in pairs(item._unique_portal_levels) do
                    table.insert(list2, uniquePortalLevelKey)
                end
            end
            table.sort(list2)
            local list3 = {
            }
            local function helper(arg1, arg2)
                if type(arg1) ~= "table" or arg2 > 4 then
                    return
                end
                if type(arg1.item_id) == "string" then
                    list3 [arg1.item_id] = true
                end
                for _, value in pairs(arg1) do
                    helper(value, arg2 + 1)
                end
            end
            for _, item in ipairs(list2) do
                helper((Core.Levels [item] or {
                }).rewards, 0)
            end
            if Modes.PORTALS [itemKey] then
                list3 [Modes.PORTALS [itemKey].item] = true
            end
            table.insert(list, {
                pid = itemKey,
                name = item.name or itemKey,
                rarity = item.rarity,
                levels = list2,
                drops = list3
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        if arg1.name ~= arg2.name then
            return arg1.name < arg2.name
        end
        return arg1.pid < arg2.pid
    end)
    Modes._kinds = list
    return list
end

