function Modes.portalsHeldData(pid)
    local prof = Core.prof()
    local uniqueItems = (prof.inventory and prof.inventory.unique_items) or prof.unique_items or {
    }
    local list = {
    }
    for uniqueItemKey, uniqueItem in pairs(uniqueItems) do
        if type(uniqueItem) == "table" and uniqueItem.item_id == pid then
            local uniquePortalData = type(uniqueItem._unique_item_data) == "table" and uniqueItem._unique_item_data._unique_portal_data or {
            }
            local ctl = type(uniquePortalData._ctl) == "table" and uniquePortalData._ctl or {
            }
            local list2 = {
            }
            for _, levelmodifier in pairs(type(ctl._levelmodifiers) == "table" and ctl._levelmodifiers or {
            }) do
                if type(levelmodifier) == "table" and levelmodifier.id then
                    table.insert(list2, tostring(levelmodifier.id))
                end
            end
            table.insert(list, {
                uuid = uniqueItem.uuid or uniqueItemKey,
                pid = pid,
                level = uniquePortalData.level_id,
                tier = tonumber(uniquePortalData.portal_depth) or 0,
                diff = tonumber(uniquePortalData.difficulty_scale) or 1,
                reward = tonumber(uniquePortalData._portal_reward_scale) or 1,
                lanes = tonumber(uniquePortalData._lanes),
                host = tonumber(uniquePortalData._host_star_remnants) or 0,
                map = uniquePortalData._override_map,
                weak = ctl._weak_against or uniquePortalData._weak_against,
                strong = ctl._strong_against or uniquePortalData._strong_against,
                mods = list2
            })
        end
    end
    table.sort(list, function(item, item2)
        return item.uuid < item2.uuid
    end)
    return list
end

function Modes.portalMod(item)
    local info, flag = {
        weak = {
        },
        strong = {
        },
        res = {
        }
    }, false
    for _, value in pairs(type(item.weak) == "table" and item.weak or {
    }) do
        local damageType = type(value) == "table" and value.damage_type or (type(value) == "string" and value) or nil
        if damageType and damageType ~= "" then
            flag = true
            info.weak [damageType] = Modes.weakAmp(type(value) == "table" and value.amplification)
        end
    end
    for _, value in pairs(type(item.strong) == "table" and item.strong or {
    }) do
        local damageType = type(value) == "table" and value.damage_type or (type(value) == "string" and value) or nil
        local amplification = type(value) == "table" and tonumber(value.amplification)
        if damageType and damageType ~= "" then
            flag = true
            if amplification and amplification < 1 then
                info.res [damageType] = amplification
            else
                info.strong [damageType] = true
            end
        end
    end
    return flag and info or nil
end

function Modes.weakAmp(amplification)
    amplification = tonumber(amplification)
    if not amplification then
        return 1.5
    end
    return amplification < 1 and 1 + amplification or amplification
end

function Modes.portalFit(item, equipped)
    local portalMod = Modes.portalMod(item)
    if not portalMod then
        return 1
    end
    local count, count2 = 0, 0
    for _, value in ipairs(equipped or {
    }) do
        if not Units.isFarm(value.id) and not Units.allyBuff(value.id) then
            local ok, res = pcall(Units.score, value.u)
            res = ok and tonumber(res) or 0
            count = count + res
            count2 = count2 + res * Units.elem(value.id, portalMod)
        end
    end
    return count > 0 and count2 / count or 1
end

function Modes.portalRows()
    local list = {
    }
    local pickPortal = Config.pickPortal or "smart"
    if pickPortal == "off" or Config.portals == false then
        return list
    end
    local badPortal = FarmHub.badPortal or {
    }
    local testTeam = Brain.testTeam
    local function helper(arg1)
        for _, portalKind in ipairs(Modes.portalKinds()) do
            local arg12 = arg1 or pickPortal == portalKind.pid or (testTeam and (testTeam.left or 0) > 0 and testTeam.pid == portalKind.pid)
            if arg12 or pickPortal == "smart" then
                local portalsHeld = Modes.portalsHeld(portalKind.pid)
                local list2 = {
                }
                for dropKey in pairs(portalKind.drops) do
                    if (Brain.goalNeed [dropKey] or 0) > 0 then
                        table.insert(list2, dropKey)
                    end
                end
                table.sort(list2)
                if # portalsHeld > 0 and (arg12 or # list2 > 0) then
                    local equipped = Units.equipped()
                    local list3, list4 = {
                    }, {
                    }
                    for _, item in ipairs(Modes.portalsHeldData(portalKind.pid)) do
                        list4 [item.tier] = (list4 [item.tier] or 0) + 1
                        item.fit = Modes.portalFit(item, equipped)
                        local item2 = list3 [item.tier]
                        local flag = not item2 or (badPortal [item.uuid] or 0) < (badPortal [item2.uuid] or 0) or ((badPortal [item.uuid] or 0) == (badPortal [item2.uuid] or 0) and item.fit > item2.fit)
                        if flag then
                            list3 [item.tier] = item
                        end
                    end
                    for itemKey, item in pairs(list3) do
                        local level = item.level or Modes.portalLevel(item.uuid) or portalKind.levels [1]
                        if level and Core.Levels [level] and Modes.open(level) then
                            local overrideGemReward = tonumber(Core.Levels [level]._override_gem_reward) or 0
                            local overrideGemReward2, list3 = overrideGemReward, {
                            }
                            local portal = Modes.PORTALS [portalKind.pid]
                            for _, item in ipairs(list2) do
                                local num, flag = 1, true
                                if portal and portal.item == item then
                                    num, flag = Modes.portalPer(portalKind.pid)
                                end
                                overrideGemReward2 = overrideGemReward2 + Modes.itemValue(item, num)
                                table.insert(list3, string.format("≈%s %s a run%s", Utils.fmt(num), (Core.Items [item] or {
                                }).name or item, flag and "" or " (a guess until one is played)"))
                            end
                            local ok, res = pcall(Reports.hiveDrops, level)
                            for key, value in pairs(ok and type(res) == "table" and res or {
                            }) do
                                if not table.find(list2, key) then
                                    overrideGemReward2 = overrideGemReward2 + Modes.itemValue(key, tonumber(value) or 0)
                                end
                            end
                            overrideGemReward2 = overrideGemReward2 * item.reward + item.host * Modes.itemValue("star_remnant_limited", 1)
                            local info = {
                                key = itemKey > 0 and ("pt:" .. level .. ":t" .. itemKey) or ("pt:" .. level),
                                kind = "portal",
                                level = level,
                                diff = "Hard",
                                portal = item.uuid,
                                first = false,
                                picked = arg12 or nil,
                                value = overrideGemReward2,
                                p0 = Modes.PRIOR_WIN.hard,
                                label = Modes.levelName(level) .. (itemKey > 0 and string.format(" (Tier %d)",
                                itemKey) or ""),
                                tier = itemKey,
                                mod = Modes.portalMod(item),
                                why = string.format("%s%s: %s%s · you hold %d%s",
                                arg1 and "none left of your pick, so your other portals · " or (arg12 and "your pick · " or ""),
                                portalKind.name,
                                # list3 > 0 and table.concat(list3,
                                ", ") or (overrideGemReward .. " gems a run"),
                                itemKey > 0 and string.format(" · Tier %d%s, enemies ×%.1f, rewards ×%.1f",
                                itemKey,
                                item.lanes and string.format(" (%d lane%s)",
                                item.lanes,
                                item.lanes == 1 and "" or "s") or "",
                                item.diff,
                                item.reward) or "",
                                list4 [itemKey],
                                item.host > 0 and string.format(" · the host gets %d Limited Star Remnant%s",
                                item.host,
                                item.host == 1 and "" or "s") or "")
                            }
                            if item.diff ~= 1 or item.map or item.lanes then
                                local level2 = table.clone(Core.Levels [level])
                                level2._lobby_difficulty_scale = item.diff
                                if item.map then
                                    level2.map = item.map
                                end
                                if item.lanes then
                                    level2._portal_lanes = item.lanes
                                end
                                info.ldOverride = level2
                            end
                            if # item.mods > 0 then
                                info.why = info.why .. " · modifiers: " .. table.concat(item.mods, ", ")
                            end
                            table.insert(list, info)
                        end
                    end
                end
            end
        end
    end
    helper(false)
    if # list == 0 and ((pickPortal ~= "smart" and # Modes.portalsHeld(pickPortal) == 0) or Config.onlyPortals) then
        helper(true)
    end
    return list
end

function Modes.portalBonus(arg1)
    if Config.pickPortal == "off" or Config.portals == false then
        return 0, nil
    end
    for portalKey, portal in pairs(Modes.PORTALS) do
        if portal.from == arg1 and (Brain.goalNeed [portal.item] or 0) > 0 then
            local portalDrops, portalDrops2 = Modes.portalDrops(portalKey)
            local portalPer = Modes.portalPer(portalKey)
            return portalDrops * Modes.itemValue(portal.item, portalPer), string.format("≈%s %s a run%s, for %s", Utils.fmt(portalDrops), (Core.Items [portalKey] or {
            }).name or portalKey, portalDrops2 and "" or " (a guess)", (Core.Items [portal.item] or {
            }).name or portal.item)
        end
    end
    return 0, nil
end

function Adventure.goals()
    local session = Core.session()
    if not session then
        return {
        }
    end
    local equipped = Units.equipped()
    local huge = math.huge
    for _, value in ipairs(equipped) do
        if not Units.isFarm(value.id) and not Units.allyBuff(value.id) then
            local ok, res = pcall(Units.score, value.u)
            if ok then
                huge = math.min(huge, res)
            end
        end
    end
    local list = {
    }
    for _, item in ipairs(equipped) do
        list [item.uuid] = true
    end
    local evolveUnit = Config.autoEvolve and Config.evolveUnit ~= "" and Config.evolveUnit or nil
    local list2 = {
    }
    for _, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and unit.evolve and unit.evolve.evolve_unit and not unit.evolve.hide_from_ui and Core.Units [unit.evolve.evolve_unit] then
            local ok, res = pcall(Units.score, session.collection:get_unit_by_uuid(ownedUnit.uuid) or ownedUnit)
            res = (ok and res or 0) + (list [ownedUnit.uuid] and 0.5 or 0) + (ownedUnit.uuid == evolveUnit and 1e30 or 0)
            if not list2 [ownedUnit.unit_id] or res > list2 [ownedUnit.unit_id].sc then
                list2 [ownedUnit.unit_id] = {
                    u0 = ownedUnit,
                    sc = res
                }
            end
        end
    end
    local list = {
    }
    local list3 = {
    }
    for _, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        list3 [ownedUnit.unit_id] = true
    end
    for _, item in pairs(list2) do
        local u0 = item.u0
        local unit = Core.Units [u0.unit_id]
        if not list3 [unit.evolve.evolve_unit] or u0.uuid == evolveUnit then
            local shiny = u0.shiny and unit.evolve.shiny or unit.evolve.normal
            local flag, list2, list3 = true, {
            }, {
            }
            for _, unitData in pairs(shiny and shiny.unit_requirement or {
            }) do
                local amount = (tonumber(unitData.amount) or 1) - (unitData.unit_id == u0.unit_id and 1 or 0)
                if amount > 0 then
                    local copyCount = # Adventure.copies(unitData.unit_id, unitData.shiny, u0.uuid)
                    if copyCount < amount then
                        flag = false
                        table.insert(list3, {
                            copies = unitData.unit_id,
                            have = copyCount,
                            need = amount
                        })
                    end
                    table.insert(list2, {
                        id = unitData.unit_id,
                        amount = amount,
                        shiny = unitData.shiny and true or nil
                    })
                end
            end
            local list4 = {
            }
            for _, value in pairs(shiny and shiny.item_requirement or {
            }) do
                table.insert(list4, {
                    id = value.item_id,
                    amount = tonumber(value.amount) or 1
                })
            end
            local value = u0.uuid == evolveUnit or nil
            if shiny and (flag or value) then
                local unitObj = session.collection:get_unit_by_uuid(u0.uuid) or u0
                local info = {
                    unit_id = unit.evolve.evolve_unit,
                    uuid = "evo:" .. tostring(unitObj.uuid),
                    xp = unitObj.xp,
                    traits = unitObj.traits,
                    trait_stats = unitObj.trait_stats,
                    further_modifiers = unitObj.further_modifiers
                }
                local ok, res = pcall(Units.score, unitObj)
                local ok2, res2 = pcall(Units.score, info)
                res, res2 = ok and res or 0, ok2 and res2 or 0
                local ok, res3 = pcall(Core.USC.calculate_xp, unit.evolve.evolve_unit, 100)
                local ok2, res4 = pcall(Units.score, {
                    unit_id = unit.evolve.evolve_unit,
                    uuid = "evo100:" .. tostring(unitObj.uuid),
                    xp = math.max(tonumber(unitObj.xp) or 0,
                    ok and tonumber(res3) or 0),
                    traits = unitObj.traits,
                    trait_stats = unitObj.trait_stats,
                    further_modifiers = unitObj.further_modifiers
                })
                res4 = ok2 and tonumber(res4) or res2
                local hidden = Units.hidden(u0.unit_id) or Units.hidden(unit.evolve.evolve_unit)
                local list5, count, flag, flag2 = {
                }, 0, false, true
                local killsShort = Adventure.killsShort(unitObj, shiny)
                if killsShort then
                    flag2 = false
                    table.insert(list5, {
                        takedown = true,
                        what = killsShort.what,
                        have = killsShort.have,
                        need = killsShort.need
                    })
                end
                for _, item in ipairs(list3) do
                    flag2 = false
                    table.insert(list5, item)
                end
                for _, value in pairs(shiny.item_requirement or {
                }) do
                    local planItem = Adventure.planItem(value.item_id, value.amount or 1)
                    if not planItem.done then
                        flag2 = false
                        table.insert(list5, planItem)
                        if planItem.unknown then
                            flag = true
                        elseif planItem.farmNeed > 0 then
                            planItem.best = Adventure.bestSource(planItem.levels)
                            count = count + planItem.farmNeed / math.max(0.1, planItem.best and planItem.best.per or 1)
                        end
                    end
                end
                local _, _, tier3 = Adventure.tier(unit.evolve.evolve_unit)
                if res2 > res or hidden or value then
                    table.insert(list, {
                        uuid = u0.uuid,
                        from = u0.unit_id,
                        to = unit.evolve.evolve_unit,
                        scoreFrom = res,
                        scoreTo = res2,
                        scoreFull = res4,
                        gain = hidden and 0 or res2 - res,
                        pinned = value,
                        intoTeam = value or (not hidden and res2 > huge) or (hidden and tier3 >= Adventure.TIER_RANK.S),
                        ready = flag2,
                        unknown = flag,
                        hidden = hidden or nil,
                        rating = Adventure.tierText(unit.evolve.evolve_unit),
                        tierRank = tier3,
                        plans = list5,
                        runs = count,
                        items = list4,
                        eats = list2
                    })
                end
            end
        end
    end
    table.sort(list, function(arg1, arg2)
        if (arg1.pinned or false) ~= (arg2.pinned or false) then
            return arg1.pinned or false
        end
        local flag, flag2 = (arg1.hidden and not arg1.intoTeam) or false, (arg2.hidden and not arg2.intoTeam) or false
        if flag ~= flag2 then
            return not flag
        end
        if arg1.ready ~= arg2.ready then
            return arg1.ready
        end
        if arg1.unknown ~= arg2.unknown then
            return not arg1.unknown
        end
        if arg1.intoTeam ~= arg2.intoTeam then
            return arg1.intoTeam
        end
        return arg1.gain / math.max(1, arg1.runs) > arg2.gain / math.max(1, arg2.runs)
    end)
    return list
end

function Adventure.text(goal)
    local list = {
    }
    for _, plan in ipairs(goal.plans) do
        local name = (Core.Items [plan.item] or {
        }).name or plan.item
        if plan.takedown then
            table.insert(list, string.format("%s %s/%s (it earns them on your team)", plan.what, Utils.fmt(plan.have), Utils.fmt(plan.need)))
        elseif plan.copies then
            table.insert(list, string.format("spare copies of %s %d/%d (unlocked, from summons)", Units.name(plan.copies), plan.have, plan.need))
        elseif plan.unknown then
            table.insert(list, name .. ": source unknown (event/portal)")
        elseif plan.portal then
            local portal = Modes.PORTALS [plan.portal]
            table.insert(list, string.format("%s %d/%d from %s (you hold %d; %s drops them)", name, plan.have, plan.need, (Core.Items [plan.portal] or {
            }).name or plan.portal, # Modes.portalsHeld(plan.portal), Modes.levelName(portal.from)))
        elseif plan.eventShop then
            table.insert(list, string.format("%s from the event shop: %s/%s %s", name, Utils.fmt(Core.cur(plan.currency)), Utils.fmt(plan.cost), tostring(plan.currency)))
        elseif plan.shopKey then
            table.insert(list, string.format("%s from the raid shop: %d/%d %s", name, Adventure.have(plan.costItem), plan.cost * (plan.need - plan.have), (Core.Items [plan.costItem] or {
            }).name or plan.costItem))
        else
            table.insert(list, string.format("%s %d/%d", name, plan.have, plan.need))
        end
    end
    local str = ""
    local value
    for _, plan in ipairs(goal.plans) do
        if plan.levels and plan.levels [1] then
            value = plan
            break
        end
    end
    local best = value and (value.best or value.levels [1])
    if best then
        str = string.format(" · farm %s (≈%.0f a run, ≈%d runs)", Modes.levelName(best.level), best.per, math.ceil(goal.runs))
    end
    local str2 = goal.hidden and "strength unknown (the game shows its upgrades only in a match)" or string.format("score %s → %s", Utils.fmt(goal.scoreFrom), Utils.fmt(goal.scoreTo))
    return string.format("%s → %s · %s%s%s · %s%s", Units.name(goal.from), Units.name(goal.to), str2, goal.intoTeam and " (joins your team)" or "", goal.rating and (" · " .. goal.rating) or "", goal.ready and "ready to evolve" or table.concat(list, "; "), goal.ready and "" or str)
end

function Adventure.refresh()
    local goals = Adventure.goals()
    local goals2 = table.clone(goals)
    table.sort(goals2, function(item, item2)
        local tierRank, tierRank2 = tonumber(item.tierRank) or 0, tonumber(item2.tierRank) or 0
        if tierRank ~= tierRank2 then
            return tierRank > tierRank2
        end
        local scoreFull, scoreFull2 = tonumber(item.scoreFull) or 0, tonumber(item2.scoreFull) or 0
        if scoreFull ~= scoreFull2 then
            return scoreFull > scoreFull2
        end
        return tostring(item.uuid) < tostring(item2.uuid)
    end)
    Brain.goalsTop = {
    }
    for i, goal in ipairs(goals2) do
        if i <= 10 or goal.pinned then
            table.insert(Brain.goalsTop, {
                uuid = goal.uuid,
                from = goal.from,
                to = goal.to,
                ready = goal.ready,
                intoTeam = goal.intoTeam,
                unknown = goal.unknown,
                hidden = goal.hidden,
                pinned = goal.pinned,
                text = Adventure.text(goal)
            })
        end
    end
    Brain.goals = {
    }
    table.clear(Brain.goalItems)
    table.clear(Brain.goalNeed)
    local count = 0
    local pinned = goals [1] and goals [1].pinned
    for _, goal in ipairs(goals) do
        table.insert(Brain.goals, {
            uuid = goal.uuid,
            from = goal.from,
            to = goal.to,
            ready = goal.ready,
            intoTeam = goal.intoTeam,
            unknown = goal.unknown,
            hidden = goal.hidden,
            tierRank = goal.tierRank,
            text = Adventure.text(goal),
            gain = goal.gain,
            runs = goal.runs,
            plans = goal.plans,
            items = goal.items,
            eats = goal.eats,
            scoreFrom = goal.scoreFrom,
            scoreTo = goal.scoreTo,
            pinned = goal.pinned
        })
        if not goal.ready and (goal.pinned or (not pinned and Config.goals and not goal.unknown and (not goal.hidden or goal.intoTeam) and (goal.intoTeam or count == 0) and count < 2)) then
            count = count + 1
            for _, plan in ipairs(goal.plans) do
                if plan.farm and plan.farmNeed > 0 then
                    local ratio = Config.goalValue * (goal.intoTeam and 1 or 0.4) / (count == 1 and 1 or 2) / math.max(1, plan.farmNeed)
                    Brain.goalItems [plan.farm] = math.max(Brain.goalItems [plan.farm] or 0, ratio)
                    Brain.goalNeed [plan.farm] = math.max(Brain.goalNeed [plan.farm] or 0, plan.farmNeed)
                end
            end
        end
        if # Brain.goals >= 12 then
            break
        end
    end
    App.saveSoon()
    return goals
end

function Adventure.buyShopGoals()
    if not Config.raidShopGoals then
        return
    end
    for _, goal in ipairs(Brain.goals) do
        for _, plan in ipairs(goal.plans or {
        }) do
            if plan.shopKey and plan.costItem and Adventure.have(plan.item) < plan.need and Adventure.have(plan.costItem) >= plan.cost then
                local have = Adventure.have(plan.costItem)
                local ok, res = App.request("rshop", "buy_raidshop_shop_item", plan.shopKey, "1")
                local now = Utils.now()
                while Utils.now() - now < 3 and Adventure.have(plan.costItem) >= have do
                    task.wait(0.2)
                end
                if ok and Adventure.have(plan.costItem) < have then
                    Spending.add((Core.Items [plan.item] or {
                    }).name or plan.item, plan.cost, (Core.Items [plan.costItem] or {
                    }).name or plan.costItem, "for " .. Units.name(goal.to))
                    if App.notify then
                        App.notify("Goals", string.format("Bought %s for %s (Units → Goals)", (Core.Items [plan.item] or {
                        }).name or plan.item, Units.name(goal.from)), "success")
                    end
                    return true
                else
                    App.log(1, "SHOP", "raid shop refused " .. tostring(plan.shopKey) .. " (" .. tostring(res) .. ")")
                    App.backoff("rshop", 900)
                end
                return
            end
        end
    end
end

function Adventure.lbText()
    local session = Core.session()
    if not session then
        return "…"
    end
    local lb = Brain.lb
    local have = Adventure.have("divine_wish")
    local list = {
    }
    for _, item in ipairs(Units.equipped()) do
        list [item.uuid] = true
    end
    local count, count2 = 0, 0
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and (unit.rarity == "Mythic" or unit.rarity == "Secret") and not unit._event_unit and not list [ownedUnitKey] then
            local ok, res, res2 = pcall(Core.USC.is_unit_good_for_fusion, {
                uuid = "x"
            }, ownedUnit)
            res2 = (ok and res) and (tonumber(res2) or 1) or 0
            if ownedUnit._locked then
                count2 = count2 + res2
            else
                count = count + res2
            end
        end
    end
    local value, value2
    for _, value3 in ipairs(Units.equipped()) do
        local currentLimitBreak = value3.u.further_modifiers and value3.u.further_modifiers.limit_break and value3.u.further_modifiers.limit_break.current_limit_break or 0
        if currentLimitBreak < 1 and not Units.isFarm(value3.id) then
            local ok, res = pcall(Units.score, value3.u)
            if ok and (not value2 or res > value2) then
                value, value2 = value3, res
            end
        end
    end
    local requirement = lb and tonumber(lb.requirement) or 12
    return string.format("Best target: %s (your strongest unit; level cap 100 → 110 ≈ +20%% damage after levelling, and +5%% damage for your whole team). " .. "Needs %d fuel points: you have %d in unlocked Mythic/Secret units (+%d in locked ones) and %d Divine Wish. " .. "It destroys the fuel units, so the farm never does it — the Unit Fusion NPC does it when you choose.", value and Units.name(value.id) or "—", requirement, count, count2, have)
end
Strategy.LOG = "POWER"

function Strategy.traitName(trait, trait2)
    if not trait then
        return "no trait"
    end
    local traitInfo = Core.traitInfo(trait)
    local name = traitInfo and traitInfo.name or tostring(trait)
    return name .. ((trait2 and tostring(trait2) ~= "1") and (" " .. tostring(trait2)) or "")
end

function Strategy.role(unitId)
    if Units.isFarm(unitId) then
        return "farm"
    elseif Units.allyBuff(unitId) then
        return "buffer"
    end
    return "carry"
end
Strategy._salt = 0

function Strategy.whatIf(unitData, arg2)
    Strategy._salt = Strategy._salt + 1
    local list = {
    }
    for key, value in pairs(unitData) do
        list [key] = value
    end
    list.uuid = "what:" .. Strategy._salt .. ":" .. tostring(unitData.uuid)
    for key, value in pairs(arg2 or {
    }) do
        list [key] = value
    end
    return list
end

function Strategy.base(unitData)
    return Strategy.score(Strategy.whatIf(unitData, {
    }))
end

function Strategy.score(whatIf)
    local ok, res = pcall(Units.score, whatIf)
    return (ok and tonumber(res)) or 0
end

function Strategy.level(unitObj)
    local ok, res = pcall(Core.USC.calculate_level, unitObj.unit_id, tonumber(unitObj.xp) or 0)
    return (ok and tonumber(res)) or 1
end

function Strategy.cap(unitObj)
    local ok, res = pcall(Core.USC.get_max_level, unitObj)
    return (ok and tonumber(res)) or 100
end

function Strategy.xpFor(unitId, cap)
    local ok, res = pcall(Core.USC.calculate_xp, unitId, cap)
    return (ok and tonumber(res)) or 0
end

function Strategy.lb(unitObj)
    local furtherModifiers = unitObj.further_modifiers
    return (furtherModifiers and furtherModifiers.limit_break and tonumber(furtherModifiers.limit_break.current_limit_break)) or 0
end

function Strategy.share(unitId)
    local value = Brain.str.share [unitId]
    if value and (Brain.str.shareN or 0) >= 3 then
        return math.max(0.05, value)
    end
    local count, count2 = 0, 0
    for _, value in ipairs(Units.equipped()) do
        if not Units.isFarm(value.id) then
            local score = Strategy.score(value.u)
            count = count + score
            if value.id == unitId then
                count2 = score
            end
        end
    end
    return math.max(0.05, count > 0 and count2 / count or 0.1)
end

function Strategy.learn(arg1, arg2)
    Brain.str.shareN = (Brain.str.shareN or 0) + 1
    local value = math.max(0.1, 1 / Brain.str.shareN)
    for _, value2 in ipairs(arg2 or {
    }) do
        if value2.id and not Units.isFarm(value2.id) then
            local value3 = arg1 [value2.id] or 0
            local value4 = Brain.str.share [value2.id]
            Brain.str.share [value2.id] = value4 and (value4 + (value3 - value4) * value) or value3
        end
    end
    App.saveSoon()
end

function Strategy.core(arg1)
    local session = Core.session()
    if not session then
        return Brain.str.core or {
        }
    end
    local list = {
    }
    if type(Brain.savedTeam) == "table" and # Brain.savedTeam > 0 then
        for _, value in ipairs(Brain.savedTeam) do
            local unitObj = session.collection:get_unit_by_uuid(value)
            if unitObj then
                table.insert(list, {
                    uuid = value,
                    id = unitObj.unit_id
                })
            end
        end
    end
    if # list == 0 then
        for _, unit in ipairs(Units.equipped()) do
            table.insert(list, {
                uuid = unit.uuid,
                id = unit.id
            })
        end
    end
    local list2 = {
    }
    for _, item in ipairs(list) do
        table.insert(list2, item.uuid)
    end
    table.sort(list2)
    local joined = table.concat(list2, ",")
    if not arg1 and # (Brain.str.core or {
    }) >= 6 and os.time() - (tonumber(Brain.str.coreAt) or 0) < (Config.teamCoreDays or 7) * 86400 then
        if Brain.str.teamSig == joined then
            return Brain.str.core
        end
        if Brain.str.pendingSig ~= joined then
            Brain.str.pendingSig, Brain.str.pendingAt = joined, os.time()
            return Brain.str.core
        end
        if os.time() - (tonumber(Brain.str.pendingAt) or 0) < 600 then
            return Brain.str.core
        end
    end
    Brain.str.pendingSig, Brain.str.pendingAt = nil, nil
    local list2, list3 = {
    }, {
    }
    for _, item in ipairs(list) do
        table.insert(list2, item.uuid)
        list3 [item.id] = true
    end
    for _, value in ipairs({
        "evolveUnit",
        "fuseUnit",
        "focusDone"
    }) do
        local value2 = Config [value]
        local unitObj = value2 ~= "" and session.collection:get_unit_by_uuid(value2)
        if unitObj and not table.find(list2, value2) then
            table.insert(list2, value2)
            list3 [unitObj.unit_id] = true
        end
    end
    local list = {
    }
    for _, value in pairs(Brain.simTeam or {
    }) do
        if type(value) == "table" and os.time() - (tonumber(value.at) or 0) < 7 * 86400 then
            for _, name in ipairs(value.names or {
            }) do
                list [name] = (list [name] or 0) + 1
            end
        end
    end
    local list4 = {
    }
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and (unit.rarity == "Mythic" or unit.rarity == "Secret") and not list3 [ownedUnit.unit_id] and Units.rows(ownedUnit.unit_id) and not Units.hidden(ownedUnit.unit_id) and not Units.isFarm(ownedUnit.unit_id) and not Units.allyBuff(ownedUnit.unit_id) then
            local unitObj = session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit
            table.insert(list4, {
                uuid = ownedUnitKey,
                id = ownedUnit.unit_id,
                k = (list [Units.name(ownedUnit.unit_id)] or 0) * 1e12 + Strategy.score(unitObj)
            })
        end
    end
    table.sort(list4, function(item, item2)
        if item.k ~= item2.k then
            return item.k > item2.k
        end
        return item.uuid < item2.uuid
    end)
    for _, item in ipairs(list4) do
        if # list2 >= 8 then
            break
        end
        if not list3 [item.id] then
            table.insert(list2, item.uuid)
            list3 [item.id] = true
        end
    end
    Brain.str.core, Brain.str.coreAt, Brain.str.teamSig = list2, os.time(), joined
    local list = {
    }
    for _, item in ipairs(list2) do
        local unitObj = session.collection:get_unit_by_uuid(item)
        if unitObj then
            table.insert(list, Units.name(unitObj.unit_id))
        end
    end
    App.log(1, Strategy.LOG, "core units: " .. table.concat(list, ", "))
    App.saveSoon()
    return list2
end

function Strategy.gainXp(unitObj, count)
    local xp, xpFor = tonumber(unitObj.xp) or 0, Strategy.xpFor(unitObj.unit_id, Strategy.cap(unitObj))
    local value = math.max(0, xpFor - xp)
    if value <= 0 or (count or 0) <= 0 then
        return 0, 0
    end
    local count2 = math.min(count, value)
    local base = Strategy.base(unitObj)
    if base <= 0 then
        return 0, count2
    end
    return Strategy.share(unitObj.unit_id) * (Strategy.score(Strategy.whatIf(unitObj, {
        xp = xp + count2
    })) / base - 1) * 100, count2
end

function Strategy.gainFuse(unitObj)
    if Strategy.lb(unitObj) >= 1 then
        return 0
    end
    local base = Strategy.base(unitObj)
    if base <= 0 then
        return 0
    end
    local whatIf = Strategy.whatIf(unitObj, {
        xp = math.max(tonumber(unitObj.xp) or 0,
        Strategy.xpFor(unitObj.unit_id,
        110)),
        further_modifiers = {
            limit_break = {
                current_limit_break = 1
            }
        }
    })
    return Strategy.share(unitObj.unit_id) * (Strategy.score(whatIf) / base - 1) * 100 + 5
end
Strategy.MAX_RELICS = 6
Strategy.RELIC_MOVE_GAIN = 0.5
Strategy.RELIC_SETTLED_GAIN = 2

function Strategy.relicBar()
    if Brain.str.relicTeam == nil or Brain.str.relicTeam == Modes.teamSig() then
        return Strategy.RELIC_SETTLED_GAIN
    end
    return Strategy.RELIC_MOVE_GAIN
end

function Strategy.relicWorth(u, itemByUuid)
    local uniqueRelicData = itemByUuid._unique_item_data and itemByUuid._unique_item_data._unique_relic_data
    if not uniqueRelicData then
        return 0
    end
    local item = Core.Items [itemByUuid.item_id] or {
    }
    local types, types2 = Units.types(u.unit_id)
    if item.main_damage_type and item.main_damage_type ~= "both" and item.main_damage_type ~= types2 then
        return 0
    end
    local count, count2 = 0, 0
    for _, coreDamageTypeBuff in pairs(uniqueRelicData._core_damage_type_buffs or {
    }) do
        if types [coreDamageTypeBuff.damage_type] then
            count = count + (tonumber(coreDamageTypeBuff.mul) or 0) + (tonumber(coreDamageTypeBuff.add_upg) or 0) * 0.01 + (tonumber(coreDamageTypeBuff.pen) or 0) * 0.001
            count2 = count2 + (tonumber(coreDamageTypeBuff.crit) or 0)
        end
    end
    count = count + count2 * 0.5
    local rows = Units.rows(u.unit_id)
    local row = rows and rows [rows.max]
    local value = (row and tonumber(row.cd) or 0) * Units.mult(u, "attack_cooldown")
    for _, uniqueRelicEffect in pairs(uniqueRelicData._unique_relic_effects or {
    }) do
        local params = type(uniqueRelicEffect.params) == "table" and uniqueRelicEffect.params or {
        }
        if uniqueRelicEffect.id == "hourglass_relic" then
            local ratio = math.min(1, (tonumber(params.extra_damage) or 0) * value / math.max(1, tonumber(params.time_interval) or 40))
            local drone = Units.DRONES and Units.DRONES [u.unit_id]
            if drone and drone.late and value > 0 then
                local ratio2 = 1 / value
                ratio = ratio * ratio2 / (ratio2 + (tonumber(drone.max) or 0) * (tonumber(drone.late.dmg) or 0) * (tonumber(drone.hits) or 1) / math.max(0.1, tonumber(drone.late.cd) or 4))
            end
            count = count + ratio
        elseif uniqueRelicEffect.id == "yuno_clover" then
            count = count + (tonumber(params.dmg_buff) or 0) * 0.25
        elseif uniqueRelicEffect.id == "nail" then
            count = count + (tonumber(params.dmg_buff) or 0) * count2
        elseif uniqueRelicEffect.id == "asta_clover" then
            if types.magic then
                count = 0
            else
                count = count + (tonumber(params.dmg_buff) or 0) * 0.3
            end
        elseif uniqueRelicEffect.id == "noelle_crown" then
            if types.water_damage then
                count = count + 0.05
            end
        end
    end
    return count
end

function Strategy.relicPlan()
    local session = Core.session()
    if not session then
        return nil
    end
    local inventoryProfileData = session.inventory and session.inventory.inventory_profile_data or {
    }
    local list = {
    }
    for _, uniqueItem in ipairs(inventoryProfileData.unique_items or {
    }) do
        if type(uniqueItem) == "table" and uniqueItem.uuid and (Core.Items [uniqueItem.item_id] or {
        }).item_group == "Relics" then
            table.insert(list, uniqueItem)
        end
    end
    local list2 = {
    }
    for _, value in ipairs(Units.equipped()) do
        local rarity = value.data and value.data.rarity
        if not Units.isFarm(value.id) and (rarity == "Legendary" or rarity == "Mythic" or rarity == "Secret" or rarity == "Exclusive") then
            local share = Strategy.share(value.id)
            if not Brain.str.share [value.id] then
                share = math.min(share, 0.15)
            end
            local list3 = {
            }
            for _, item in ipairs(list) do
                local relicWorth = Strategy.relicWorth(value.u, item) * share * 100
                if relicWorth > 0.01 then
                    table.insert(list3, {
                        it = item,
                        w = relicWorth
                    })
                end
            end
            table.sort(list3, function(arg1, arg2)
                if arg1.w ~= arg2.w then
                    return arg1.w > arg2.w
                end
                return arg1.it.uuid < arg2.it.uuid
            end)
            local list, list4 = {
            }, {
            }
            for _, item in ipairs(list3) do
                local item2 = list4 [item.it.item_id] or 0
                if # list < 6 and item2 < ((Core.Items [item.it.item_id] or {
                }).unique_equip and 1 or 2) then
                    list4 [item.it.item_id] = item2 + 1
                    table.insert(list, item)
                end
            end
            if value.u._equipped_relic then
                local flag = false
                for _, item in ipairs(list) do
                    if item.it.uuid == value.u._equipped_relic then
                        flag = true
                    end
                end
                local itemByUuid = not flag and session.inventory:get_item_by_uuid(value.u._equipped_relic)
                if itemByUuid then
                    table.insert(list, {
                        it = itemByUuid,
                        w = Strategy.relicWorth(value.u,
                        itemByUuid) * share * 100
                    })
                end
            end
            table.insert(list2, {
                e = value,
                share = share,
                opts = list
            })
        end
    end
    local list, num = {
    }, - 1
    local list3, list4, list5 = {
    }, {
    }, {
    }
    local function helper(arg1, arg2)
        if arg1 > # list2 then
            if arg2 > num then
                num = arg2
                list = table.clone(list3)
            end
            return
        end
        local item = list2 [arg1]
        list3 [item.e.uuid] = nil
        helper(arg1 + 1, arg2)
        for _, opt in ipairs(item.opts) do
            local uniqueEquip = (Core.Items [opt.it.item_id] or {
            }).unique_equip
            if not list4 [opt.it.uuid] and not (uniqueEquip and list5 [opt.it.item_id]) then
                list4 [opt.it.uuid] = true
                if uniqueEquip then
                    list5 [opt.it.item_id] = true
                end
                list3 [item.e.uuid] = opt.it.uuid
                helper(arg1 + 1, arg2 + opt.w + (opt.it.uuid == item.e.u._equipped_relic and 0.01 or 0))
                list3 [item.e.uuid] = nil
                list4 [opt.it.uuid] = nil
                if uniqueEquip then
                    list5 [opt.it.item_id] = nil
                end
            end
        end
    end
    helper(1, 0)
    local count, list3 = 0, {
    }
    for _, item in ipairs(list2) do
        local itemByUuid = item.e.u._equipped_relic and session.inventory:get_item_by_uuid(item.e.u._equipped_relic)
        local relicWorth = itemByUuid and Strategy.relicWorth(item.e.u, itemByUuid) * item.share * 100 or 0
        count = count + relicWorth
        local itemByUuid2 = list [item.e.uuid] and session.inventory:get_item_by_uuid(list [item.e.uuid])
        local relicWorth2 = itemByUuid2 and Strategy.relicWorth(item.e.u, itemByUuid2) * item.share * 100 or 0
        table.insert(list3, string.format("%s: %s (%+.1f%%) → %s (%+.1f%%)", Units.name(item.e.id), itemByUuid and (Core.Items [itemByUuid.item_id] or {
        }).name or "none", relicWorth, itemByUuid2 and (Core.Items [itemByUuid2.item_id] or {
        }).name or "none", relicWorth2))
    end
    return list, num - count, list3, list2
end

function Strategy.relicsApply(arg1)
    if not (Config.team and Config.teamRelics) or Config.strDry then
        return false
    end
    local teamSig = Modes.teamSig()
    if not arg1 and Brain.str.relicSig == teamSig and os.time() - (tonumber(Brain.str.relicAt) or 0) < 600 then
        return false
    end
    if App.req.back.relicMove and Utils.now() < App.req.back.relicMove then
        return false
    end
    Brain.str.relicSig, Brain.str.relicAt = teamSig, os.time()
    local relicPlan, relicPlan2, relicPlan3, relicPlan4 = Strategy.relicPlan()
    if not relicPlan then
        return false
    end
    Brain.str.relicNote = string.format("relics now on the best spread for this team (a change would add %.1f%%)", math.max(0, relicPlan2))
    if relicPlan2 < Strategy.relicBar() then
        Brain.str.relicTeam = teamSig
        return false
    end
    local session = Core.session()
    local ownedUnits = session.profile_data.collection.owned_units
    local function helper(arg1)
        for ownedUnitKey, ownedUnit in pairs(ownedUnits) do
            if ownedUnit._equipped_relic == arg1 then
                return ownedUnitKey, ownedUnit
            end
        end
    end
    local function helper2(arg1)
        return App.gameSaid(arg1) or "no answer"
    end
    local function helper3(arg1)
        local value, unitData = helper(arg1)
        if not value then
            return true
        end
        local now = Utils.now()
        App.request("relicMove", "request_unequip_relic", arg1)
        while Utils.now() - now < 4 and unitData._equipped_relic == arg1 do
            task.wait(0.25)
        end
        task.wait(1.2)
        if unitData._equipped_relic == arg1 then
            App.log(1, "POWER", string.format("%s's %s wouldn't come off (%s): relics stay as they are for now", Units.name(unitData.unit_id), tostring(Units.relicName(unitData)), helper2(now)))
            App.backoff("relicMove", 300)
            return false
        end
        return true
    end
    App.log(1, "POWER", string.format("moving relics for +%.1f%% team damage: %s", relicPlan2, table.concat(relicPlan3, " · ")))
    for _, value in ipairs(relicPlan4) do
        local equippedRelic = value.e.u._equipped_relic
        if equippedRelic and equippedRelic ~= relicPlan [value.e.uuid] and not helper3(equippedRelic) then
            return false
        end
    end
    for key, value in pairs(relicPlan) do
        local value2 = helper(value)
        if value2 and value2 ~= key and not helper3(value) then
            return false
        end
    end
    table.sort(relicPlan4, function(arg1, arg2)
        return arg1.share > arg2.share
    end)
    local count = 0
    for _, value in ipairs(relicPlan4) do
        local value2 = relicPlan [value.e.uuid]
        if value2 and value.e.u._equipped_relic ~= value2 then
            local count2, equippedRelic = 0, nil
            local list = {
            }
            for _, item in ipairs(Units.equipped()) do
                list [item.uuid] = true
            end
            for ownedUnitKey, ownedUnit in pairs(ownedUnits) do
                if ownedUnit._equipped_relic then
                    count2 = count2 + 1
                    if not list [ownedUnitKey] and (not equippedRelic or not table.find(Brain.str.core or {
                    }, ownedUnitKey)) then
                        equippedRelic = ownedUnit._equipped_relic
                    end
                end
            end
            if count2 >= Strategy.MAX_RELICS and equippedRelic and not helper3(equippedRelic) then
                return false
            end
            local now = Utils.now()
            App.request("relicMove", "use_unique_item", value2, {
                unit_uuid = value.e.uuid
            })
            while Utils.now() - now < 4 and value.e.u._equipped_relic ~= value2 do
                task.wait(0.25)
            end
            task.wait(1.2)
            if value.e.u._equipped_relic ~= value2 then
                App.log(1, "POWER", string.format("the game didn't put %s on %s (%s): trying again in 5 min", (Core.Items [(session.inventory:get_item_by_uuid(value2) or {
                }).item_id] or {
                }).name or "that relic", Units.name(value.e.id), helper2(now)))
                App.backoff("relicMove", 300)
                Brain.str.relicAt = 0
                return false
            end
            count = count + 1
        end
    end
    Modes._sigAt = nil
    Brain.str.relicSig = Modes.teamSig()
    Brain.str.relicTeam = Brain.str.relicSig
    Brain.str.relicNote = string.format("relics moved for +%.1f%% team damage", relicPlan2)
    Strategy.note(string.format("moved %d relics for +%.1f%% team damage", count, relicPlan2))
    return true
end

function Strategy.foodHeld()
    local session = Core.session()
    local list = {
    }
    local inventoryProfileData = session and session.inventory and session.inventory.inventory_profile_data or {
    }
    for normalItemKey, normalItem in pairs(inventoryProfileData.normal_items or {
    }) do
        local item = Core.Items [normalItemKey]
        if type(item) == "table" and type(item.usage) == "table" and item.usage.type == "xp_feed" and (tonumber(normalItem) or 0) > 0 then
            table.insert(list, {
                id = normalItemKey,
                n = tonumber(normalItem),
                xp = tonumber(item.usage.xp_amount) or 0
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.xp > arg2.xp
    end)
    return list
end

function Strategy.xpRoom()
    local session, count = Core.session(), 0
    for _, value in ipairs(session and Strategy.core() or {
    }) do
        local unitObj = session.collection:get_unit_by_uuid(value)
        if unitObj then
            count = count + math.max(0, Strategy.xpFor(unitObj.unit_id, Strategy.cap(unitObj)) - (tonumber(unitObj.xp) or 0))
        end
    end
    return count
end

function Strategy.plan()
    local session = Core.session()
    if not session then
        return {
        }
    end
    local list = {
    }
    local core = Strategy.core()
    local foodHeld = Strategy.foodHeld()
    local count = 0
    for _, value in ipairs(foodHeld) do
        count = count + value.n * value.xp
    end
    local fuseUnit = Config.autoFuse and Config.fuseUnit ~= "" and Config.fuseUnit or nil
    local value = (Brain.fuseInfo and tonumber(Brain.fuseInfo.requirement)) or (Brain.lb and tonumber(Brain.lb.requirement)) or 12
    local have = Adventure.have("divine_wish")
    for _, value2 in ipairs(core) do
        local unitObj = session.collection:get_unit_by_uuid(value2)
        if unitObj then
            local unitId, name = unitObj.unit_id, Units.name(unitObj.unit_id)
            local role = Strategy.role(unitId)
            if Config.teamXp and count > 0 then
                local _, gainXp2 = Strategy.gainXp(unitObj, count)
                local gainXp, gainXp22 = Strategy.gainXp(unitObj, 500000)
                local ratio = gainXp22 > 0 and gainXp / gainXp22 * gainXp2 or 0
                if gainXp2 > 0 and ratio > 0 then
                    table.insert(list, {
                        kind = "feed",
                        uuid = value2,
                        name = name,
                        gain = ratio,
                        add = gainXp2,
                        text = string.format("feed %s %s XP: level %d → %d (+%.1f%% team damage)",
                        name,
                        Utils.fmt(gainXp2),
                        Strategy.level(unitObj),
                        Strategy.level({
                            unit_id = unitId,
                            xp = (tonumber(unitObj.xp) or 0) + gainXp2
                        }),
                        ratio)
                    })
                end
            end
            local value3 = Brain.str.fuseNo and tonumber(Brain.str.fuseNo [value2])
            if Config.teamFuse and Strategy.lb(unitObj) == 0 and role ~= "farm" and value2 ~= fuseUnit and not (value3 and os.time() - value3 < 86400) then
                local gainFuse = Strategy.gainFuse(unitObj)
                local flag = Strategy.xpFor(unitId, Strategy.cap(unitObj)) <= (tonumber(unitObj.xp) or 0)
                local ok, _, res2 = pcall(FarmHub.fuseFuel, unitObj, value)
                res2 = ok and res2 or 0
                local text = (not flag and "not at its level cap yet") or (have < 1 and "no Divine Wish (the Daily Challenge pays one)") or (res2 < value and string.format("spare units it may use are worth %d of %d points", math.floor(res2), math.floor(value))) or nil
                table.insert(list, {
                    kind = "fuse",
                    uuid = value2,
                    name = name,
                    gain = gainFuse,
                    blocked = text,
                    text = string.format("limit break %s (+%.1f%% team damage once it reaches level 110)",
                    name,
                    gainFuse)
                })
            end
        end
    end
    table.sort(list, function(arg1, arg2)
        if arg1.gain ~= arg2.gain then
            return arg1.gain > arg2.gain
        end
        return arg1.text < arg2.text
    end)
    for key in pairs(Units._mult) do
        if type(key) == "string" and key:sub(1, 5) == "what:" then
            Units._mult [key] = nil
        end
    end
    Brain.str.acts, Brain.str.actsAt = {
    }, os.time()
    for i = 1, math.min(12, # list) do
        local item = list [i]
        table.insert(Brain.str.acts, {
            kind = item.kind,
            uuid = item.uuid,
            name = item.name,
            gain = item.gain,
            text = item.text,
            blocked = item.blocked
        })
    end
    return list
end

function Strategy.itemWorth(arg1)
    if not (Brain.str.acts and os.time() - (tonumber(Brain.str.actsAt) or 0) < 900) then
        return nil
    end
    local list = {
    }
    for _, act in ipairs(Brain.str.acts) do
        if act.gain and (not list [act.kind] or act.gain > list [act.kind]) then
            list [act.kind] = act.gain
        end
    end
    local strengthValue = Config.strengthValue or 300
    if arg1 == "divine_wish" then
        return list.fuse and math.max(Core.ITEM_VALUE.divine_wish or 400, list.fuse * strengthValue) or nil
    end
    return nil
end

function Strategy.xpRate()
    local session = Core.session()
    if not session then
        return 0
    end
    local count = 0
    for _, value in ipairs(Strategy.core()) do
        local unitObj = session.collection:get_unit_by_uuid(value)
        if unitObj then
            local gainXp, gainXp2 = Strategy.gainXp(unitObj, 500000)
            if gainXp2 > 0 then
                count = math.max(count, gainXp / gainXp2)
            end
        end
    end
    local count2 = count * (Config.strengthValue or 300)
    if (tonumber(Core.cur("gold")) or 0) > (Config.xpGoldFloor or 100000) then
        count2 = math.min(count2, (Core.GOLD_VALUE or 0.02) / 14)
    end
    return count2
end

function Strategy.xpGuess(mode)
    local level = mode.level and Core.Levels [mode.level]
    if not level then
        return 0
    end
    local value = math.min(9, tonumber(level.story_world_rank) or tonumber(mode.rank) or 9)
    local storyLevelRank = tonumber(level.story_level_rank) or 6
    local num = (mode.kind == "raid" and 1.5 or 1) * (value > 5 and 2 or 1)
    local ratio = 2.1564 ^ (value - 1) * (40 + 10 * storyLevelRank) / num
    if mode.kind == "infinite" then
        ratio = 3 * 30 * 2.1564 ^ (value - 1) / num
    end
    local num = value >= 9 and 0.3 or (value >= 7 and 0.5 or 1)
    return ratio * num * 6
end

function Strategy.modeBonus(arg1)
    if not (Config.team and Config.teamXp) or arg1.kind == "dungeon" or arg1.kind == "event" then
        return 0
    end
    local xpRate = Strategy._xpRate and os.time() - (Strategy._xpRateAt or 0) < 300 and Strategy._xpRate or nil
    if not xpRate then
        xpRate = Strategy.xpRate()
        Strategy._xpRate, Strategy._xpRateAt = xpRate, os.time()
    end
    if xpRate <= 0 then
        return 0
    end
    local mode = Brain.modes and Brain.modes [arg1.key]
    local xp = tonumber(mode and mode.xp) or Strategy.xpGuess(arg1)
    local xp2 = xp * xpRate
    if xp2 < 1 then
        return 0
    end
    return xp2, string.format("≈%s XP for your team (≈%d gems)", Utils.fmt(xp), math.floor(xp2 + 0.5))
end

function Strategy.xpSettle()
    local lastRun = Brain.lastRun
    if not (lastRun and type(lastRun.xp0) == "table" and lastRun.key) then
        return
    end
    local session = Core.session()
    if not session then
        return
    end
    local count, count2 = 0, 0
    for key, value in pairs(lastRun.xp0) do
        local unitObj = session.collection:get_unit_by_uuid(key)
        if unitObj then
            count = count + math.max(0, (tonumber(unitObj.xp) or 0) - (tonumber(value) or 0))
            count2 = count2 + 1
        end
    end
    Brain.lastRun = nil
    if count2 == 0 then
        return
    end
    local rec = Modes.rec(lastRun.key)
    rec.xp = rec.xp and (rec.xp + (count - rec.xp) * 0.3) or count
    if count > 0 then
        App.log(2, Strategy.LOG, string.format("%s paid your units %s XP", lastRun.key, Utils.fmt(count)))
    end
    App.saveSoon()
end

function Strategy.note(arg1)
    App.log(1, Strategy.LOG, arg1)
    table.insert(Brain.str.log, 1, {
        at = os.time(),
        msg = arg1
    })
    while # Brain.str.log > 20 do
        table.remove(Brain.str.log)
    end
    App.saveSoon()
end

function Strategy.run(item)
    local session = Core.session()
    local unitObj = session and session.collection:get_unit_by_uuid(item.uuid)
    if not unitObj then
        return
    end
    if item.kind == "feed" then
        local trait = Units.trait(unitObj)
        local num = trait == "neuroplasticity" and 1.5 or 1
        local value = math.max(0, Strategy.xpFor(unitObj.unit_id, Strategy.cap(unitObj)) - (tonumber(unitObj.xp) or 0))
        local list, count, count2 = {
        }, 0, 0
        for _, value2 in ipairs(Strategy.foodHeld()) do
            local xp = value2.xp * num
            local n = math.min(value2.n, math.floor((value - count) / math.max(1, xp)))
            if n > 0 then
                list [value2.id] = n
                count = count + n * xp
                count2 = count2 + n
            end
        end
        if count2 == 0 then
            Brain.str.feedNote = item.name .. ": no food small enough for the XP it has left"
            return
        end
        local xp, level = tonumber(unitObj.xp) or 0, Strategy.level(unitObj)
        local ok, res = App.request("feed", "level_up_feed", item.uuid, list)
        local now = Utils.now()
        while Utils.now() - now < 4 and (tonumber((session.collection:get_unit_by_uuid(item.uuid) or unitObj).xp) or 0) <= xp do
            task.wait(0.25)
        end
        local unitObj2 = session.collection:get_unit_by_uuid(item.uuid) or unitObj
        local xp2 = (tonumber(unitObj2.xp) or 0) - xp
        if xp2 > 0 then
            Spending.add(string.format("%d XP food on %s", count2, item.name), count2, "items", string.format("Units → Upgrades: +%s XP, level %d → %d", Utils.fmt(xp2), level, Strategy.level(unitObj2)))
            Strategy.note(string.format("fed %s %d items: +%s XP, level %d → %d%s", item.name, count2, Utils.fmt(xp2), level, Strategy.level(unitObj2), math.abs(xp2 - count) > count * 0.1 and string.format(" (planned %s)", Utils.fmt(count)) or ""))
        else
            Strategy.note(string.format("the game didn't take the food for %s (%s): trying again in 10 min", item.name, tostring(ok and res or "no answer")))
            App.backoff("feed", 600)
        end
    elseif item.kind == "fuse" then
        FarmHub.fuseInto(item.uuid, false)
    end
end

function Strategy.slotOf(uuid)
    local session = Core.session()
    for equippedUnitKey, equippedUnit in pairs(session and session.profile_data.collection.equipped_units or {
    }) do
        if equippedUnit == uuid then
            return tonumber(equippedUnitKey) or equippedUnitKey
        end
    end
    return nil
end

function Strategy.reequip()
    local reequip = Brain.str.reequip
    if not reequip then
        return true
    end
    local session = Core.session()
    local unitObj = session and session.collection:get_unit_by_uuid(reequip.uuid)
    if not unitObj then
        Brain.str.reequip = nil
        return true
    end
    for i = 1, 3 do
        if Strategy.slotOf(reequip.uuid) then
            break
        end
        App.request("eq", "equip_unit", reequip.uuid)
        local now = Utils.now()
        while Utils.now() - now < 3 and not Strategy.slotOf(reequip.uuid) do
            task.wait(0.25)
        end
    end
    Modes._sigAt = nil
    if Strategy.slotOf(reequip.uuid) then
        Brain.str.reequip = nil
        App.saveSoon()
        return true
    end
    App.log(1, "TEAM", string.format("%s didn't go back into slot %s: trying again", Units.name(unitObj.unit_id), tostring(reequip.slot)))
    return false
end
Strategy.REMOTE = {
    feed = "feed",
    fuse = "fuse"
}
Strategy.WORK_MAX = 300

function Strategy.nextAct(acts)
    local now = os.time()
    for _, act in ipairs(acts or {
    }) do
        local value = App.req.back [Strategy.REMOTE [act.kind] or ""]
        if not act.blocked and not (value and Utils.now() < value) and (tonumber(Brain.str.noWork [act.kind]) or 0) <= now and (tonumber(Brain.str.noWork [act.kind .. ":" .. tostring(act.uuid)]) or 0) <= now then
            return act
        end
    end
end

function Strategy.workSig()
    local count = 0
    for _, value in ipairs(Strategy.foodHeld()) do
        count = count + value.n
    end
    return table.concat({
        count,
        Adventure.have("divine_wish")
    }, ",")
end
Strategy.FEED_STOP_GAIN = 0.5

function Strategy.focusReady()
    if not (Config.autoEvolve and Config.evolveUnit ~= "") then
        return nil
    end
    pcall(Adventure.refresh)
    for _, goal in ipairs(Brain.goals or {
    }) do
        if goal.pinned and goal.uuid == Config.evolveUnit and goal.ready and (FarmHub.evoBlocked [goal.uuid] or 0) < os.time() then
            local list = {
            }
            for _, item in ipairs(Units.equipped()) do
                list [item.uuid] = true
            end
            if not FarmHub.evoEats(goal, list) then
                return goal
            end
        end
    end
end

function Strategy.hasWork(arg1)
    if not arg1 then
        local focusReady = Strategy.focusReady()
        if focusReady then
            return "evolve " .. Units.name(focusReady.from) .. ", your focus", "evolve"
        end
        if FarmHub.snipeWanted() then
            return "pull " .. Units.name(Config.snipeUnit) .. " while it's featured (Banner Snipe)", "snipe"
        end
        if FarmHub.snipeDue() then
            return "look at the banners for " .. Units.name(Config.snipeUnit) .. ": they've turned over (Banner Snipe)", "snipe"
        end
        if Brain.ownSwap then
            return "put " .. Units.name(Brain.ownSwap.into) .. " on your team", "ownSwap"
        end
    end
    if not Config.team or Config.strDry then
        return nil
    end
    Strategy.acts = Strategy.plan()
    FarmHub.last.teamPlan = Utils.now()
    local acts = Strategy.acts
    if not arg1 then
        acts = {
        }
        for _, act in ipairs(Strategy.acts) do
            if not (act.kind == "feed" and (tonumber(act.gain) or 0) < Strategy.FEED_STOP_GAIN) then
                table.insert(acts, act)
            end
        end
    end
    local nextAct = Strategy.nextAct(acts)
    if nextAct then
        return nextAct.text, nextAct.kind
    end
    if Config.teamRelics and (tonumber(Brain.str.noWork.relic) or 0) <= os.time() and (not arg1 or not (Config.autoTeam and Config.play)) then
        local _, relicPlan2 = Strategy.relicPlan()
        if relicPlan2 and relicPlan2 >= (arg1 and Strategy.relicBar() or Strategy.RELIC_SETTLED_GAIN) then
            return string.format("move relics for +%.1f%% team damage", relicPlan2), "relic"
        end
    end
    if not arg1 and Config.teamXp and Config.teamBuyXp and Config.goldShop and os.time() - (tonumber(Brain.str.shopAt) or 0) > 21600 and Strategy.xpRoom() > 0 and (tonumber(Core.cur("gold")) or 0) > (Config.xpGoldFloor or 100000) then
        return "look for XP food in the gold shop", "shop"
    end
    return nil
end

function Strategy.finishWork()
    local now = Utils.now()
    local count = 0
    while App.alive and Config.master and not Brain.holdLobby and Utils.now() - now < Strategy.WORK_MAX do
        local hasWork, hasWork2 = Strategy.hasWork(true)
        if not hasWork then
            break
        end
        App.status("Mode", "Units → Upgrades first: " .. tostring(hasWork))
        if hasWork2 == "relic" then
            local ok, res = pcall(Strategy.relicsApply, true)
            if not (ok and res) then
                Brain.str.noWork.relic = os.time() + 1800
            end
        else
            Strategy.tick()
        end
        count = count + 1
        task.wait(4)
    end
    if count > 0 then
        App.log(1, Strategy.LOG, string.format("Units → Upgrades finished for now: %d actions in %ds", count, math.floor(Utils.now() - now)))
        Modes._sigAt, Modes.lastScored = nil, nil
        App.saveSoon()
    end
end

function Strategy.tick()
    if not Config.team then
        Brain.str.next = "Off."
        return
    end
    if Brain.str.reequip then
        Strategy.reequip()
    end
    local plan
    if FarmHub.every("teamPlan", 60) or not Brain.str.acts then
        plan = Strategy.plan()
    else
        plan = Strategy.acts
    end
    Strategy.acts = plan or Strategy.acts or {
    }
    local nextAct = Strategy.nextAct(Strategy.acts)
    if not nextAct then
        local act = Strategy.acts [1]
        Brain.str.next = act and (act.text .. " — waiting: " .. tostring(act.blocked)) or "Nothing to do: every core unit is as strong as what you have allows."
        return
    end
    if Config.strDry then
        Brain.str.next = "Would " .. nextAct.text .. ". Dry Run is on: nothing is spent."
        if Brain.str.dryLast ~= nextAct.text then
            Brain.str.dryLast = nextAct.text
            App.log(1, Strategy.LOG, "dry run: would " .. nextAct.text)
        end
        return
    end
    Brain.str.next = nextAct.text
    local workSig = Strategy.workSig()
    local ok, res = pcall(Strategy.run, nextAct)
    if not ok then
        App.log(1, "ERROR", "team: " .. tostring(res))
    end
    local value = nextAct.kind == "fuse" and os.time() - (tonumber(Config.fuseArmAt) or 0) < 45
    if Strategy.workSig() == workSig and not value then
        Brain.str.noWork [nextAct.kind .. ":" .. tostring(nextAct.uuid)] = os.time() + 1800
    end
    local value = App.req.back [Strategy.REMOTE [nextAct.kind] or ""]
    if value and value > Utils.now() then
        Brain.str.noWork [nextAct.kind] = os.time() + math.ceil(value - Utils.now())
    end
    FarmHub.last.teamPlan = nil
end

function Strategy.rows()
    local session = Core.session()
    local list = {
    }
    if not session then
        return list
    end
    for _, value in ipairs(Brain.str.core or {
    }) do
        local unitObj = session.collection:get_unit_by_uuid(value)
        if unitObj then
            local trait, trait2 = Units.trait(unitObj)
            local list2 = {
                string.format("level %d/%d",
                Strategy.level(unitObj),
                Strategy.cap(unitObj)),
                Strategy.traitName(trait,
                trait2)
            }
            if unitObj.trait_stats then
                table.insert(list2, (FarmHub.statRanks(unitObj):gsub(" · ", " / ")))
            end
            table.insert(list2, Units.relicName(unitObj) and ("relic: " .. Units.relicName(unitObj)) or "no relic")
            if Strategy.lb(unitObj) >= 1 then
                table.insert(list2, "limit broken ✓")
            end
            local value2
            for _, act in ipairs(Brain.str.acts or {
            }) do
                if act.uuid == value then
                    value2 = act
                    break
                end
            end
            if value2 then
                table.insert(list2, "next: " .. (value2.text:gsub("^%l", string.upper)) .. (value2.blocked and (" (waiting: " .. value2.blocked .. ")") or ""))
            end
            table.insert(list, {
                name = Units.name(unitObj.unit_id),
                text = table.concat(list2,
                " · ")
            })
        end
    end
    return list
end

function Strategy.text()
    if not Config.team then
        return "Off. Switch it on and the farm makes your core units stronger with what you already have."
    end
    local list = {
        Brain.str.next or "Working it out in the lobby…"
    }
    if Brain.str.fuseNote then
        table.insert(list, "Limit break: " .. Brain.str.fuseNote)
    end
    if Brain.str.relicNote then
        table.insert(list, "Relics: " .. Brain.str.relicNote)
    end
    for i = 1, math.min(4, # (Brain.str.log or {
    })) do
        table.insert(list, os.date("%H:%M", Brain.str.log [i].at) .. " " .. Brain.str.log [i].msg)
    end
    return table.concat(list, "\n")
end
FarmHub.last = {
}
FarmHub.hatched = {
}

function FarmHub.evolve(item, arg2)
    local session = Core.session()
    local unitObj = session.collection:get_unit_by_uuid(item.uuid)
    if not unitObj then
        return false, "unit not found"
    end
    local count, list = 0, {
    }
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        if ownedUnit.unit_id == item.to then
            count = count + 1
            list [ownedUnitKey] = true
        end
    end
    local _, res = App.request("evolve", "evolve_unit", item.uuid)
    task.wait(2)
    local unitObj = session.collection:get_unit_by_uuid(item.uuid)
    local count2 = 0
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        if ownedUnit.unit_id == item.to then
            count2 = count2 + 1
            if not list [ownedUnitKey] then
                if Config.fuseXpUnit == item.uuid then
                    Config.fuseXpUnit, Config.fuseXpId = ownedUnitKey, item.to
                    App.saveSoon()
                end
                if Config.fuseUnit == item.uuid then
                    Config.fuseUnit = ownedUnitKey
                    App.saveSoon()
                end
            end
        end
    end
    if count2 > count then
        local list = {
        }
        for _, item in ipairs(item.items or {
        }) do
            table.insert(list, string.format("%s ×%d", (Core.Items [item.id] or {
            }).name or item.id, item.amount))
        end
        for _, eat in ipairs(item.eats or {
        }) do
            table.insert(list, string.format("%d× %s", eat.amount, Units.name(eat.id)))
        end
        local text = string.format("%s → %s (score %s → %s)", Units.name(item.from), Units.name(item.to), Utils.fmt(item.scoreFrom or 0), Utils.fmt(item.scoreTo or 0))
        Spending.add("evolved " .. text, 1, "evolution", (arg2 or "your choice") .. (# list > 0 and (" · used " .. table.concat(list, ", ")) or ""))
        App.log(1, "EVOLVE", text .. " — " .. (arg2 or "your choice") .. (# list > 0 and (" · used " .. table.concat(list, ", ")) or ""))
        Modes._sigAt = nil
        pcall(Adventure.refresh)
        return true, Units.name(item.to) .. " is yours!"
    end
    App.log(1, "EVOLVE", "evolve refused for " .. Units.name(item.from) .. " (" .. tostring(res) .. "), unit now " .. tostring(unitObj and unitObj.unit_id))
    return false, "the game said no (" .. tostring(res) .. ")"
end
FarmHub.evoBlocked = {
}

function FarmHub.evoEats(item, list)
    local session = Core.session()
    local ok, res = pcall(Units.score, session.collection:get_unit_by_uuid(item.uuid))
    for _, eat in ipairs(item.eats or {
    }) do
        for _, copy in ipairs(Adventure.copies(eat.id, eat.shiny, item.uuid)) do
            local unitObj = session.collection:get_unit_by_uuid(copy.uuid) or copy
            local ok2, res2 = pcall(Units.score, unitObj)
            if list [copy.uuid] or Units.trait(unitObj) or (ok and ok2 and res2 >= res) then
                return string.format("would use up a %s you may want (on your team, a trait, or stronger) — lock it in the game to keep it", Units.name(eat.id))
            end
        end
    end
end
FarmHub.pickNote = {
}

function FarmHub.pickDone(arg1, arg2, evolve, arg4)
