function Simulator.unbound(ld)
    return not tonumber(ld._override_infinite_bound_waves) and not ld._infinite_bound_level
end

function Simulator.boundEnd(ld, itemCount, calKey)
    if not (ld and ld._infinite_bound_level) or tonumber(ld._override_infinite_bound_waves) then
        return nil
    end
    local value = calKey and Brain.simCal [calKey]
    if type(value) == "table" and (tonumber(value.lastWave) or 0) > 15 then
        return nil
    end
    return (itemCount or 0) > 0 and math.min(itemCount, 15) or 15
end

function Simulator.slim(arg1)
    local list = {
    }
    for _, ldField in ipairs(Simulator.LD_FIELDS) do
        local value = arg1 [ldField]
        if type(value) ~= "table" and type(value) ~= "function" then
            list [ldField] = value
        end
    end
    if type(arg1._override_waves) == "table" then
        list._override_waves = {
            infinite = arg1._override_waves.infinite,
            template = arg1._override_waves.template
        }
    end
    if type(arg1._dungeon) == "table" then
        list._dungeon = {
            depth = arg1._dungeon.depth,
            choice_str = arg1._dungeon.choice_str
        }
    end
    if type(arg1._override_infinite_final_boss_wave) == "table" then
        list._final = {
            wave = arg1._override_infinite_final_boss_wave.wave,
            cfg = arg1._override_infinite_final_boss_wave.final_boss_config_id
        }
    elseif type(arg1._final) == "table" then
        list._final = table.clone(arg1._final)
    end
    if type(arg1._override_infinite_boss_interval__skip_waves) == "table" then
        list._skip = {
        }
        for key in pairs(arg1._override_infinite_boss_interval__skip_waves) do
            list._skip [tostring(key)] = true
        end
    elseif type(arg1._skip) == "table" then
        list._skip = table.clone(arg1._skip)
    end
    return list
end
local function helper(arg1, ...)
    local ok, res = pcall(arg1, ...)
    return ok and tonumber(res) or nil
end

function Simulator.info(slim, key, levelFor, mod, rotation)
    local calKey = Simulator.calKey(key, slim, levelFor, rotation)
    local value = Brain.simCal[calKey] or {}
    local overrideGamemode = slim._OVERRIDE_GAMEMODE or slim._gamemode or (slim.infinite and "infinite") or "story"
    local flag = slim.id == "__DAILY_CHALLENGE"
    local flag2 = (Brain.live.event and slim.id == Brain.live.event.level) and true or false
    local info = {
        _is_daily_challenge = flag or nil,
        _is_event_challenge = flag2 or nil,
        _use_max = slim._use_max,
        world = slim.world,
        id = slim.id,
        _override_multiplayer_diff_scale = slim._override_multiplayer_diff_scale,
        _no_multiplayer_scale = slim._no_multiplayer_scale,
        portal_group = slim.portal_group,
        _raid_multiplayer_scale = slim._raid_multiplayer_scale
    }
    local storyWorldRank = tonumber(slim.story_world_rank) or # Utils.list(Core.WLO.WORLD_ORDER)
    local str = (overrideGamemode == "infinite") and "challenge" or overrideGamemode
    local value2 = helper(Core.LU.calculate_world_diff_scale, storyWorldRank, str, nil, slim.map, info) or 1
    local value3 = helper(Core.LU.calculate_level_diff_scale, tonumber(slim.story_level_rank) or 6, (overrideGamemode == "infinite" or overrideGamemode == "raid") and overrideGamemode or (overrideGamemode == "challenge" and "challenge" or "story"), info) or 1
    local value4 = helper(Core.LU.calculate_multiplayer_diff_scale, overrideGamemode, 1, info) or 1
    local overrideWaves = slim._override_waves
    local wave = Core.Waves [(overrideWaves and overrideWaves.template) or slim.waves or slim.id]
    local wave2 = wave
    if wave and wave.template and Core.Waves [wave.template] then
        wave2 = Core.Waves [wave.template]
    end
    local infinite = (overrideWaves and overrideWaves.infinite) or slim.infinite or (wave and wave.infinite) or false
    local initialUnitConfigs = (wave and wave.initial_unit_configs) or (wave2 and wave2.initial_unit_configs) or {
    }
    if infinite and slim._infinite_bound_level then
        local flag = false
        for _, initialUnitConfig in pairs(initialUnitConfigs) do
            if type(initialUnitConfig) == "table" and initialUnitConfig.spawn_tier_normal then
                flag = true
            end
        end
        if not flag then
            infinite = false
        end
    end
    local list = Utils.list((wave and (wave.override_waves or wave.waves)) or (wave2 and wave2.waves))
    local levelFor2 = levelFor or slim._challenge
    local challenge = Core.CAR.challenges and Core.CAR.challenges [levelFor2 or ""] or nil
    local count, count2 = 0, 0
    for _, enemyBuff in pairs(challenge and challenge.enemy_buffs or {
    }) do
        if type(enemyBuff) == "table" and enemyBuff.name == "damage_reduction" then
            count = count + (tonumber(enemyBuff.params and enemyBuff.params.reduction) or 0)
        end
        if type(enemyBuff) == "table" and enemyBuff.name == "healing" then
            count2 = count2 + (tonumber(enemyBuff.params and enemyBuff.params.percent) or 0)
        end
    end
    local difficulty = slim._difficulty or ((infinite and not slim._dungeon and not slim._infinite_bound_level) and "Hard") or "Normal"
    local value5 = ((not infinite) or (not slim._dungeon and not slim._infinite_bound_level)) and (Core.GS.DIFFICULTY_HEALTH_SCALES and Core.GS.DIFFICULTY_HEALTH_SCALES [difficulty]) or 1
    local value6 = value2 * value3 * value4 * value5 * (challenge and tonumber(challenge.enemy_health_scale) or 1) * (tonumber(slim._lobby_difficulty_scale) or 1) * (tonumber(slim._world_diff_scale_multiplier) or 1)
    local value2 = helper(Core.LU.calculate_world_resource_scale, storyWorldRank, str) or 2.6
    local waveTimer = (wave and tonumber(wave.wave_max_time)) or (wave2 and tonumber(wave2.wave_max_time)) or Simulator.PRIOR.waveTimer
    local map, lanes = slim.map, (Brain.maps [slim.map] or {
    }).lanes
    local portalLanes = tonumber(slim._portal_lanes)
    if portalLanes and portalLanes >= 1 and type(lanes) == "table" and # lanes > portalLanes then
        map = tostring(slim.map) .. "~" .. portalLanes
        local list = {
        }
        for i = 1, portalLanes do
            list [i] = lanes [i]
        end
        lanes = # list >= 2 and list or nil
    end
    local info = {
        key = key,
        ld = slim,
        map = map,
        infinite = infinite and true or false,
        list = list,
        configs = initialUnitConfigs,
        gm = overrideGamemode,
        total = (type(slim._dungeon) == "table" and 15) or tonumber(slim._override_infinite_bound_waves) or Simulator.boundEnd(slim,
        # list,
        calKey) or (((not infinite) or slim._infinite_bound_level) and # list > 0 and # list) or (slim._infinite_bound_level and 15) or (infinite and Simulator.INF_CAP) or 30,
        hpRaw = value6,
        hpScale = value6 * (tonumber(value.hpCal) or (function()
            if calKey ~= key then return nil end
            local ok,
            res = pcall(Reports.hiveHp,
            key)
            return ok and res or nil
        end)() or 1),
        speedScale = challenge and tonumber(challenge.enemy_speed_scale) or 1,
        costScale = challenge and tonumber(challenge.player_cost_scale) or 1,
        rangeScale = challenge and tonumber(challenge.player_range_scale) or 1,
        red = math.min(0.75,
        count),
        regen = count2,
        shield = challenge and tonumber(challenge.enemy_additional_shield) or 0,
        flyChance = levelFor2 == "flying_enemies" and 1 or 0,
        armorAll = levelFor2 == "armored_enemies" or nil,
        bounty = value2 * (tonumber(value.bountyCal) or 1),
        payBase = value2,
        pay = value2 * (tonumber(value.yenCal) or 1),
        waveSec = tonumber(value.waveSec) or Simulator.PRIOR.waveSec,
        walk = Simulator.mapWalk(map) or Simulator.mapWalk(slim.map) or tonumber(value.walk) or Simulator.PRIOR.walk,
        waveTimer = waveTimer,
        skipDelay = tonumber(value.skipDelay) or Simulator.PRIOR.skipDelay,
        autoskip = Simulator.autoskip(),
        voteAt = tonumber(value.voteAt) or waveTimer / 2,
        votePer = tonumber(value.votePer) or Simulator.PRIOR.votePer,
        eff = Simulator.effFor(value),
        voteWave = type(value.voteWave) == "table" and value.voteWave or nil,
        spawnGap = tonumber(value.spawnGap) or Simulator.PRIOR.spawnGap,
        baseHp = tonumber(value.baseHp) or (wave and tonumber(wave.base_health)) or (wave2 and tonumber(wave2.base_health)) or Simulator.PRIOR.baseHp,
        baseRel = tonumber(value.baseRel) or Simulator.PRIOR.baseRel,
        timerAt = type(value.timerAt) == "table" and value.timerAt or {
