            if enemyModifiers.Armor or enemyModifiers.Ice or info.armorAll then
                info.mapMods = true
            end
        end
    end
    if Hunt.is(slim.id) then
        Simulator.applyFx(info, Hunt.fx(Hunt.weatherNow()))
    end
    local ok, res = pcall(Hunt.charmDmg, slim)
    if ok and (tonumber(res) or 0) > 0 then
        if not info.fx then
            Simulator.applyFx(info, Hunt.fx("clear"))
        end
        info.fx.dmg = info.fx.dmg * (1 + res)
    end
    return info
end

function Simulator.applyFx(arg1, fx)
    if not fx then
        return arg1
    end
    arg1.fx = fx
    arg1.rangeScale = arg1.rangeScale * fx.range
    arg1.costScale = arg1.costScale * fx.cost
    arg1.speedScale = arg1.speedScale * fx.speed
    arg1.regen = (arg1.regen or 0) + fx.regen
    arg1.shield = (arg1.shield or 0) + (fx.shield or 0)
    arg1.flyChance = (arg1.flyChance or 0) + (fx.fly or 0)
    arg1.noCC, arg1.shroud = fx.noCC, fx.shroud
    if (fx.ice or 0) > 0 then
        arg1.iceShare, arg1.mapMods = fx.ice, true
    end
    arg1.hpRaw, arg1.hpScale = arg1.hpRaw * fx.hp, arg1.hpScale * fx.hp
    return arg1
end

function Simulator.fxDps(arg1, id)
    local fx = arg1.fx
    if not fx then
        return 1
    end
    local _, types2 = Units.types(id)
    local ratio = fx.dmg / fx.cd * (1 + (fx.kinds [types2] or 0))
    if types2 == "physical" and fx.crit > 0 then
        ratio = ratio * (1 + fx.crit * 0.5)
    end
    return ratio
end

function Simulator.waveYen(arg1, i, payBase)
    local waveReward
    if arg1.infinite then
        waveReward = (Core.LU.Infinite and Core.LU.Infinite.initial_wave_template and Core.LU.Infinite.initial_wave_template.wave_reward) or 1000
    else
        waveReward = arg1.list [i] and tonumber(arg1.list [i].wave_reward) or 0
    end
    return waveReward * (payBase or arg1.pay or 1)
end

function Simulator.waveScale(arg1, wave, item)
    if arg1.infinite then
        return helper(Core.LU.Infinite.infinite_diff_scale, wave, arg1.ld.id) or 1
    end
    return item and tonumber(item.wave_diff_scale) or 1
end

function Simulator.baseStats(arg1, configKey)
    local config = arg1.configs [configKey]
    if type(config) ~= "table" then
        return nil
    end
    local value = config.override_stats and (config.override_stats [1] or config.override_stats ["1"]) or {
    }
    return tonumber(value.health) or 20, tonumber(value.speed) or 1, tonumber(value.resource_reward) or 30
end

function Simulator.enemy(arg1, arg2, arg3, item)
    local baseStats, baseStats2, baseStats3 = Simulator.baseStats(arg1, arg2)
    if not baseStats then
        return nil
    end
    baseStats = baseStats * arg1.hpScale * Simulator.waveScale(arg1, arg3, item)
    local unit = Core.Units [arg1.configs [arg2].unit_id] or {
    }
    local info = {
        hp = baseStats,
        max = baseStats,
        speed = baseStats2 * arg1.speedScale,
        bounty = baseStats3 * arg1.bounty,
        boss = tostring(arg2):find("boss") ~= nil,
        p = 0,
        sh = (tonumber(unit.shield) or 0) + (arg1.shield or 0),
        fly = Simulator.flies(unit)
    }
    local enemyModifiers = type(unit.enemy_modifiers) == "table" and unit.enemy_modifiers or {
    }
    info.fire, info.soar = enemyModifiers.Fire and true or nil, enemyModifiers.Soaring and true or nil
    info.armor, info.ice = (enemyModifiers.Armor or arg1.armorAll) and true or nil, enemyModifiers.Ice and true or nil
    if not info.ice and (arg1.iceShare or 0) > 0 then
        if info.boss then
            info.iceAvg = arg1.iceShare
        else
            arg1.iceAcc = (arg1.iceAcc or 0) + arg1.iceShare
            if arg1.iceAcc >= 1 then
                info.ice, info.iceKey, arg1.iceAcc = true, "Ice@snow", arg1.iceAcc - 1
            end
        end
    end
    Simulator.enemyTraits(info, unit, baseStats)
    return info
end

function Simulator.modRead(enemyMod)
    if type(enemyMod) ~= "table" or type(enemyMod.r) ~= "table" or # enemyMod.r < 8 then
        return nil
    end
    local rCount = # enemyMod.r
    if enemyMod._n == rCount and enemyMod._last == enemyMod.r [rCount] and enemyMod._f ~= nil then
        return enemyMod._f
    end
    local r = table.clone(enemyMod.r)
    table.sort(r)
    local value, value2, value3 = r [math.floor(rCount / 2) + 1], r [math.floor(rCount / 4) + 1], r [math.min(rCount, math.floor(rCount * 3 / 4) + 1)]
    enemyMod._n, enemyMod._last = rCount, enemyMod.r [rCount]
    enemyMod._f = (value2 >= value * 0.7 and value3 <= value * 1.4) and value or false
    enemyMod.f = enemyMod._f or nil
    return enemyMod._f
end

function Simulator.modFactor(iceKey)
    local modRead = Simulator.modRead(Brain.enemyMods [iceKey])
    if modRead then
        return modRead
    end
    local hive = Reports.hive()
    local enemyMod = hive and type(hive.enemyMods) == "table" and hive.enemyMods [iceKey]
    if type(enemyMod) == "table" and tonumber(enemyMod.f) and ((tonumber(enemyMod.players) or 0) >= 2 or (tonumber(enemyMod.pairs) or 0) >= 16) then
        return tonumber(enemyMod.f)
    end
    return Simulator.MOD_GUESS [iceKey] or 1
end
Simulator.MOD_GUESS = {
    ["Ice@snow"] = 1 / 3
}

function Simulator.modHit(item, item2)
    local num = 1
    if item.armor and item2.full then
        num = num * Simulator.modFactor("Armor")
    end
    if item.ice and not item2.fireDmg then
        num = num * Simulator.modFactor(item.iceKey or "Ice")
    end
    if item.iceAvg and not item2.fireDmg then
        num = num / (1 - item.iceAvg + item.iceAvg / Simulator.modFactor("Ice@snow"))
    end
    return num
end

function Simulator.flies(unit)
    return type(unit) == "table" and ((type(unit.enemy_modifiers) == "table" and unit.enemy_modifiers.Flying) or (type(unit.passives) == "table" and unit.passives.Flying)) and true or false
end

function Simulator.enemyTraits(arg1, unit, baseStats)
    for _, buff in pairs(type(unit.buffs) == "table" and unit.buffs or {
    }) do
        if type(buff) == "table" and buff.name == "healing" and type(buff.params) == "table" then
            arg1.regen = (arg1.regen or 0) + (tonumber(buff.params.percent) or 0) / math.max(0.1, tonumber(buff.params.healing_rate) or 1)
        end
    end
    if type(unit.barrier) == "table" and tonumber(unit.barrier.health_ratio) then
        local count = 0
        for _, buff in pairs(type(unit.barrier.buffs) == "table" and unit.barrier.buffs or {
        }) do
            if type(buff) == "table" and buff.name == "damage_reduction" and type(buff.params) == "table" then
                count = count + (tonumber(buff.params.reduction) or 0)
            end
        end
        arg1.bar = baseStats * tonumber(unit.barrier.health_ratio) / math.max(0.1, 1 - count)
    end
    local deathSpawn = unit.death_spawn
    if type(deathSpawn) == "table" and type(deathSpawn.units) == "table" then
        for _, unit in pairs(deathSpawn.units) do
            if type(unit) == "table" and tonumber(unit.health_ratio) then
                arg1.split = {
                    n = tonumber(deathSpawn.amount) or 1,
                    ratio = tonumber(unit.health_ratio),
                    unit = unit.unit
                }
                break
            end
        end
    end
end

function Simulator.wave(applyFx, arg2, arg3)
    local cacheKey = tostring(arg2) .. (arg3 and ":s" or "")
    local cached = applyFx._waveCache and applyFx._waveCache[cacheKey]
    if cached then
        local out = table.create and table.create(#cached.list) or {}
        for idx, proto in ipairs(cached.list) do
            out[idx] = {
                hp = proto.hp,
                max = proto.max,
                speed = proto.speed,
                bounty = proto.bounty,
                boss = proto.boss,
                p = 0,
                sh = proto.sh,
                fly = proto.fly,
                fire = proto.fire,
                soar = proto.soar,
                armor = proto.armor,
                ice = proto.ice,
                iceKey = proto.iceKey,
                iceAvg = proto.iceAvg,
                regen = proto.regen,
                bar = proto.bar,
                split = proto.split
            }
        end
        return out, cached.yen
    end
    local list = {
    }
    applyFx.iceAcc = (arg2 * 0.6180339887) % 1
    if not applyFx.infinite then
        local item = applyFx.list [arg2]
        if not item then
            return list, 0
        end
        for _, item2 in ipairs(Utils.list(item.wave)) do
            for i = 1, tonumber(item2.amount) or 1 do
                local enemy = Simulator.enemy(applyFx, item2.unit, arg2, item)
                if enemy then
                    table.insert(list, enemy)
                end
            end
        end
    else
        local value = helper(Core.LU.Infinite.infinite_amt_scale, arg2, applyFx.ld) or 10
        local list2, count = {
        }, 0
        for configKey, config in pairs(applyFx.configs) do
            if type(config) == "table" and config.spawn_tier_normal then
                local value = helper(Core.LU.Infinite.infinite_get_normal_unit_chance, config, arg2) or 0
                if value > 0 then
                    table.insert(list2, {
                        k = configKey,
                        c = value
                    })
                    count = count + value
                end
            end
        end
        table.sort(list2, function(arg1, arg2)
            return arg1.k < arg2.k
        end)
        local value2, count2 = math.floor(value + 0.5), 0
        for i, item in ipairs(list2) do
            local ratio = (i == # list2) and math.max(0, value2 - count2) or math.floor(value2 * item.c / count + 0.5)
            for i = 1, ratio do
                local enemy = Simulator.enemy(applyFx, item.k, arg2)
                if enemy then
                    table.insert(list, enemy)
                end
            end
            count2 = count2 + ratio
        end
        local value = applyFx.ld._infinite_bound_level and arg2 == applyFx.total
        if value then
            local list2, count = {
            }, 0
            for configKey, config in pairs(applyFx.configs) do
                if type(config) == "table" and tonumber(config.spawn_tier_boss) and (helper(Core.LU.Infinite.infinite_get_boss_unit_chance, config, arg2) or 0) > 0 then
                    local baseStats = Simulator.baseStats(applyFx, configKey)
                    if baseStats then
                        table.insert(list2, {
                            k = configKey,
                            hp = baseStats,
                            tier = tonumber(config.spawn_tier_boss)
                        })
                        count = count + baseStats
                    end
                end
            end
            table.sort(list2, function(arg1, arg2)
                return arg1.tier > arg2.tier
            end)
            local value = type(applyFx.ld._dungeon) == "table" and (tonumber(applyFx.ld._dungeon.depth) or 0) >= 20
            local item = list2 [1]
            if item and not value then
                local ratio = count / # list2
                for _, item2 in ipairs(list2) do
                    if math.abs(item2.hp - ratio) < math.abs(item.hp - ratio) then
                        item = item2
                    end
                end
            end
            if item then
                local enemy = Simulator.enemy(applyFx, item.k, arg2)
                if enemy then
                    enemy.boss = true
                    table.insert(list, enemy)
                end
            end
        elseif arg2 % applyFx.bossEvery == 0 and not applyFx.skip [tostring(arg2)] then
            local value = math.max(1, math.min(6, math.floor(arg2 / applyFx.bossEvery)))
            for configKey, config in pairs(applyFx.configs) do
                if type(config) == "table" and tonumber(config.spawn_tier_boss) == value then
                    local enemy = Simulator.enemy(applyFx, configKey, arg2)
                    if enemy then
                        enemy.boss = true
                        table.insert(list, enemy)
                    end
                    break
                end
            end
        end
        if applyFx.final and tonumber(applyFx.final.wave) == arg2 and applyFx.final.cfg then
            local enemy = Simulator.enemy(applyFx, applyFx.final.cfg, arg2)
            if enemy then
                enemy.boss = true
                table.insert(list, enemy)
            end
        end
    end
    local starfall = applyFx.fx and applyFx.fx.starfall
    local starGolem = starfall and applyFx.cfgById and applyFx.cfgById.star_golem_1
    local perWave = starfall and tonumber(starfall.perWave) or 0
    if starGolem and perWave > 0 then
        local count = math.floor(arg2 * perWave + 1e-8) - math.floor((arg2 - 1) * perWave + 1e-8)
        for _ = 1, count do
            local enemy = Simulator.enemy(applyFx, starGolem, arg2)
            if enemy then
                local hpMul = tonumber(starfall.hpK) or 1
                enemy.hp, enemy.max = enemy.hp * hpMul, enemy.max * hpMul
                table.insert(list, enemy)
            end
        end
    end
    local countMul = tonumber(applyFx.cal and applyFx.cal.countCal)
    if countMul and not arg3 and math.abs(countMul - 1) > 0.05 and # list > 0 then
        local target = math.max(1, math.floor(# list * countMul + 0.5))
        if target > # list then
            local ordinary = {}
            for _, enemy in ipairs(list) do
                if not enemy.boss then table.insert(ordinary, enemy) end
            end
            if # ordinary > 0 then
                for index = 1, target - # list do
                    table.insert(list, table.clone(ordinary[(index - 1) % # ordinary + 1]))
                end
            end
        elseif target < # list then
            for index = # list, 1, -1 do
                if # list <= target then break end
                if not list[index].boss then table.remove(list, index) end
            end
        end
    end
    local waveYen = Simulator.waveYen(applyFx, arg2)
    applyFx._waveCache = applyFx._waveCache or {}
    local protoList = {}
    for idx, enemy in ipairs(list) do
        protoList[idx] = {
            hp = enemy.hp,
            max = enemy.max,
            speed = enemy.speed,
            bounty = enemy.bounty,
            boss = enemy.boss,
            sh = enemy.sh,
            fly = enemy.fly,
            fire = enemy.fire,
            soar = enemy.soar,
            armor = enemy.armor,
            ice = enemy.ice,
            iceKey = enemy.iceKey,
            iceAvg = enemy.iceAvg,
            regen = enemy.regen,
            bar = enemy.bar,
            split = enemy.split
        }
    end
    applyFx._waveCache[cacheKey] = { list = protoList, yen = waveYen }
    return list, waveYen
end
Simulator._masks = {
}
Simulator._walk = {
}

function Simulator.mapWalk(map)
    if not map then
        return nil
    end
    if Simulator._walk [map] ~= nil then
        return Simulator._walk [map] or nil
    end
    local walk = Brain.maps [map] and tonumber(Brain.maps [map].walk)
    if not walk then
        local list = {
        }
        for key, value in pairs(Brain.simCal) do
            local match = type(value) == "table" and tonumber(value.walk) and (tostring(key):match("^st:([^:]+)") or tostring(key):match("^rd:([^:]+)") or tostring(key):match("^inf:([^:]+)"))
            local level = match and Core.Levels [match]
            if level and level.map == map then
                table.insert(list, tonumber(value.walk))
            end
        end
        if # list > 0 then
            table.sort(list)
            walk = list [math.ceil(# list / 2)]
        end
    end
    if not walk then
        local hive = Reports.hive()
        local value = hive and type(hive.mapInfo) == "table" and hive.mapInfo [map]
        if type(value) == "table" and (tonumber(value.runs) or 0) >= 3 then
            walk = tonumber(value.walk)
        end
    end
    Simulator._walk [map] = walk or false
    return walk
end

function Simulator.mask(map, range)
    local value = math.max(5, math.min(60, math.floor((range or 10) / 5 + 0.5) * 5))
    local text = tostring(map) .. ":" .. value
    if Simulator._masks [text] then
        return Simulator._masks [text]
    end
    local map2 = Brain.maps [map] or Brain.maps [tostring(map):match("^(.-)~%d+$") or ""]
    local bin = map2 and map2.bins and map2.bins [tostring(value)]
    local list = {
    }
    if type(bin) == "string" and # bin == Simulator.BINS then
        for i = 1, Simulator.BINS do
            list [i] = bin:sub(i, i) == "1"
        end
        local value2 = map2.binsL and map2.binsL [tostring(value)]
        if type(value2) == "table" then
            list.lanes = {
            }
            for key, value in pairs(value2) do
                local list2 = {
                }
                for i = 1, Simulator.BINS do
                    list2 [i] = value:sub(i, i) == "1"
                end
                list.lanes [key] = list2
            end
        end
    else
        local value2 = math.min(0.7, value / 70)
        for i = 1, Simulator.BINS do
            local ratio = (i - 0.5) / Simulator.BINS
            list [i] = ratio >= 0.1 and ratio <= 0.1 + value2
        end
    end
    Simulator._masks [text] = list
    return list
end

function Simulator.laneList(samples)
    local list, list2 = {
    }, {
    }
    for _, sample in ipairs(samples or {
    }) do
        local lane = tostring(sample.lane)
        if sample.lane ~= nil and not list [lane] then
            list [lane] = true
            table.insert(list2, lane)
        end
    end
    table.sort(list2)
    return # list2 >= 2 and list2 or nil
end

function Simulator.spotMask(layout, spot, range)
    local range2 = math.floor(range + 0.5)
    local text = string.format("%d,%d,%d", spot.X, spot.Z, range2)
    local value = layout.cache [text]
    if value then
        return value
    end
    value = {
    }
    local range22 = range2 * range2
    local flag = Simulator.laneList(layout.samples) ~= nil
    if flag then
        value.lanes = {
        }
    end
    for _, sample in ipairs(layout.samples) do
        local x, z = sample.pos.X - spot.X, sample.pos.Z - spot.Z
        if x * x + z * z <= range22 then
            local bins = math.min(Simulator.BINS, math.floor(sample.prog * Simulator.BINS) + 1)
            value [bins] = true
            if flag then
                local lane = tostring(sample.lane)
                value.lanes [lane] = value.lanes [lane] or {
                }
                value.lanes [lane] [bins] = true
            end
        end
    end
    layout.cache [text] = value
    return value
end

