function Simulator.teamFrom(arg1, map)
    local list = {
    }
    local map2 = Brain.maps [map] or Brain.maps [tostring(map):match("^(.-)~%d+$") or ""]
    local flag = not (map2 and map2.hill == false)
    for _, unitData in ipairs(arg1) do
