function Simulator.profileSig(units)
    local members = {}
    for _, unit in ipairs(units) do
        local trait, tier = Units.trait(unit)
        table.insert(members, string.format("%q:%q:%q:%q:%q:%q:%q",
            tostring(unit.uuid), tostring(unit.unit_id), tostring(unit.xp), tostring(trait),
            tostring(tier), tostring(unit._equipped_relic), tostring(unit.skin and unit.skin._skin_id)))
    end
    table.sort(members)
    return table.concat(members, ",")
end
Simulator.WALK_STUDS = 1.9

function Simulator.boxBins(arg1, range, count)
    local ratio = 2 * (range or 0) * (tonumber(arg1.walk) or Simulator.PRIOR.walk) / Simulator.WALK_STUDS
    return math.max(1, math.min(count, math.floor(ratio * Simulator.BINS + 0.5)))
end
Simulator._holds, Simulator._holdsFrom = {
}, {
}

function Simulator.holds(id)
    local hold = Simulator._holds [id]
    if hold == nil then
        hold = false
        local ok, res = pcall(Units.toggleOf, id)
        if ok and res then
            hold, Simulator._holdsFrom [id] = true, tonumber(res.from) or 1
        end
        local rows = not hold and Units.rows(id)
        for i = 0, rows and rows.max or - 1 do
            local row = rows [i]
            local flag, value = false, nil
            if row then
                flag, value = pcall(Units.attackInfo, row.atk, row.range)
            end
            if flag and value and ((value.stun or 0) > 0 or (value.slowTime or 0) > 0) then
                hold, Simulator._holdsFrom [id] = true, i
                break
            end
        end
        Simulator._holds [id] = hold
    end
    return hold, Simulator._holdsFrom [id]
end
Simulator.GALE_SLOW = 0.3

function Simulator.memoOn()
    Simulator.memo, Simulator.memoAt = setmetatable({
    }, {
        __mode = "k"
    }), os.clock()
end

function Simulator.run(info, teamFrom, arg3)
    local memo = Simulator.memo
    if memo and os.clock() - (Simulator.memoAt or 0) > 180 then
        Simulator.memo, memo = nil, nil
    end
    if not memo then
        return Simulator.runRaw(info, teamFrom, arg3)
    end
    for key in pairs(arg3 or {
    }) do
        if key ~= "hpMul" and key ~= "fusionSave" then
            return Simulator.runRaw(info, teamFrom, arg3)
        end
    end
    local list = {}
    for _, value in ipairs(teamFrom) do
        list[#list + 1] = Simulator.profileSig({value.u})
    end
    table.sort(list)
    local joined = tostring(info.zone) .. "|" .. tostring(arg3 and arg3.hpMul or 1) .. "|" .. tostring(arg3 and arg3.fusionSave or false) .. "|" .. table.concat(list, ",")
    local lvlKey = info._memoKey or info
    local value = memo[lvlKey]
    if not value then
        value = {
        }
        memo[lvlKey] = value
    end
    local runRaw = value [joined]
    if not runRaw then
        runRaw = Simulator.runRaw(info, teamFrom, arg3)
        value [joined] = runRaw
        Simulator.memoMiss = (Simulator.memoMiss or 0) + 1
    else
        Simulator.memoHit = (Simulator.memoHit or 0) + 1
    end
    return runRaw
end

function Simulator.runRaw(arg1, arg2, arg3)
    arg3 = arg3 or {
    }
    local hpMul = arg3.hpMul or 1
    local dt = Simulator.DT
    local count = 0
    if arg3.layout and arg3.layout.laneList == nil then
