function Match.summonWorth()
    if Match.summonAvg == nil then
        local count, count2, count3 = 0, 0, 0
        for _, value in ipairs(Units.equipped()) do
            local ok, res = pcall(Units.dps, value.u, 0, Match.mod)
            count, count2, count3 = count + ((not Units.isFarm(value.id) and ok and res) or 0), count2 + 1, count3 + (value.data.cost or 0)
        end
        Match.summonAvg, Match.summonCost = count2 > 0 and count / count2 or 0, count2 > 0 and count3 / count2 or 0
    end
    local bestRate = Match.bestRate or 0
    return bestRate <= 0 or Match.summonAvg * 2 >= bestRate * (10000 + Match.summonCost)
end

function Match.hasGeneral()
    for _, unit in ipairs(Match.mine or {
    }) do
