function Match.ritualWorth()
    local ritual = Brain.fh.ritual
    return ritual and ritual.n >= 2 and ritual.ratio / ritual.n or nil
end

function Match.ritualTarget()
    local mergePlan = Match.mergePlan
    local list = {
    }
    for _, unit in ipairs(Match.mine) do
        local idValue = unit._stats.id.Value
        if not Units.isFarm(idValue) and not Units.allyBuff(idValue) and not Units.idol(idValue) and not (mergePlan and mergePlan.id == idValue) and not (Match.airLow() and Match.canAir(unit)) then
            local ok, res = pcall(Match.liveDps, unit, idValue)
            if ok and res and res > 0 then
                table.insert(list, {
                    m = unit,
                    dps = res
                })
            end
        end
    end
    if # list < 3 then
        return nil
    end
    table.sort(list, function(arg1, arg2)
        return arg1.dps > arg2.dps
    end)
    local ritualWorth = Match.ritualWorth()
    if not ritualWorth then
        return list [3].m, "a test: how strong the Divine General comes out of this unit"
    end
    if ritualWorth >= 1.5 then
        return list [1].m, string.format("the Divine General came out at %.1f× the unit's damage before", ritualWorth)
    end
    return nil
end
Match.ADAPT_ORDER = {
    "Divine Wings",
    "Adapted Slash",
    "Heavenly Force"
