function Match.adapt()
    if not getconnections then
        return
    end
    local flag = false
    for _, unit in ipairs(Match.mine or {
    }) do
        if unit._stats.id.Value == "mahoraga" then
            flag = true
            break
        end
    end
    if not flag then
        return
    end
    if not (Match.adaptPrompt and Match.adaptPrompt.Parent) then
        Match.adaptPrompt = nil
        local playerGui = LocalPlayer:FindFirstChild("PlayerGui")
        for _, desc in ipairs(playerGui and playerGui:GetDescendants() or {
        }) do
            if desc.Name == "MahoragaAdaptationPrompt" and not desc:FindFirstAncestorOfClass("Configuration") then
                Match.adaptPrompt = desc
                break
            end
        end
    end
    local adaptPrompt = Match.adaptPrompt
    if not (adaptPrompt and adaptPrompt:IsA("GuiObject") and adaptPrompt.Visible) then
        Match.adaptTries = 0
        return
    end
    Match.adaptTries = (Match.adaptTries or 0) + 1
    if Match.adaptTries > 3 then
        return
    end
    local list = {
    }
    for _, desc in ipairs(adaptPrompt:GetDescendants()) do
        if desc:IsA("TextLabel") and desc.Name == "Mode" and desc.Parent then
            list [desc.Text] = desc.Parent
        end
    end
    for _, value in ipairs(Match.ADAPT_ORDER) do
        local item = list [value]
        local item2 = item and (item:IsA("GuiButton") and item or item:FindFirstChildWhichIsA("GuiButton", true))
        if item2 and item.Visible then
            local count = 0
            for _, value in ipairs({
                item2.Activated,
                item2.MouseButton1Click,
                item2.MouseButton1Down
            }) do
                for _, getconnection in ipairs(getconnections(value)) do
                    if pcall(function()
                        getconnection:Fire()
                    end) then
                        count = count + 1
                    end
                end
            end
            App.log(1, "SPELL", string.format("Divine General adapts: %s (%d click handler%s, try %d)", value, count, count == 1 and "" or "s", Match.adaptTries))
            return
        end
    end
end

function Match.newUnitMeasure(arg1, _arg2, arg3, arg4, arg5)
    task.spawn(function()
        local value
        for i = 1, 10 do
            task.wait(1)
            for _, child in ipairs(workspace._UNITS:GetChildren()) do
                local stats = child:FindFirstChild("_stats")
                if not arg5 [child] and stats and stats:FindFirstChild("player") and stats.player.Value == LocalPlayer and stats:FindFirstChild("damage") and (arg1 == "ritual" or stats.id.Value == arg4.id) then
                    value = child
                    break
                end
            end
            if value then
                task.wait(1)
                break
            end
        end
        if not value then
            App.log(2, "SPELL", (Match.SPELL_NAMES [arg1] or arg1) .. ": couldn't find the new unit to measure")
            return
        end
        local stats = value._stats
        local ok, res = pcall(Match.liveDps, value, stats.id.Value)
        res = ok and tonumber(res) or 0
        local totalSpentValue = stats:FindFirstChild("total_spent") and tonumber(stats.total_spent.Value) or 0
        local value2 = Brain.fh [arg1] or {
            n = 0,
            ratio = 0,
            spent = 0
        }
        if arg4.dps > 0 then
            value2.n, value2.ratio, value2.spent = value2.n + 1, value2.ratio + res / arg4.dps, value2.spent + (arg4.spent > 0 and totalSpentValue / arg4.spent or 0)
        end
        Brain.fh [arg1] = value2
        App.log(1, "SPELL", string.format("%s result: %s at level %s does %s damage a second (%s had %s at level %d) · ¥%s in it (%s had ¥%s) · %.0f studs away", Match.SPELL_NAMES [arg1] or arg1, Units.name(stats.id.Value), tostring(stats:FindFirstChild("upgrade") and stats.upgrade.Value or "?"), Utils.fmt(res), arg3, Utils.fmt(arg4.dps), arg4.lvl, Utils.fmt(totalSpentValue), arg3, Utils.fmt(arg4.spent), (Utils.flat(value:GetPivot().Position) - Utils.flat(arg4.pos)).Magnitude))
    end)
end

