function Match.makeRoom()
    local session = Core.session()
    if not (Match.random and session) or Match.spellBusy then
        return
    end
    local list = {
    }
    for ingameSpellKey, ingameSpell in pairs(session.ingame_spells or {
    }) do
        list [ingameSpell] = (list [ingameSpell] or 0) + 1
        local ritualWorth = Match.ritualWorth()
        local num = ingameSpell == "ritual" and ((ritualWorth and ritualWorth < 1.5) and 0 or 1) or (ingameSpell == "sacrifice" and Match.mergePlan) and 2 or 1
        if (ingameSpell == "summon" or ingameSpell == "gate") and not Match.summonWorth() then
            num = 0
        end
        if ingameSpell == "ritual" and Match.hasGeneral() then
            num = 0
        end
        if ingameSpell == "sell_refund" and Match.wave() < 22 and Match.fieldCount() < 18 then
            num = 0
        end
        if list [ingameSpell] > num then
            if App.request("discard", "delete_ingame_spell", ingameSpellKey) and (task.wait(0.3) and (Core.session().ingame_spells or {
            }) [ingameSpellKey] ~= ingameSpell) then
                local str = num > 0 and "one is enough in the hand" or ingameSpell == "ritual" and (Match.hasGeneral() and "a Divine General is already on the field" or "the Divine General came out too weak") or ingameSpell == "sell_refund" and "Refund is for late waves" or "not worth its price now"
                App.log(1, "SPELL", string.format("discarded %s (%s) for a new card", Match.SPELL_NAMES [ingameSpell] or tostring(ingameSpell), str))
            end
            return
        end
    end
    if Match.fieldCount() < (Match.effectiveFieldMax or Match.FIELD_MAX) or Utils.now() - (Match.roomSoldAt or - 99) < 15 then
        return
    end
    local unit, value
    for _, member in ipairs(Match.team) do
        if member.hand and not Units.isFarm(member.id) and (Match.noSpot [member.uuid] or 0) < 3 then
            local cardValue = Match.cardValue(member)
            if not value or cardValue > value then
                unit, value = member, cardValue
            end
        end
    end
    local value2 = math.max(0, (Match.total or 30) - Match.wave())
    local mergePlan = Match.mergePlan
    local value3, value4
    if unit and (tonumber(unit.data.override_hitbox_radius) or 0) > 3 and not Match.bestSpot(unit, true, false) then
        Match.noSpot [unit.uuid] = 3
        unit = nil
    end
    local airLow = Match.airLow()
    for _, unit in ipairs(Match.mine) do
        local idValue = unit._stats.id.Value
        local unit2 = Core.Units [idValue]
        if unit2 and (tonumber(unit2.cost) or 0) > 0 and not unit2.unsellable and not Units.allyBuff(idValue) and not Units.idol(idValue) and not (mergePlan and mergePlan.id == idValue) and not (airLow and Match.canAir(unit)) then
            local huge
            if Units.isFarm(idValue) then
                local farmAmountValue = unit._stats:FindFirstChild("farm_amount") and tonumber(unit._stats.farm_amount.Value) or 0
                huge = (Match.bestRate or 0) > 0 and farmAmountValue * value2 * Match.bestRate or math.huge
            else
                local ok, res = pcall(Match.liveDps, unit, idValue)
                huge = ok and res or math.huge
            end
            if not value4 or huge < value4 then
                value3, value4 = unit, huge
            end
        end
    end
    Match.roomPlan = nil
    if unit and value3 and value > 2 * value4 then
        local value
        for ingameSpellKey, ingameSpell in pairs(session.ingame_spells or {
        }) do
            if ingameSpell == "sell_refund" then
                value = ingameSpellKey
            end
        end
        local totalSpentValue = value3._stats:FindFirstChild("total_spent") and tonumber(value3._stats.total_spent.Value) or 0
        local cost = (unit.data.cost or 0) - totalSpentValue * (value and 1 or 0.5)
        local name = Units.name(value3._stats.id.Value)
        if Match.money() >= cost then
            local ok = value and App.request("spell", "use_ingame_spell", value, value3) or (not value and App.request("sell", "sell_unit_ingame", value3))
            if ok then
                App.log(1, "PLACE", string.format("made room: sold %s%s for %s (2× the damage or more)", name, value and " (full refund)" or "", Units.name(unit.id)))
                Match.roomSoldAt = Utils.now()
                Match.noSpot = {}
                task.wait(0.6)
                Match.scan()
                Match.place(unit, "the spot just made for it")
            end
        else
            Match.roomPlan = {
                name = Units.name(unit.id),
                out = name,
                need = cost
            }
        end
        return
    end
    if not FarmHub.every("discard", 20) then
        return
    end
    local value, value2
    for _, member in ipairs(Match.team) do
        if member.hand and not Units.idol(member.id) and not Match.mergeIds [member.id] then
            local num = Units.isFarm(member.id) and 0 or Match.cardDps(member)
            if not value2 or num < value2 then
                value, value2 = member, num
            end
        end
    end
    if value and Match.discardCard(value) then
        App.log(2, "PLACE", "discarded " .. Units.name(value.id) .. " from the hand (the field is full, it isn't worth a spot)")
    end
end
