function Match.refund()
    local session = Core.session()
    if not (Match.random and session) or Match.spellBusy or Match.roomPlan or not FarmHub.every("refund", 20) then
        return
    end
    local value
    for ingameSpellKey, ingameSpell in pairs(session.ingame_spells or {
    }) do
        if ingameSpell == "sell_refund" then
            value = ingameSpellKey
        end
    end
    if not value then
        return
    end
    local flag = (Match.pressure or 0) >= math.min(Config.dangerReach, ((Match.depth and Match.depth.units > 0 and Match.depth.covEnd) or 1) * 0.9)
    local bestRate = Match.bestRate or 0
    if flag or bestRate <= 0 then
        return
    end
    local wave = Match.wave()
    local value2 = math.max(0, (Match.total or 30) - wave)
    local mergePlan = Match.mergePlan
    local airLow = Match.airLow()
    local value3, value4, value5
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local idValue = stats.id.Value
        local unit2 = Core.Units [idValue]
        local totalSpentValue = stats:FindFirstChild("total_spent") and tonumber(stats.total_spent.Value) or 0
        if unit2 and not unit2.unsellable and totalSpentValue > 0 and not Units.allyBuff(idValue) and not Units.idol(idValue) and not (mergePlan and mergePlan.id == idValue) then
            local totalSpentValue2, text
            if Units.isFarm(idValue) then
                local farmAmountValue = stats:FindFirstChild("farm_amount") and tonumber(stats.farm_amount.Value) or 0
                local farmAmountValue2 = farmAmountValue * value2
                if totalSpentValue > farmAmountValue2 * 1.2 then
                    totalSpentValue2 = (totalSpentValue - farmAmountValue2) * bestRate
                    text = string.format("a farm that still pays ¥%s but gives back ¥%s now", Utils.fmt(farmAmountValue2), Utils.fmt(totalSpentValue))
                end
            elseif wave >= 10 and value2 > 2 and totalSpentValue >= 5000 and (Match.upRate [unit] or 0) < bestRate / 3 and Match.progressAt(unit:GetPivot().Position) < 0.8 and not (airLow and Match.canAir(unit)) then
                local ok, res = pcall(Match.liveDps, unit, idValue)
                res = ok and res or math.huge
                if totalSpentValue * bestRate > 3 * res and res < 0.1 * (Match.teamDps or 0) then
                    totalSpentValue2 = totalSpentValue * bestRate - res
                    text = string.format("its ¥%s buys over 3× its damage in upgrades", Utils.fmt(totalSpentValue))
                end
            end
            if totalSpentValue2 and (not value4 or totalSpentValue2 > value4) then
                value3, value4, value5 = unit, totalSpentValue2, text
            end
        end
    end
    if not value3 then
        return
    end
    Match.spellBusy = true
    task.spawn(function()
        local name = Units.name(value3._stats.id.Value)
        local ok = App.request("spell", "use_ingame_spell", value, value3)
        task.wait(1.5)
        if ok and (Core.session().ingame_spells or {
        }) [value] ~= "sell_refund" then
            Match.refunds = (Match.refunds or 0) + 1
            App.log(1, "SPELL", string.format("Refund on %s — %s", name, value5))
            App.status("Abilities", "Refund on " .. name)
        else
            App.backoff("spell", 15)
            App.log(2, "SPELL", "Refund wasn't taken on " .. name)
        end
        Match.spellBusy = false
    end)
end

function Match.bossStep()
    Match.focus = nil
    if Match.random then
        return
    end
    local enemies = Match.enemies or {
    }
    local hasBossNow = false
    for _, en in ipairs(enemies) do
        if en.boss and (en.prog or 0) >= 0.45 then
            hasBossNow = true
            break
        end
    end
    local isFinalWave = not Match.infinite and Match.total and Match.wave() >= Match.total
    if not isFinalWave and not (hasBossNow and #enemies <= 3) then
        return
    end
    for _, enemy in ipairs(enemies) do
        local humanoid = enemy.m and enemy.m:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.MaxHealth > ((Match.bossTop and Match.bossTop.hp) or 0) then
            local stats = enemy.m:FindFirstChild("_stats")
            Match.bossTop = {
                hp = humanoid.MaxHealth,
                id = stats and stats:FindFirstChild("id") and stats.id.Value,
                regen = stats and stats:FindFirstChild("Regen") and stats.Regen.Value
            }
        end
    end
    if # enemies <= 2 and Match.bossTop and not Match.bossSaid then
        Match.bossSaid = true
        pcall(function()
            local count = 0
            if Match.info then
                for _, value in ipairs((Simulator.wave(Match.info, Match.total))) do
                    if value.boss and value.hp > count then
                        count = value.hp
                    end
                end
            end
            App.log(1, "MATCH", string.format("the boss: %s, %.3g HP, heals %s%% a second · the simulator plays one of %.3g HP", tostring(Match.bossTop.id), Match.bossTop.hp, tostring(Match.bossTop.regen), count))
        end)
    end
    if # enemies == 0 or # enemies > 2 then
        Match.focusTrack = nil
        return
    end
    local value, num = nil, 1
    for _, enemy in ipairs(enemies) do
        if not value or enemy.hp > value.hp then
            value = enemy
        end
        num = math.min(num, enemy.prog)
    end
    Match.focus = {
        pos = value.pos,
        prog = value.prog,
        fly = value.fly,
        m = value.m
    }
    local now = Utils.now()
    local focusTrack = Match.focusTrack
    if not focusTrack or focusTrack.m ~= value.m then
        Match.focusMoved = {}
        Match.focusTrack = {
            m = value.m,
            t = now,
            hp = value.hp,
            prog = value.prog
        }
        return
    end
    if now - focusTrack.t >= 10 then
        focusTrack.net, focusTrack.rate = (focusTrack.hp - value.hp) / (now - focusTrack.t), (value.prog - focusTrack.prog) / (now - focusTrack.t)
        focusTrack.t, focusTrack.hp, focusTrack.prog = now, value.hp, value.prog
    end
    if not focusTrack.rate or focusTrack.rate <= 0 then
        return
    end
    local flat = Utils.flat(value.pos)
    local list, list2, count, count2 = {
    }, {
    }, 0, 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        local idValue = stats.id.Value
        local unit2 = Core.Units [idValue]
        if not Units.isFarm(idValue) and not Units.allyBuff(idValue) and not Units.BLESS.by [idValue] and unit2 and not unit2.unsellable and stats:FindFirstChild("range") then
            local flat2, rangeValue = Utils.flat(unit:GetPivot().Position), stats.range.Value
            local flag = not value.fly or Match.canAir(unit)
            if (flat2 - flat).Magnitude <= rangeValue and flag then
                count = count + 1
            end
            if not ((flat2 - flat).Magnitude <= rangeValue and flag) then
                local prog
                for _, sample in ipairs(Match.samples) do
                    if sample.prog >= num and ((sample.flat or Utils.flat(sample.pos)) - flat2).Magnitude <= rangeValue and (not prog or sample.prog < prog) then
                        prog = sample.prog
                    end
                end
                local totalSpentValue = stats:FindFirstChild("total_spent") and tonumber(stats.total_spent.Value) or 0
                local value2 = Match.focusMoved and (Match.focusMoved [unit] or Match.focusMoved [idValue])
                local flag2 = totalSpentValue <= 2.5 * (tonumber(unit2.cost) or 0)
                if prog and flag then
                    count2 = count2 + 1
                end
                if not prog or not flag then
                    if not value2 then
                        table.insert(list, {
                            m = unit,
                            id = idValue,
                            spent = totalSpentValue
                        })
                    end
                elseif not value2 and flag2 then
                    table.insert(list2, {
                        m = unit,
                        id = idValue,
                        spent = totalSpentValue,
                        eta = (prog - value.prog) / focusTrack.rate
                    })
                end
            end
        end
    end
    local ratio = (1 - value.prog) / focusTrack.rate
    Match.focusLeft, Match.focusInRange = ratio, count
    local value2 = focusTrack.net and (focusTrack.net <= 0 or value.hp / focusTrack.net > ratio * 0.8)
    if value2 and FarmHub.every("bossBehind", 30) then
        App.log(1, "MATCH", string.format("boss: %s HP left, %s HP a second after its regen, at the base in %ds, %d units reach it: moving units up to it", Utils.fmt(value.hp), Utils.fmt(focusTrack.net), math.floor(ratio), count))
    end
    local seed = tostring(Brain.dg.room and Brain.dg.room.seed)
    Brain.dg.bails = type(Brain.dg.bails) == "table" and Brain.dg.bails or {
    }
    if Match.kind == "dungeon" and not Match.bailed and Config.bailOut ~= false and (count2 == 0 or ratio < 15) and focusTrack.net and ratio > 4 and ratio < 60 and (tonumber(Brain.dg.bails [seed]) or 0) < 3 then
        local humanoid = value.m and value.m:FindFirstChildOfClass("Humanoid")
        local maxHealth = humanoid and humanoid.MaxHealth or value.hp
        local player = workspace:FindFirstChild("_BASES") and workspace._BASES:FindFirstChild("player")
        local fakeUnit = player and player:FindFirstChild("base") and player.base:FindFirstChild("fake_unit")
        local humanoid = fakeUnit and fakeUnit:FindFirstChildOfClass("Humanoid")
        local health = humanoid and humanoid.Health or (Match.info and tonumber(Match.info.baseHp)) or 100
        local baseRel = (Match.info and tonumber(Match.info.baseRel)) or Simulator.PRIOR.baseRel
        local hp = value.hp - math.max(0, focusTrack.net) * ratio
        local ratio = health / math.max(1, baseRel * maxHealth)
        local ratio2 = hp / math.max(1, focusTrack.net)
        if hp > 0 and (focusTrack.net <= 0 or ratio2 > ratio * 1.3) then
            Match.bailed = true
            Brain.dg.bails [seed] = (tonumber(Brain.dg.bails [seed]) or 0) + 1
            Brain.dg.bail = {
                sig = Modes.teamSig(),
                at = os.time()
            }
            pcall(Match.styleRecord, false)
            App.log(1, "MATCH", string.format("bailing out: the boss would reach the base with %s HP, your units deal %s a second to it and the base would last %ds against it: back to the lobby to keep the life", Utils.fmt(hp), Utils.fmt(focusTrack.net), math.floor(ratio)))
            App.flush()
            App.request("lobby", "teleport_back_to_lobby")
            return
        end
    end
    local item, str
    if count == 0 and ratio < 30 then
        return
    end
    if list [1] and FarmHub.every("bossSell", 2) then
        table.sort(list, function(arg1, arg2)
            return arg1.spent < arg2.spent
        end)
        item, str = list [1], count > 0 and "the boss has walked past it: its money goes to the units that reach it" or "the boss has walked past it"
    elseif value2 and list2 [1] and ratio >= 30 and FarmHub.every("bossSell", 8) then
        table.sort(list2, function(arg1, arg2)
            return arg1.eta > arg2.eta
        end)
        if list2 [1].eta > 15 then
            item, str = list2 [1], string.format("the boss wouldn't reach it for %ds", math.floor(list2 [1].eta))
        end
    end
    if item then
        local _, res = App.request("sell", "sell_unit_ingame", item.m)
        if res == true then
            Match.focusMoved = Match.focusMoved or {
            }
            Match.focusMoved [item.m] = true
            Match.noSpot = {}
            App.log(1, "PLACE", string.format("boss: sold %s, ¥%s spent on it, to move up: %s", Units.name(item.id), Utils.fmt(item.spent), str))
        end
    end
end

function Match.focusSpot(unit)
    local focus = Match.focus
    if focus and focus.fly then
        local airFrom = Units.airFrom(unit.id)
        if not Match.cardAir(unit.id) and (not airFrom or airFrom > 2) then
            return nil, 0
        end
    end
    local range = Units.range(unit.u, 0) * ((Match.info and Match.info.rangeScale) or 1)
    local flat = Utils.flat(focus.pos)
    local value, value2
    local count = 0
    for _, cand in ipairs(Match.cands) do
        if (Utils.flat(cand) - flat).Magnitude <= range then
            local valid = Match.valid(cand, unit.data)
            count = count + 1
            if count % 40 == 0 then
                task.wait()
            end
            if valid then
                local count, flat = 0, Utils.flat(valid)
                for _, sample in ipairs(Match.samples) do
                    if sample.prog >= focus.prog and ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= range then
                        count = count + 1
                    end
                end
                if not value2 or count > value2 then
                    value, value2 = valid, count
                end
            end
        end
    end
    return value, value2 or 0
end

function Match.focusGain(arg1)
    local focus = Match.focus
    if not focus then
        return 1
    end
    local stats = arg1._stats
    if not stats:FindFirstChild("range") then
        return 1
    end
    local flat, rangeValue = Utils.flat(arg1:GetPivot().Position), stats.range.Value
    if focus.fly and not Match.canAir(arg1) then
        return 0.02
    end
    if (flat - Utils.flat(focus.pos)).Magnitude <= rangeValue then
        return 1
    end
    return (flat - Utils.flat(focus.pos)).Magnitude <= rangeValue * 1.5 and 0.3 or 0.02
end
Match.cashTried = setmetatable({
}, {
    __mode = "k"
})

function Match.lastWaveCash()
    if Match.infinite or not Match.total or Match.spellBusy then
        return
    end
    local curWave = Match.wave()
    local isFinal = curWave >= Match.total
    local isPreFinalCrisis = (curWave == Match.total - 1) and ((Match.pressure or 0) >= Config.safeReach or (Match.depth and Match.depth.leak))
    if not isFinal and not isPreFinalCrisis then
        return
    end
    local session = Core.session()
    local value
    for ingameSpellKey, ingameSpell in pairs((session and session.ingame_spells) or {
    }) do
        if ingameSpell == "sell_refund" then
            value = ingameSpellKey
        end
    end
    local farms = {}
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local unit2 = Core.Units [stats.id.Value]
        if Units.isFarm(stats.id.Value) and not (unit2 and unit2.unsellable) and (Match.cashTried [unit] or 0) < 2 then
            local totalSpentValue = stats:FindFirstChild("total_spent") and tonumber(stats.total_spent.Value) or 0
            local farmAmt = stats:FindFirstChild("farm_amount") and tonumber(stats.farm_amount.Value) or 0
            if isFinal or (totalSpentValue * 0.25 > farmAmt * 1.5) then
                table.insert(farms, { m = unit, spent = totalSpentValue })
            end
        end
    end
    if #farms == 0 then
        return
    end
    table.sort(farms, function(a, b) return a.spent > b.spent end)
    for idx, entry in ipairs(farms) do
        local farmUnit, farmSpent = entry.m, entry.spent
        if not farmUnit.Parent then continue end
        Match.cashTried [farmUnit] = (Match.cashTried [farmUnit] or 0) + 1
        local name = Units.name(farmUnit._stats.id.Value)
        if value and idx == 1 then
            Match.spellBusy = true
            local ok = App.request("spell", "use_ingame_spell", value, farmUnit)
            Match.spellBusy = false
            value = nil
            if ok then
                Match.noSpot = {}
                App.log(1, "SPELL", string.format("last wave: Refund on %s — ¥%s back (farms don't pay after this wave)", name, Utils.fmt(farmSpent)))
            end
        else
            local _, res = App.request("sell", "sell_unit_ingame", farmUnit)
            if res == true then
                Match.noSpot = {}
                App.log(1, "PLACE", string.format("%s: sold %s, ¥%s spent on it (yen goes into damage)", isFinal and "last wave" or "crisis wave", name, Utils.fmt(farmSpent)))
            elseif Match.cashTried [farmUnit] >= 2 then
                App.log(1, "PLACE", string.format("last wave: the game won't sell %s here", name))
            end
        end
        if idx < #farms then task.wait(0.25) end
    end
end
Match.mergeIds = {
}

function Match.mergeScan()
    Match.mergePlan, Match.mergeIds = nil, {
    }
    if not Match.random then
        return
    end
    local session = Core.session()
    local flag = false
    Match.cloneCard = false
    for _, ingameSpell in pairs((session and session.ingame_spells) or {
    }) do
        if ingameSpell == "sacrifice" then
            flag = true
        elseif ingameSpell == "clone" then
            Match.cloneCard = true
        end
    end
    local list = {
    }
    local noMerge = Brain.fh.noMerge or {
    }
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        local idValue = stats.id.Value
        if not Units.isFarm(idValue) and not Units.allyBuff(idValue) and not Units.idol(idValue) and stats:FindFirstChild("max_upgrade") and (noMerge [idValue] or 0) < 2 then
            local ok, res = pcall(Match.liveDps, unit, idValue)
            list [idValue] = list [idValue] or {
            }
            table.insert(list [idValue], {
                m = unit,
                lvl = stats.upgrade.Value,
                max = stats.max_upgrade.Value,
                dps = ok and res or 0
            })
        end
    end
    local list2 = {
    }
    for _, member in ipairs(Match.team or {
    }) do
        if member.hand then
            list2 [member.id] = true
        end
    end
    local list3 = {
    }
    for itemKey, item in pairs(list) do
        table.sort(item, function(arg1, arg2)
            if arg1.dps ~= arg2.dps then
                return arg1.dps > arg2.dps
            end
            return arg1.lvl > arg2.lvl
        end)
        table.insert(list3, {
            id = itemKey,
            dps = item [1].dps * Match.airBoost(item [1].m) * Match.reach(item [1].m)
        })
    end
    table.sort(list3, function(arg1, arg2)
        return arg1.dps > arg2.dps
    end)
    for i = 1, math.min(3, # list3) do
        Match.mergeIds [list3 [i].id] = true
    end
    local value
    for itemKey, item in pairs(list) do
        local item2 = table.clone(item)
        table.sort(item2, function(arg1, arg2)
            if arg1.lvl ~= arg2.lvl then
                return arg1.lvl < arg2.lvl
            end
            return arg1.dps < arg2.dps
        end)
        for i, value in ipairs(item2) do
            if value.m == Match.freshM and i > 1 then
                table.remove(item2, i)
                table.insert(item2, 1, value)
                break
            end
        end
        local value2, value3, value4, value5
        for _, value in ipairs(item2) do
            local flat, rangeValue = Utils.flat(value.m:GetPivot().Position), value.m._stats.range.Value
            local count, count2, value6 = 0, 0, nil
            for _, value2 in ipairs(item) do
                if value2 ~= value and (Utils.flat(value2.m:GetPivot().Position) - flat).Magnitude <= rangeValue then
                    count, count2 = count + value2.dps, count2 + 1
                    if not value6 or value2.dps > value6.dps then
                        value6 = value2
                    end
                end
            end
            if count2 > 0 then
                value2, value3, value4, value5 = value, count, count2, value6
                break
            end
        end
        value5 = value5 or item [1]
        local dps = value5.dps * Match.airBoost(value5.m) * Match.reach(value5.m) * (itemKey == Match.planId and 2 or 1)
        if (Match.mergeIds [itemKey] or itemKey == Match.planId) and (value2 or list2 [itemKey]) and (not value or dps > value.score) then
            value = {
                id = itemKey,
                top = value5,
                fresh = value2,
                near = value3 or 0,
                n = value4 or 0,
                coming = list2 [itemKey],
                score = dps
            }
        end
    end
    Match.planId, Match.freshM = value and value.id, value and value.fresh and value.fresh.m
    Match.mergeHeldAt = (flag and value and value.fresh) and (Match.mergeHeldAt or Match.wave()) or nil
    if not value then
        return App.status("Merge", "no second copy of a strong unit yet")
    end
    local wave, total = Match.wave(), (Match.total or 30) - Match.wave()
    local flag2 = (Match.pressure or 0) >= math.min(Config.dangerReach, ((Match.depth and Match.depth.units > 0 and Match.depth.covEnd) or 1) * 0.9)
    local fresh = value.fresh
    local value2 = not flag2 and total > 3
    value.waits = fresh and fresh.lvl <= value.top.lvl and value.top.lvl < value.top.max and value2 or false
    local value22 = (not fresh or fresh.lvl >= value.top.lvl) and value.coming and value2
    local value23 = Match.cloneCard and value.top.lvl >= value.top.max and value2
    local value2 = fresh and fresh.lvl > value.top.lvl and value.near < 0.3 * fresh.dps
    value.ready = flag and fresh ~= nil and not value2 and (not (value.waits or value22 or value23) or wave - (Match.mergeHeldAt or wave) >= 5)
    Match.holdNoCardAt = (value.waits and not flag) and (Match.holdNoCardAt or wave) or nil
    value.hold = value.waits and (flag or wave - (Match.holdNoCardAt or wave) < 4)
    Match.mergePlan = value
    App.status("Merge", fresh and string.format("%s: merge %d cop%s into the one with %d upgrades %s", Units.name(value.id), value.n, value.n == 1 and "y" or "ies", fresh.lvl, value.ready and "now" or (flag and "once the top copy is maxed" or "when a Merge card comes")) or string.format("%s: a second copy in the hand goes next to it", Units.name(value.id)))
end

function Match.mergeHold(arg1)
    local mergePlan = Match.mergePlan
    return mergePlan and mergePlan.hold and mergePlan.fresh and mergePlan.fresh.m == arg1 or false
end

function Match.mergeBoost(arg1)
    local mergePlan = Match.mergePlan
    if not (mergePlan and mergePlan.top.m == arg1 and (mergePlan.fresh or mergePlan.coming)) then
        return 1
    end
    return Match.mergeHeldAt and 2 or 1.3
end

function Match.mergeSpot(unit)
    if not (Match.random and Match.mergeIds [unit.id]) then
        return nil
    end
    local value, value2
    for _, unit2 in ipairs(Match.mine or {
    }) do
        if unit2._stats.id.Value == unit.id then
            local ok, res = pcall(Match.liveDps, unit2, unit.id)
            res = ok and res or 0
            if not value2 or res > value2 then
                value, value2 = unit2, res
            end
        end
    end
    return value and value:GetPivot().Position
end

function Match.mergeMeasure(arg1)
    local mergeBefore = Match.mergeBefore
    if not mergeBefore then
        return
    end
    task.delay(2, function()
        if not (arg1 and arg1.Parent) then
            return
        end
        local ok, res = pcall(Match.liveDps, arg1, arg1._stats.id.Value)
        if not ok then
            return
        end
        local own = mergeBefore.own + 1.5 * mergeBefore.near
        local merge = Brain.fh.merge or {
            n = 0,
            ratio = 0
        }
        if own > 0 then
            merge.n, merge.ratio = merge.n + 1, merge.ratio + res / own
        end
        Brain.fh.merge = merge
        local idValue = arg1._stats.id.Value
        Brain.fh.noMerge = Brain.fh.noMerge or {
        }
        local res2, value = res - mergeBefore.own, 1.5 * mergeBefore.near
        if value > 0 and res2 < 0.1 * value then
            Brain.fh.noMerge [idValue] = (Brain.fh.noMerge [idValue] or 0) + 1
        elseif value > 0 and res2 >= 0.5 * value then
            Brain.fh.noMerge [idValue] = nil
        end
        App.log(1, "SPELL", string.format("Merge result: %s went from %s to %s damage a second at %d upgrades (its own + 1.5× the copies' %s = %s expected; the top copy had %d)", Units.name(arg1._stats.id.Value), Utils.fmt(mergeBefore.own), Utils.fmt(res), mergeBefore.lvl, Utils.fmt(mergeBefore.near), Utils.fmt(own), mergeBefore.top))
    end)
end

function Match.farmMergeOk()
    local farmMerge = Brain.fh.farmMerge
    if not (farmMerge and farmMerge.n > 0) then
        return true
    end
    return farmMerge.ratio / farmMerge.n >= 0.8
end

function Match.farmMergePair()
    local list = {
    }
    for _, unit in ipairs(Match.mine or {
    }) do
        local idValue = unit._stats.id.Value
        if Units.isFarm(idValue) and unit._stats:FindFirstChild("farm_amount") then
            list [idValue] = list [idValue] or {
            }
            table.insert(list [idValue], unit)
        end
    end
    for _, item in pairs(list) do
        if # item >= 2 then
            table.sort(item, function(arg1, arg2)
                return arg1._stats.upgrade.Value < arg2._stats.upgrade.Value
            end)
            for _, value in ipairs(item) do
                local flat, rangeValue = Utils.flat(value:GetPivot().Position), value._stats.range.Value
                local count, count2 = 0, 0
                for _, value2 in ipairs(item) do
                    if value2 ~= value and (Utils.flat(value2:GetPivot().Position) - flat).Magnitude <= rangeValue then
                        count, count2 = count + (tonumber(value2._stats.farm_amount.Value) or 0), count2 + 1
                    end
                end
                if count2 > 0 then
                    return value, count, count2
                end
            end
        end
    end
end

function Match.farmMergeSpot(unit)
    if not (Match.random and Match.farmMergeOk()) then
        return nil
    end
    for _, unit2 in ipairs(Match.mine or {
    }) do
        if unit2._stats.id.Value == unit.id then
            return unit2:GetPivot().Position, tonumber(unit2._stats.range.Value) or 0
        end
    end
end

function Match.farmMergeMeasure(arg1)
    local farmMergeBefore = Match.farmMergeBefore
    if not farmMergeBefore then
        return
    end
    task.delay(2, function()
        if not (arg1 and arg1.Parent) then
            return
        end
        local farmAmountValue = tonumber(arg1._stats.farm_amount.Value) or 0
        local own = farmMergeBefore.own + 1.5 * farmMergeBefore.inc
        local farmMerge = Brain.fh.farmMerge or {
            n = 0,
            ratio = 0
        }
        farmMerge.n, farmMerge.ratio = farmMerge.n + 1, farmMerge.ratio + (own > 0 and farmAmountValue / own or 0)
        Brain.fh.farmMerge = farmMerge
        App.log(1, "SPELL", string.format("Farm merge result: %s pays ¥%s a wave now (it paid ¥%s and took in farms paying ¥%s; keeping 1.5× would make ¥%s)", Units.name(arg1._stats.id.Value), Utils.fmt(farmAmountValue), Utils.fmt(farmMergeBefore.own), Utils.fmt(farmMergeBefore.inc), Utils.fmt(own)))
    end)
end
Match.IDOL_PRIOR = {
    dmg = 0.05,
    cost = 0.05
}

function Match.idolStep()
    local idol = Brain.fh.idol
    local dmg, cost = Match.IDOL_PRIOR.dmg, Match.IDOL_PRIOR.cost
    if idol and idol.n > 0 then
        dmg, cost = idol.dmg / idol.n, idol.cost / idol.n
    end
    return math.max(0, dmg) + math.max(0, cost) * 0.5
end

function Match.idolMeasure()
    local value
    for _, unit in ipairs(Match.mine) do
        local idValue = unit._stats.id.Value
        local damage = unit._stats:FindFirstChild("damage")
        if not Units.isFarm(idValue) and not Units.idol(idValue) and damage and damage.Value > 0 then
            value = unit
            break
        end
    end
    if not value then
        return
    end
    local stats = value._stats
    local function helper()
        local ok, res = pcall(Core.USC.calculate_upgrade_cost_multiplier, value, Core.session())
        local buffDamageMultiplierValue = stats:FindFirstChild("buff_damage_multiplier") and tonumber(stats.buff_damage_multiplier.Value) or 0
        return stats.damage.Value * (1 + buffDamageMultiplierValue), ok and tonumber(res) or nil
    end
    local value2, value3 = helper()
    local upgradeValue = stats.upgrade.Value
    task.delay(3, function()
        if not value.Parent or stats.upgrade.Value ~= upgradeValue then
            return
        end
        local value, value4 = helper()
        if not (value3 and value4 and value3 > 0 and value2 > 0) then
            return
        end
        if value == value2 and value4 == value3 then
            return App.log(2, "UPGRADE", "Idol upgrade: no change seen yet, not counted")
        end
        local idol = Brain.fh.idol or {
            n = 0,
            dmg = 0,
            cost = 0
        }
        idol.n, idol.dmg, idol.cost = idol.n + 1, idol.dmg + (value / value2 - 1), idol.cost + (1 - value4 / value3)
        Brain.fh.idol = idol
        App.log(1, "UPGRADE", string.format("Idol upgrade measured on %s: %+.1f%% damage, upgrades %.1f%% cheaper", Units.name(stats.id.Value), (value / value2 - 1) * 100, (1 - value4 / value3) * 100))
    end)
end

function Match.spells()
    local session = Core.session()
    local ingameSpells = session and session.ingame_spells
    if type(ingameSpells) ~= "table" or Match.spellBusy then
        return
    end
    local money = Match.money()
    local flag = (Match.pressure or 0) >= math.min(Config.dangerReach, ((Match.depth and Match.depth.units > 0 and Match.depth.covEnd) or 1) * 0.9)
    local value, value2, value3
    for _, unit in ipairs(Match.mine) do
        local idValue = unit._stats.id.Value
        if not Units.isFarm(idValue) and not Units.allyBuff(idValue) and idValue ~= "mahoraga" then
            local ok, res = pcall(Match.liveDps, unit, idValue)
            local res2 = ok and res and res * Match.airBoost(unit) * Match.reach(unit)
            if res2 and (not value3 or res2 > value3) then
                value, value2, value3 = unit, res, res2
            end
        end
    end
    local mergePlan = Match.mergePlan
    local list = {
    }
    for ingameSpellKey, ingameSpell in pairs(ingameSpells) do
        table.insert(list, {
            slot = ingameSpellKey,
            spell = ingameSpell,
            rank = Match.SPELL_ORDER [ingameSpell] or 9
        })
    end
    table.sort(list, function(arg1, arg2)
        return arg1.rank < arg2.rank
    end)
    Match.spellWant = nil
    Match.cloneNote = nil
    for _, item in ipairs(list) do
        local slot, spell = item.slot, item.spell
        local value2, str
        local value3
        for _, unit in ipairs(Match.mine) do
            if unit._stats.id.Value == "mahoraga" then
                value3 = unit
            end
        end
        local value4 = value3 and (Match.buffCount [value3] or 0) < 2
        if spell == "random_buff" and money >= 1000 and (value4 or value) then
            if value4 then
                value2, str = value3, "the Divine General (two buffs make it a boss killer; its range is only 8.5)"
            else
                value2, str = value, "+100% attack or range on your strongest unit"
            end
        elseif spell == "sacrifice" and mergePlan and mergePlan.ready then
            if money >= 1000 then
                value2, str = mergePlan.fresh.m, string.format("the %d other cop%s in its range (it keeps 1.5× their damage through its own upgrades)", mergePlan.n, mergePlan.n == 1 and "y" or "ies")
                Match.mergeBefore = {
                    own = mergePlan.fresh.dps,
                    near = mergePlan.near,
                    lvl = mergePlan.fresh.lvl,
                    top = mergePlan.top.lvl
                }
            else
                Match.spellWant = Match.spellWant or {
                    cost = 1000,
                    why = "Merge on " .. Units.name(mergePlan.id)
                }
            end
        elseif spell == "sacrifice" and money >= 1000 and not flag and not (mergePlan and mergePlan.fresh) and Match.farmMergeOk() and Match.farmMergePair() then
            local farmMergePair, farmMergePair2, farmMergePair3 = Match.farmMergePair()
            value2 = farmMergePair
            str = string.format("the %d other %s in its reach (does a farm keep their income?)", farmMergePair3, Units.name(farmMergePair._stats.id.Value))
            Match.farmMergeBefore = {
                own = tonumber(farmMergePair._stats.farm_amount.Value) or 0,
                inc = farmMergePair2
            }
        elseif spell == "clone" then
            local value3 = not flag and mergePlan and mergePlan.fresh and mergePlan.top.lvl < mergePlan.top.max
            Match.cloneWaitAt = value3 and (Match.cloneWaitAt or Match.wave()) or nil
            local value4 = value3 and Match.wave() - Match.cloneWaitAt < 5
            local m, str2
            if not flag and mergePlan and mergePlan.fresh and mergePlan.top.lvl >= mergePlan.top.max then
                m, str2 = mergePlan.top.m, "a maxed copy for the Merge to take in"
            elseif not value4 and value then
                m, str2 = value, flag and "a copy of your strongest unit: instant damage with enemies near the base" or "a copy of your strongest unit (two copies make a Merge)"
            end
            if value4 then
                Match.cloneNote = string.format("waits for %s to max (%d/%d, up to %d more waves)", Units.name(mergePlan.id), mergePlan.top.lvl, mergePlan.top.max, 5 - (Match.wave() - Match.cloneWaitAt))
            end
            if m and money >= 5000 then
                value2, str = m, str2
            elseif m then
                local ok, res = pcall(Match.liveDps, m, m._stats.id.Value)
                res = ok and tonumber(res) or 0
                if res >= (Match.bestRate or 0) * 5000 * 0.5 then
                    Match.spellWant = Match.spellWant or {
                        cost = 5000,
                        why = "Clone of " .. Units.name(m._stats.id.Value),
                        rate = res / 5000
                    }
                    Match.cloneNote = "saving for a copy of " .. Units.name(m._stats.id.Value)
                else
                    Match.cloneNote = string.format("a copy of %s (%s dps) is worth less than ¥5k of upgrades (%s)", Units.name(m._stats.id.Value), Utils.fmt(res), Utils.fmt((Match.bestRate or 0) * 5000))
                end
            end
        elseif spell == "ritual" and not flag and Match.wave() >= 8 and not Match.hasGeneral() then
            local ritualTarget, ritualTarget2 = Match.ritualTarget()
            if ritualTarget and money >= 10000 then
                value2, str = ritualTarget, ritualTarget2
            elseif ritualTarget then
                Match.spellWant = Match.spellWant or {
                    cost = 10000,
                    why = "a Ritual (" .. ritualTarget2 .. ")"
                }
            end
        elseif spell == "summon" and money >= 10000 and not flag and Match.summonWorth() then
            value2, str = false, "a unit from your own team"
        elseif spell == "gate" and money >= 2500 and not flag and Match.summonWorth() then
            value2, str = false, "3× the odds of Astral Summon"
        end
        if str then
            Match.spellBusy = true
            local list = {
            }
            for _, child in ipairs(workspace._UNITS:GetChildren()) do
                list [child] = true
            end
            local value
            if value2 then
                local stats = value2._stats
                local ok, res = pcall(Match.liveDps, value2, stats.id.Value)
                value = {
                    id = stats.id.Value,
                    pos = value2:GetPivot().Position,
                    dps = ok and tonumber(res) or 0,
                    lvl = stats.upgrade.Value,
                    spent = stats:FindFirstChild("total_spent") and tonumber(stats.total_spent.Value) or 0
                }
            end
            task.spawn(function()
                local ok
                if value2 then
                    ok = App.request("spell", "use_ingame_spell", slot, value2)
                else
                    ok = App.request("spell", "use_ingame_spell", slot)
                end
                task.wait(1.5)
                local name = value2 and Units.name(value2._stats.id.Value) or ""
                if ok and (Core.session().ingame_spells or {
                }) [slot] ~= spell then
                    App.log(1, "SPELL", string.format("%s%s — %s", Match.SPELL_NAMES [spell] or tostring(spell), value2 and (" on " .. name) or "", str))
                    App.status("Abilities", string.format("spell %s%s — %s", Match.SPELL_NAMES [spell] or tostring(spell), value2 and (" on " .. name) or "", str))
                    if spell == "sacrifice" then
                        if value and Units.isFarm(value.id) then
                            pcall(Match.farmMergeMeasure, value2)
                        else
                            pcall(Match.mergeMeasure, value2)
                        end
                    end
                    if spell == "random_buff" and value2 then
                        Match.buffCount [value2] = (Match.buffCount [value2] or 0) + 1
                    end
                    if (spell == "clone" or spell == "ritual") and value then
                        pcall(Match.newUnitMeasure, spell, value2, name, value, list)
                    end
                else
                    App.backoff("spell", 15)
                    App.log(2, "SPELL", tostring(spell) .. " wasn't taken" .. (value2 and (" on " .. name) or ""))
                end
                Match.spellBusy = false
            end)
            return
        end
    end
end

function Match.trainCount()
    local on = Brain.train.on
    if not (on and Match.trainee) then
        return
    end
    local count = 0
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local uuidValue = stats:FindFirstChild("uuid") and stats.uuid.Value
        local findFirstChild = uuidValue == Match.trainee and stats:FindFirstChild(on.what == "kills" and "kill_count" or "takedown_count")
        if findFirstChild then
            count = count + (tonumber(findFirstChild.Value) or 0)
        end
    end
    Match.trainTk = math.max(Match.trainTk or 0, count)
    App.status("Training", string.format("%s: %d %s this match · %s/%s", Units.name(on.id), Match.trainTk, on.what, Utils.fmt(on.have + (on.got or 0) + Match.trainTk), Utils.fmt(on.need)))
end

function Match.trainDone(arg1, arg2)
    local on = Brain.train.on
    if not (on and Match.trainee) then
        return
    end
    Match.trainCount()
    local trainTk = Match.trainTk or 0
    on.got = (on.got or 0) + trainTk
    local tk = Brain.trainSim [arg1] and tonumber(Brain.trainSim [arg1].tk)
    if not Match.joinedMid then
        local value = Brain.train.real [arg1] or {
            n = 0,
            sum = 0
        }
        value.n, value.sum = value.n + 1, value.sum + trainTk
        Brain.train.real [arg1] = value
        if tk and tk > 0 then
            local cal = Brain.train.cal
            cal.real, cal.sim, cal.n = (cal.real or 0) + trainTk, (cal.sim or 0) + tk, (cal.n or 0) + 1
        end
    end
    table.insert(Brain.train.log, 1, {
        key = arg1,
        got = trainTk,
        won = arg2,
        at = os.time()
    })
    while # Brain.train.log > 20 do
        table.remove(Brain.train.log)
    end
    App.log(1, "TRAIN", string.format("%s: +%d %s this run (%s%s) · %s/%s", Units.name(on.id), trainTk, on.what, arg2 and "won" or "lost", tk and string.format(", the simulator said ≈%d", tk) or "", Utils.fmt(Training.realHave(on)), Utils.fmt(on.need)))
    if not arg2 then
        Brain.train.bad [arg1] = os.time() + 6 * 3600
        App.log(1, "TRAIN", "the training team lost here: no training in this mode for 6 h")
    end
end

function Match.sampleNamekTest()
    local test = Match.namekTest
    if not test then return end
    local now = Utils.now()
    local elapsed = test.lastSample and math.min(2, now - test.lastSample) or 0
    test.lastSample = now
    test.wave = Match.wave()
    for _, tower in ipairs(Match.mine) do
        local stats = tower._stats
        local id = stats.id.Value
        if id == Units.FUSION.hero then test.fusionWave = test.fusionWave or test.wave end
        if not Units.isFarm(id) and not Units.allyBuff(id) then
            local _, damageType = Units.types(id)
            local amount = tonumber(stats:GetAttribute("_dmg_buff_" .. damageType)) or 0
            test.peak = math.max(test.peak, amount)
            test.observed += elapsed
            if amount >= 0.99 then test.full += elapsed end
        end
    end
end

function GUI.namekTestText()
    local test = Match.namekTest or Brain.namekTest
    if not test then return "No test yet." end
    if not test.wave then
        return os.time() - test.armedAt <= 900 and "Armed. Enter Namek Infinite within 15 minutes." or "The test expired. Arm it again."
    end
    return string.format("%s · wave %d\nPeak buff +%d%% · +100%% uptime %.0f%%\nSupport chosen %d / %d compared buys\n%s\nFused Hero: %s",
        test.finished and "Finished" or (Match.namekTest and "Running" or "Interrupted"), test.wave, math.floor(test.peak * 100 + 0.5),
        100 * test.full / math.max(1, test.observed), test.supportChoices, test.comparisons,
        test.lastChoice or "No support vs attacker purchase observed yet",
        test.fusionWave and ("wave " .. tostring(test.fusionWave)) or "not observed")
end

function Match.finish()
    if Match.finished then
        return
    end
    Match.finished = true
    if Match.namekTest then
        Match.sampleNamekTest()
        Match.namekTest.finished = true
        Brain.namekTest = Match.namekTest
        App.log(1, "TEST", GUI.namekTestText():gsub("\n", " · "))
        App.saveNow()
    end
    local result
    local now = Utils.now()
    local function confirmed(result)
        return type(result) == "table" and type(result.victory) == "boolean"
    end
    while App.alive and Utils.now() - now < 8 do
        local ui = Core.GUIS.results_ui
        if confirmed(Match.result) then
            result = Match.result
        elseif ui and confirmed(ui.settings) then
            result = ui.settings
        end
        if result then break end
        task.wait(0.25)
    end
    if not result then
        App.log(1, "RESULT", "game finished without a confirmed result; no match stats recorded")
        Brain.pending, Brain.startTeam = nil, nil
        App.saveNow()
        if App.alive and Config.master and Config.play then
            App.request("lobby", "teleport_back_to_lobby")
        end
        return
    end
    local victory = result.victory
    local wave = Match.infinite and Match.wave() or nil
    if wave then
        victory = true
    end
    local key = Match.key
    local rec = Modes.rec(key)
    local canLearn = not (Match.joinedMid or Match.stopping or Match.trialId or Match.random or Match.hadCompany)
    local live = Modes.liveChallenge(key)
    local sameRotation = live and Match.rotation and Match.rotation == tostring(live.uuid)
    if sameRotation and not Match.joinedMid then
        local record = rec.rotationStats
        if not record or record.rotation ~= Match.rotation then
            record = { rotation = Match.rotation, runs = 0, wins = 0, sec = 0, timed = 0, streak = 0 }
            rec.rotationStats = record
        end
        record.runs = record.runs + 1
        record.wins = record.wins + (victory and 1 or 0)
        record.streak = victory and 0 or record.streak + 1
        if canLearn then record.soloStreak = victory and 0 or (record.soloStreak or 0) + 1 end
    end
    if wave and not Match.joinedMid and not Match.stopping then
        rec.waveSum, rec.waveN = (tonumber(rec.waveSum) or 0) + wave, (tonumber(rec.waveN) or 0) + 1
        rec.waveBest = math.max(tonumber(rec.waveBest) or 0, wave)
    end
    if wave and (tonumber(Brain.infResults) or 0) < 3 and type(result) == "table" then
        Brain.infResults = (tonumber(Brain.infResults) or 0) + 1
        local list = {
        }
        for key, value in pairs(result) do
            table.insert(list, type(value) == "table" and (key .. "{…}") or (key .. "=" .. tostring(value)))
        end
        table.sort(list)
        App.log(1, "MATCH", "Infinite result fields: " .. table.concat(list, ", "))
    end
    local stats = type(result.stats) == "table" and result.stats or {}
    local resources = type(result.resource_reward) == "table" and result.resource_reward or {}
    local value = math.max(0, tonumber(stats.time_taken) or (os.clock() - (Match.startClock or os.clock())))
    local gemReward = (tonumber(result.gem_reward) or 0) + (tonumber(result.first_completion_gems) or 0)
    local currentEventResource = Core.GS.CURRENT_EVENT_RESOURCE or "AprilCoins"
    local resource = tonumber(resources[currentEventResource]) or 0
    if not Match.joinedMid then
        rec.runs = rec.runs + 1
        if victory then
            rec.wins = rec.wins + 1
            rec.streak = 0
        elseif Match.kind == "event" and resource > 0 then
            rec.streak = 0
        else
            rec.streak = (rec.streak or 0) + 1
        end
        rec.sec = rec.sec + value
        rec.timed = (tonumber(rec.timed) or 0) + 1
        if sameRotation then
            rec.rotationStats.sec = rec.rotationStats.sec + value
            rec.rotationStats.timed = rec.rotationStats.timed + 1
        end
    end
    if victory then
        if Match.ld._gamemode == "story" or Match.kind == "raid" then
            Brain.cleared [Match.ld.id .. ":" .. tostring(Match.ld._difficulty or "Normal")] = os.time()
        end
        if sameRotation then live.doneUuid = live.uuid end
    end
    for key, value in pairs(Brain.cleared) do
        if os.time() - value > 86400 then
            Brain.cleared [key] = nil
        end
    end
    rec.gems = rec.gems + gemReward
    rec.coins = rec.coins + resource
    rec.last = os.time()
    local lossStreak = live and (sameRotation and rec.rotationStats and rec.rotationStats.streak or 0) or (rec.streak or 0)
    local flag = not Match.joinedMid and lossStreak >= Config.restAfterLosses and Match.kind ~= "dungeon" and Match.kind ~= "portal" and not Match.trialId and not (Config.dailyLoop and key == "dc")
    if flag then
        rec.restUntil, rec.restWhy = os.time() + 6 * 3600, "losses"
        rec.restRotation = Match.rotation
        App.log(1, "MODE", Match.label() .. ": lost " .. lossStreak .. " in a row — resting it for 6 h")
    end
    if not victory and sameRotation and not Match.joinedMid then
        live.lost = (live.lost or 0) + 1
    end
    Brain.totals.matches = (Brain.totals.matches or 0) + 1
    if not Match.joinedMid then
        if victory then
            Brain.totals.wins = Brain.totals.wins + 1
        else
            Brain.totals.losses = Brain.totals.losses + 1
        end
    end
    Brain.totals.gems = (Brain.totals.gems or 0) + gemReward
    Brain.totals.coins = (Brain.totals.coins or 0) + resource
    local list = {
    }
    for _, item in pairs(type(result.new_items) == "table" and result.new_items or {}) do
        if type(item) == "table" then
            local id = item.item_id or item.id
            if type(id) == "string" or type(id) == "number" then
                id = tostring(id)
                list[id] = (list[id] or 0) + (tonumber(item.amount) or 1)
            end
        elseif type(item) == "string" or type(item) == "number" then
            local id = tostring(item)
            list[id] = (list[id] or 0) + 1
        end
    end
    local label = Match.label()
    if Match.kind == "dungeon" and not Match.joinedMid then
        local ok, res = pcall(Dungeon.roomDone, victory)
        if not ok then
            App.log(1, "ERROR", "dungeon: " .. tostring(res))
        end
    end
    if canLearn then
        pcall(Match.spotResult, victory)
    end
    Brain.lastResult = {
        won = victory,
        text = string.format("%s · %s · wave %s · %dm%02ds",
        label,
        victory and "won" or "lost",
        tostring(stats.waves_completed or Match.wave()),
        math.floor(value / 60),
        math.floor(value % 60)),
        gems = gemReward,
        coins = resource,
        items = list,
        at = os.time()
    }
    table.insert(Brain.history, 1, {
        key = key,
        won = victory,
        sec = value,
        gems = gemReward,
        coins = resource,
        at = os.time()
    })
    while # Brain.history > 30 do
        table.remove(Brain.history)
    end
    Brain.lastMatch = {
        label = label,
        spent = Match.spent,
        actions = # Match.actions,
        refusals = Match.refusals or 0,
        at = os.time()
    }
    if canLearn and not Match.trainee then
        local ok, err = pcall(Match.learn)
        if not ok then App.log(1, "ERROR", "unit learning: " .. tostring(err)) end
    end
    local ok, res = pcall(Match.trainDone, key, victory)
    if not ok then
        App.log(1, "ERROR", "training: " .. tostring(res))
    end
    local flag, value2 = true, nil
    if Match.hunt then
        local ok, res = pcall(Match.huntRecord, result, resource, victory, value)
        if not ok then
            App.log(1, "ERROR", "hunt record: " .. tostring(res))
        end
    end
    if Match.random then
        pcall(Match.fhRecord, resource, victory)
    elseif canLearn and not Match.trainee then
        flag, value2 = pcall(Match.calMerge, victory)
    end
    if not flag then
        App.log(1, "ERROR", "sim calibration: " .. tostring(value2))
    end
    Reports.record({
        mode = key,
        won = victory,
        sec = math.floor(value),
        wave = Match.wave(),
        gems = gemReward,
        coins = resource,
        mid = Match.joinedMid or nil
    })
    App.log(1, "RESULT", string.format("%s — %s, +%d gems%s, ¥%s spent, %d refused spots", label, wave and ("reached wave " .. wave) or (victory and "WON" or "LOST"), gemReward, resource > 0 and (", +" .. resource .. " " .. currentEventResource) or "", Utils.fmt(Match.spent), Match.refusals or 0))
    if Brain.watch and Brain.watch.key == key then
        Brain.watch.won = victory and true or false
        App.saveNow()
    end
    local testTeam = Brain.testTeam
    local same = testTeam and (testTeam.left or 0) > 0 and testTeam.key == key and type(testTeam.uuids) == "table"
        and Training.same(Match.teamUuids or {}, testTeam.uuids)
    if same and not (Match.joinedMid or Match.stopping) then
        testTeam.left = testTeam.left - 1
        testTeam.runs = testTeam.runs or {
        }
        local damageLine = Match.damageLine() or ""
        table.insert(testTeam.runs, {
            won = victory,
            wave = Match.wave(),
            sec = value,
            at = os.time(),
            dmg = damageLine
        })
        App.log(1, "TEST", string.format("%s: run %d of %d %s at wave %d in %.1f min · %s", tostring(testTeam.label), # testTeam.runs, tonumber(testTeam.n) or # testTeam.runs, victory and "WON" or "LOST", Match.wave(), value / 60, damageLine))
        if testTeam.left <= 0 then
            App.log(1, "TEST", tostring(testTeam.label) .. ": done, the usual team picking is back")
        end
        App.saveSoon()
    end
    if canLearn and not same and not Match.trainee and not wave and (not live or sameRotation) then
        local uuids = table.clone(Match.teamUuids or {})
        if # uuids > 0 then
            table.sort(uuids)
            local identity = table.concat(uuids, ",")
            if victory then
                local sameTeam = rec.winSig == identity and rec.winProfile == Match.teamProfile
                    and rec.winRotation == Match.rotation
                rec.winTeamN = sameTeam and (tonumber(rec.winTeamN) or 0) + 1 or 1
                rec.winTeam, rec.winSig = uuids, identity
                rec.winProfile, rec.winRotation = Match.teamProfile, Match.rotation
            elseif rec.winSig == identity and rec.winRotation == Match.rotation
                and (not rec.winProfile or rec.winProfile == Match.teamProfile) then
                rec.winTeam, rec.winSig, rec.winTeamN = nil, nil, nil
                rec.winProfile, rec.winRotation = nil, nil
            end
        end
    end
    local ok, res = pcall(Reports.match, {
        key = key,
        won = victory,
        sec = value,
        gems = gemReward,
        coins = resource,
        items = list
    })
    if not ok then
        App.log(1, "ERROR", "local learning: " .. tostring(res))
    end
    if Match.kind == "portal" then
        pcall(function()
            local list = {
            }
            for _, value in ipairs(Units.equipped()) do
                table.insert(list, Units.name(value.id))
            end
            local pred = Match.pred
            FarmHub.portalLine(string.format("%s · %s at wave %d of %d · predicted %s · team: %s · style %s · modifiers: %s · %s", os.date("%m-%d %H:%M"), victory and "WON" or "LOST", Match.wave(), Match.total or 0, pred and ((pred.won and "a win at " or "a loss at ") .. tostring(pred.wave)) or "nothing", table.concat(list, ", "), tostring(Match.style), tostring(Brain.portalMods or "?"):sub(1, 300), tostring(Match.damageLine() or "")))
        end)
    end
    for key, value in pairs(Match.buffSeen) do
        local count = 0
        for _, level in ipairs(value.levels) do
            count = math.max(count, level)
        end
        App.log(1, "BUFF", string.format("%s cast %d times: your units read %s%% after the casts (highest +%d%%)", Units.name(key), value.casts, table.concat(value.levels, ", "), count))
        local allyBuff = Units.allyBuff(key)
        if allyBuff and allyBuff.attack then
            local count2 = 0
            for _, value in pairs(allyBuff.types or {
            }) do
                count2 = math.max(count2, tonumber(value) or 0)
            end
            local value = Brain.stack [allyBuff.attack]
            if count2 > 0 and count / 100 > count2 + 0.05 and not (value and value.stacks and (tonumber(value.cap) or 0) >= count / 100) then
                Brain.stack [allyBuff.attack] = {
                    stacks = true,
                    cap = math.max(value and value.stacks and tonumber(value.cap) or 0,
                    count / 100),
                    before = count2,
                    after = count / 100,
                    at = os.time(),
                    seen = true
                }
                App.log(1, "BUFF", string.format("%s's buffs stack: +%d%% with one, +%d%% seen with more. Copies now chain up to that", Units.name(key), math.floor(count2 * 100 + 0.5), count))
            end
        end
    end
    local ok, res = pcall(Match.damageLine)
    if ok and res then
        App.log(1, "DAMAGE", res)
    end
    if not Match.random then
        local ok, res, res2 = pcall(Match.damageShares)
        if ok and res and canLearn and not Match.trainee then
            pcall(Strategy.learn, res, Match.team)
        end
        local ok2, res = pcall(Match.summonSplit)
        if canLearn and not Match.trainee and ok2 and res and ok and (res2 or 0) > 0 then
            Brain.str.summon = type(Brain.str.summon) == "table" and Brain.str.summon or {
            }
            for key, value in pairs(res) do
                if value.total >= 0.01 * res2 then
                    local value2 = Brain.str.summon [key]
                    local value3 = (type(value2) == "table" and tonumber(value2.n) or 0) + 1
                    local value4 = math.max(0.2, 1 / value3)
                    Brain.str.summon [key] = {
                        s = type(value2) == "table" and (value2.s + (value.share - value2.s) * value4) or value.share,
                        n = value3
                    }
                end
            end
        end
        Brain.lastRun = {
            key = key,
            at = os.time(),
            xp0 = Match.xp0
        }
    end
    if Match.trialId then
        local ok, res = pcall(Match.trialDone, victory, value)
        if not ok then
            App.log(1, "ERROR", "trial: " .. tostring(res))
            Brain.trial = nil
        end
    end
    local value
    if victory and Match.ld._is_actual_storymode then
        local ok, res = pcall(Core.PSC.get_next_story_level, Match.ld.id)
        if ok and res then
            value = res
            local now = Utils.now()
            while App.alive and Utils.now() - now < 2 do
                if Modes.open(res) then
                    break
                end
                task.wait(0.5)
            end
        end
    end
    local mode = nil
    pcall(function()
        mode = Modes.pick()
    end)
    if mode and mode.kind == "story" and mode.first and value and mode.level ~= value and not Brain.nextMode then
        for _, mode2 in ipairs(Modes.lastScored or {
        }) do
            if mode2.kind == "story" and mode2.first and mode2.level == value and mode2.diff == Match.ld._difficulty and (mode2.baseScore or mode2.score or 0) >= (mode.baseScore or mode.score or 0) * Modes.CHAIN_MIN then
                mode = mode2
                break
            end
        end
    end
    if not mode and value and Config.onlyStory and (Config.pickStory == "" or Config.pickStory == "progress") and Match.ld._difficulty == "Normal" and not Modes.done((Core.prof() or {
    }).level_data or {
    }, value, "Normal") then
        local text = "st:" .. value .. ":Normal"
        mode = {
            key = text,
            kind = "story",
            first = true,
            level = value,
            diff = "Normal",
            label = Modes.levelName(value) .. " (Normal)",
            rec = Modes.rec(text)
        }
    end
    local str, str2 = "lobby", "back to the lobby"
    local victory2 = (Match.ld._gamemode == "story" or Match.ld._gamemode == "infinite" or (Match.kind == "event" and Match.ld._OVERRIDE_CAN_REPLAY)) and victory
    if not Config.play or not Config.master then
        str, str2 = "stay", "Auto Play is off"
    elseif mode and mode.key == key and victory2 then
        str, str2 = "replay", "replaying: still the best mode"
    elseif mode and mode.kind == "story" and Match.ld._is_actual_storymode and victory then
        local ok, res = pcall(Core.PSC.get_next_story_level, Match.ld.id)
        if ok and res == mode.level and mode.diff == Match.ld._difficulty then
            str, str2 = "next_story", "next act: " .. mode.label
        end
    end
    if str ~= "replay" and str ~= "next_story" and mode then
        str2 = "lobby for: " .. mode.label
    end
    local on = Brain.train.on
    if on and Match.trainee and (str == "replay" or str == "next_story") and Training.realHave(on) >= on.need then
        str, str2 = "lobby", "lobby: " .. Units.name(on.id) .. " has its " .. tostring(on.what) .. ", your own team goes back in"
    end
    if Brain.holdLobby and str ~= "stay" then
        str, str2 = "lobby", "lobby: held there: " .. tostring(Brain.holdLobby.why)
    end
    if (str == "replay" or str == "next_story") and mode then
        local ok, res = pcall(FarmHub.matchOn, mode)
        if ok and res then
            str, str2 = "lobby", "lobby: matchmaking again for " .. tostring(mode.label)
        end
    end
    if (str == "replay" or str == "next_story") and Config.smartCharm and mode then
        local ok, res = pcall(Hunt.charmWant, mode)
        if ok and res then
            str, str2 = "lobby", "lobby: putting on the Summer Charm (" .. Hunt.charmWords(res) .. ")"
        end
    end
    if Match.trialId and str ~= "stay" then
        str, str2 = "lobby", Brain.trial and "lobby: the next trial run" or "lobby: your own team goes back in"
    end
    if Brain.buyStorage and str ~= "stay" then
        str, str2 = "lobby", "lobby: buying the unit storage you agreed"
    end
    if Brain.buyOnce and str ~= "stay" then
        str, str2 = "lobby", "lobby: buying the " .. tostring((Core.Items [Brain.buyOnce.item] or {
        }).name or Brain.buyOnce.item) .. " you agreed"
    end
    local value
    if ((Match.kind == "dungeon" and victory) or str == "next_story" or str == "replay") and str ~= "stay" then
        local ok, res = pcall(Strategy.hasWork)
        if ok then
            value = res
        else
            App.log(1, "ERROR", "team work: " .. tostring(res))
        end
        if value then
            str, str2 = "lobby", "lobby: the Units → Upgrades can " .. tostring(value)
        end
    end
    if Match.kind == "dungeon" and str ~= "stay" and mode and mode.key == "dg" and victory and # Units.equipped() >= 6 and not Brain.holdLobby and not Brain.buyStorage and not value then
        Brain.pending = nil
        local saved = App.saveNow()
        App.status("Match", "next dungeon room")
        local flag, flag2 = true, false
        if saved then flag, flag2 = pcall(Dungeon.chain) end
        if not flag then
            App.log(1, "ERROR", "dungeon next room: " .. tostring(flag2))
        end
        if flag and flag2 then
            return
        end
        Brain.startTeam = nil
        str, str2 = "lobby", "lobby: the next dungeon room didn't start from here"
    end
    Brain.pending = (str == "replay" or str == "next_story") and {
        key = mode.key,
        kind = mode.kind,
        level = mode.level,
        diff = mode.diff,
        label = mode.label,
        rotation = Modes.rotation(mode),
        at = os.time()
    } or nil
    if str == "next_story" or str == "replay" then
        Brain.startTeam = {
            train = {
                key = mode.key,
                kind = mode.kind,
                first = mode.first,
                level = mode.level,
                diff = mode.diff,
                label = mode.label
            },
            why = (str == "replay" and "replay: " or "next act: ") .. tostring(mode.label)
        }
    end
    local saved = App.saveNow()
    while not saved and App.alive do
        App.status("Match", "couldn't save match data; retrying")
        task.wait(5)
        saved = App.saveNow()
    end
    if not App.alive then return end
    App.status("Match", str2)
    App.log(1, "MODE", str2)
    if str == "stay" then
        return
    end
    task.wait(2.5)
    if str == "replay" or str == "next_story" then
        local serverToClient = ReplicatedStorage.endpoints.server_to_client
        local flag, flag2 = false, false
        local conn = serverToClient.match_rematch_started.OnClientEvent:Connect(function()
            flag = true
        end)
        local conn2 = serverToClient.match_rematch_ready.OnClientEvent:Connect(function()
            flag2 = true
        end)
        table.insert(App.conns, conn)
        table.insert(App.conns, conn2)
        App.request("vote", "set_game_finished_vote", str)
        local now = Utils.now()
        while App.alive and Utils.now() - now < 30 and not flag do
            task.wait(0.25)
        end
        if flag then
            local now2 = Utils.now()
            while App.alive and Utils.now() - now2 < 60 and not flag2 do
                task.wait(0.25)
            end
            if App.alive then
                App.log(1, "MODE", string.format("the match restarted in place in %.0f s (%s)", Utils.now() - now, str))
                local ok, res = pcall(App.restart)
                if ok then
                    return
                end
                App.log(1, "ERROR", "couldn't start again in place: " .. tostring(res))
            else
                return
            end
        end
    end
    if App.alive then
        App.request("lobby", "teleport_back_to_lobby")
    end
end

function Match.watchMods()
    local ignore = workspace:FindFirstChild("ignore")
    if not ignore then
        return
    end
    local list = {
    }
    local num, flag = - 9, false
    local conn = ignore.ChildAdded:Connect(function(part)
        task.defer(function()
            local gui = part:FindFirstChild("Gui")
            if not (gui and part:IsA("BasePart")) then
                return
            end
            local inst, value
            for _, child in ipairs(workspace._UNITS:GetChildren()) do
                local humanoidRootPart = child:FindFirstChild("HumanoidRootPart")
                if humanoidRootPart then
                    local magnitude = (humanoidRootPart.Position - part.Position).Magnitude
                    if magnitude < 4 and (not value or magnitude < value) then
                        inst, value = child, magnitude
                    end
                end
            end
            local stats = inst and inst:FindFirstChild("_stats")
            if not (stats and stats:FindFirstChild("Armor")) then
                return
            end
            local player = stats:FindFirstChild("player")
            if player and player.Value ~= nil then
                return
            end
            local list2 = {
            }
            for _, value in ipairs({
                "Armor",
                "Ice",
                "Flying",
                "Soaring"
            }) do
                local findFirstChild = stats:FindFirstChild(value)
                list2 [value] = findFirstChild and (tonumber(findFirstChild.Value) or 0) > 0
            end
            if list2.Flying or list2.Soaring then
                return
            end
            local str = (list2.Armor and not list2.Ice and "Armor") or (list2.Ice and not list2.Armor and "Ice") or ((not list2.Armor and not list2.Ice) and "plain") or nil
            if not str then
                return
            end
            if str == "Ice" then
                if os.clock() - num > 2 then
                    num, flag = os.clock(), Hunt.is(Match.ld and Match.ld.id) and Hunt.weatherNow() == "snow"
                end
                if flag then
                    str = "Ice@snow"
                end
            end
            local now = os.clock()
            for _, child in ipairs(gui:GetChildren()) do
                local finalDamage = tonumber(child:GetAttribute("final_damage"))
                if finalDamage and finalDamage > 1 then
                    local flag, text = false, child:FindFirstChild("text")
                    for _, child in ipairs(text and text:GetChildren() or {
                    }) do
                        if child:IsA("ImageLabel") then
                            flag = true
                        end
                    end
                    local name = child.Name
                    local info = {
                        at = now,
                        t = name,
                        dmg = finalDamage,
                        crit = child:GetAttribute("is_crit") and true or false,
                        kind = str,
                        icon = flag,
                        res = tonumber(stats:GetAttribute("_dmg_res_" .. name)) or 0,
                        weak = (tonumber(stats:GetAttribute("_dmg_weak_" .. name)) or 0) + (tonumber(stats:GetAttribute("_dmg_amp_" .. name)) or 0)
                    }
                    if not (str ~= "Armor" and str ~= "plain" and name:find("fire")) then
                        for _, item in ipairs(list) do
                            if now - item.at < 0.05 and item.t == name and item.crit == info.crit and item.res == info.res and item.weak == info.weak then
                                local info2 = (info.kind ~= "plain" and info.icon and info) or (item.kind ~= "plain" and item.icon and item) or nil
                                local info3 = (info.kind == "plain" and not info.icon and info) or (item.kind == "plain" and not item.icon and item) or nil
                                if info2 and info3 then
                                    Match.modPair(info2.kind, info2.dmg / info3.dmg)
                                end
                            end
                        end
                    end
                    table.insert(list, info)
                end
            end
            while list [1] and now - list [1].at > 0.2 do
                table.remove(list, 1)
            end
        end)
    end)
    table.insert(App.conns, conn)
end

function Match.modPair(kind, ratio)
    if ratio <= 0.02 or ratio >= 1.2 then
        return
    end
    local enemyMod = Brain.enemyMods [kind] or {
        r = {
        }
    }
    Brain.enemyMods [kind] = enemyMod
    table.insert(enemyMod.r, ratio)
    while # enemyMod.r > 80 do
        table.remove(enemyMod.r, 1)
    end
    local modRead = Simulator.modRead(enemyMod)
    local value = enemyMod.said and modRead and math.abs(modRead - enemyMod.said) <= enemyMod.said * 0.1
    if modRead and not value then
        enemyMod.said = modRead
    end
    local str, str2 = kind == "Armor" and "Armored" or (kind == "Ice@snow" and "Ice (Blizzard)" or "Ice"), kind == "Armor" and "from full-area attacks" or "from everything but fire"
    if modRead and not value then
        App.log(1, "MATCH", string.format("%s enemies measured from %d real hits: they take ×%.2f %s", str, # enemyMod.r, modRead, str2))
    end
    if modRead == false and not enemyMod.saidLoose then
        enemyMod.saidLoose = true
        local r = table.clone(enemyMod.r)
        table.sort(r)
        App.log(1, "MATCH", string.format("%s enemies: %d real hits so far disagree (×%.2f to ×%.2f), so the simulator doesn't count them until they agree", str, # r, r [1], r [# r]))
    end
end

function Match.startTeam()
    local startTeam = Brain.startTeam
    if type(startTeam) ~= "table" then
        return
    end
    Brain.startTeam = nil
    App.saveSoon()
    App.listenGame()
    if startTeam.train and startTeam.train.key ~= Match.key then
        return
    end
    if startTeam.seed and tostring(Brain.dg.room and Brain.dg.room.seed) ~= tostring(startTeam.seed) then
        return
    end
    local function helper(arg1)
        Match.noBuy = true
        Brain.pending = nil
        App.log(1, "TEAM", string.format("%s: no wave started, back to the lobby (%s)", tostring(arg1), tostring(startTeam.why)))
        App.saveNow()
        for i = 1, 3 do
            App.request("lobby", "teleport_back_to_lobby")
            local now = Utils.now()
            while App.alive and Utils.now() - now < 5 do
                task.wait(0.5)
            end
        end
    end
    if workspace._DATA.GameStarted.Value then
        App.log(1, "TEAM", "too late for a team change before the first wave: " .. tostring(startTeam.why))
        if startTeam.must and not Training.same(Training.team(), startTeam.uuids) then
            helper("the first wave had already started")
        end
        return
    end
    local now = Utils.now()
    local team = Training.team()
    local ok, res = pcall(function()
        if startTeam.train then
            startTeam.train.rec = Modes.rec(startTeam.train.key)
            startTeam.train.ldOverride = Simulator.slim(Match.ld)
            if Config.autoTeam and not FarmHub.teamFor(startTeam.train, FarmHub.QUICK_SEARCH) then
                return false
            end
            Training.apply(startTeam.train)
        elseif startTeam.home then
            Training.home()
        elseif startTeam.own then
            FarmHub.restoreTeam()
        else
            FarmHub.equipTeam(startTeam.uuids, tostring(startTeam.why))
        end
    end)
    local team2 = Training.team()
    local flag = not Training.same(team, team2)
    local gameSaid = App.gameSaid(now)
    if flag or not ok or gameSaid then
        App.log(1, "TEAM", string.format("team change before the first wave (%s): %s in %.1f s%s%s", tostring(startTeam.why), flag and "the game took it" or "nothing changed", Utils.now() - now, gameSaid and (" · the game said: " .. tostring(gameSaid)) or "", ok and "" or (" · error: " .. tostring(res))))
    end
    if ok and res == false then
        helper("the planned team didn't go on")
        return
    end
    if startTeam.must then
        if not ok or # team2 < 6 or not Training.same(team2, startTeam.uuids) then
            helper(string.format("the team for this room didn't go on (%d of 6 units right)", (function()
                local count = 0
                for _, member in ipairs(team2) do
                    if table.find(startTeam.uuids, member) then
                        count = count + 1
                    end
                end
                return count
            end)()))
            return false
        end
        local ok, res = pcall(Strategy.relicsApply)
        if not ok then
            App.log(1, "ERROR", "relics: " .. tostring(res))
        end
    end
    return flag
end

function Match.run()
    App.status("Match", "loading the map")
    local now = Utils.now()
    while App.alive and not (Core.Loader.LevelData and workspace:FindFirstChild("_MAP_CONFIG") and workspace._MAP_CONFIG:FindFirstChild("MapLoaded") and workspace._MAP_CONFIG.MapLoaded.Value) do
        if Utils.now() - now > 60 then
            break
        end
        task.wait(0.5)
    end
    Match.ld = Core.Loader.LevelData or {
    }
    Match.key, Match.kind = Modes.fromLevelData(Match.ld)
    Match.key = Match.key or "?"
    local live = Modes.liveChallenge(Match.key)
    if live and live.uuid ~= nil then
        local actual = Match.ld._challenge_uuid
        if actual ~= nil then
            if tostring(actual) == tostring(live.uuid) or (live.ld and live.ld._challenge_uuid ~= nil
                and tostring(actual) == tostring(live.ld._challenge_uuid)) then
                Match.rotation = tostring(live.uuid)
            end
        elseif Match.key == "ch" and Match.ld.id == live.level and Match.ld._challenge == live.challenge then
            Match.rotation = tostring(live.uuid)
        elseif Match.key == "dc" and Brain.pending and Brain.pending.key == "dc"
            and Brain.pending.rotation == tostring(live.uuid) and os.time() - (tonumber(Brain.pending.at) or 0) < 1200 then
            Match.rotation = tostring(live.uuid)
        end
    end
    Match.hadCompany = # Players:GetPlayers() > 1
    local test = Brain.namekTest
    if test and not test.wave and not test.running and os.time() - test.armedAt <= 900 and Match.key == "inf:namek_infinite" then
        Match.namekTest = test
        test.running = true
        test.wave, test.peak, test.full, test.observed, test.comparisons, test.supportChoices = 0, 0, 0, 0, 0, 0
        App.log(1, "TEST", "Namek Infinite test started")
        App.saveNow()
    end
    if Brain.holdLobby and os.time() - (tonumber(Brain.holdLobby.at) or 0) < 90 then
        App.log(1, "MODE", "this match started just after you pressed Go To Lobby: going back")
        pcall(App.flush)
        App.request("lobby", "teleport_back_to_lobby")
    end
    if Brain.watch and Brain.watch.key == Match.key and os.time() - (tonumber(Brain.watch.at) or 0) > 120 then
        pcall(FarmHub.watchDone)
        for portalKey, portal in pairs(Modes.PORTALS) do
            if Match.key == "inf:" .. portal.from then
                Brain.watch = {
                    key = Match.key,
                    portal = portalKey,
                    item = portal.item,
                    have = Adventure.have(portal.item),
                    held = # Modes.portalsHeld(portalKey),
                    used = false,
                    at = os.time()
                }
            end
        end
    end
    Match.noSpot, Match.refusedRun, Match.unitRefusals = {
    }, {
    }, {
    }
    Match.effectiveFieldMax = nil
    Match.spotRefusalCount = {}
    Match.buffTestBusy = false
    Match.activeBusy = false
    Match.style, Match.styleSig = nil, nil
    Match.refusals = 0
    Match.startClock = os.clock()
    Match.startT = Utils.now()
    Match.placeLog, Match.styleWhy = {
    }, nil
    Match.starRun, Match.stars = nil, nil
    Match.joinedMid = (workspace._DATA.GameStarted.Value and Match.wave() > 2) or workspace._DATA.GameFinished.Value
    local info = {
        weak = {
        },
        strong = {
        }
    }
    for _, value in pairs(Match.ld._weak_against or Match.ld.weak_against or {
    }) do
        if type(value) == "table" then
            info.weak [value.damage_type] = Modes.weakAmp(value.amplification)
        else
            info.weak [value] = 1.5
        end
    end
    for _, value in pairs(Match.ld._strong_against or Match.ld.strong_against or {
    }) do
        info.strong [type(value) == "table" and value.damage_type or value] = true
    end
    if Match.key == "dc" and (Match.ld._daily_challenge_weak_against or Match.ld._daily_challenge_strong_against) then
        info = Modes.dailyMod(Match.ld._challenge_uuid, Match.ld._daily_challenge_weak_against, Match.ld._daily_challenge_strong_against)
    elseif Match.key == "dc" and Match.rotation and Brain.live.daily and Brain.live.daily.mod then
        info = Brain.live.daily.mod
    end
    Match.mod = (next(info.weak) or next(info.strong) or next(info.res or {
    })) and info or Modes.levelMod(Match.ld.id)
    if Match.mod and Match.mod.res then
        local list = {
        }
        for key, value in pairs(Match.mod.weak) do
            table.insert(list, string.format("%s ×%.2f", (key:gsub("_damage", "")), value))
        end
        for key, value in pairs(Match.mod.res) do
            table.insert(list, string.format("%s ×%.2f", (key:gsub("_damage", "")), value))
        end
        table.sort(list)
        App.log(1, "MATCH", (Match.key == "dc" and "the Daily's damage taken by type, as every enemy carries it: " or "this level's weak points, weighted by enemy HP: ") .. table.concat(list, ", "))
    end
    Match.buildPath()
    Match.buildWaves()
    Match.setupChecks()
    Match.buildCandidates()
    Match.random = Match.ld._randomequippedmode ~= nil or Core.session().override_equipped_units ~= nil
    Match.hunt = Hunt.is(Match.ld.id)
    if not Match.random then
        local ok, res = pcall(Match.startTeam)
        if not ok then
            App.log(1, "ERROR", "team change at the start: " .. tostring(res))
        end
    end
    Match.team = Match.random and Match.randomTeam() or Units.equipped()
    if Match.random then
        App.log(1, "MATCH", "this mode deals its own team: " .. # Match.team .. " units in hand")
    end
    pcall(Match.watchHelpers)
    Match.trialId = nil
    do
        local trial = Brain.trial
