        },
        baseRel = {
        },
        alive = {
        },
        spawn = {
        },
        spawnLast = {
        },
        dpsAt = {
        },
        dens = {
        },
        pay = {
        },
        skip = {
        },
        timer = {
        },
        votes = {
        }
    }
    Match.track = setmetatable({
    }, {
        __mode = "k"
    })
    local ok, res = pcall(Simulator.info, Simulator.slim(Match.ld), Match.key, challenge, Match.mod, Match.rotation)
