    end
    if Match.info and Match.kind == "dungeon" then
        local ok, res = pcall(Dungeon.fx, Dungeon.data())
        if ok then
            Simulator.applyFx(Match.info, res)
            local list = {
            }
            for key, value in pairs(Match.mod and Match.mod.weak or {
            }) do
                table.insert(list, string.format("%s ×%.2f", tostring(key):gsub("_damage", ""), value))
            end
            App.log(1, "DUNGEON", string.format("this room's effects: %s · the run's items and curses: %s", # list > 0 and table.concat(list, ", ") or "none", Dungeon.fxText(res)))
        end
    end
    if Match.info and Match.trialId then
        task.spawn(function()
            local list = {
            }
