                App.log(1, "SIM", Match.infinite and string.format("prediction for this run: the base falls at wave %d%s (%.0f min)", res.wave, res.won and "+" or "", res.t / 60) or string.format("prediction for this run: %s at wave %d", res.won and "win" or "loss", res.wave))
            end
        end)
    end
    local serverToClient = ReplicatedStorage.endpoints.server_to_client
    table.insert(App.conns, serverToClient.game_finished.OnClientEvent:Connect(function(arg1)
        Match.result = arg1
    end))
    table.insert(App.conns, serverToClient.show_roguelike_options.OnClientEvent:Connect(function(_arg1, arg2)
        Match.rogueOptions = arg2
    end))
    if serverToClient:FindFirstChild("show_roguelike_vote_result") then
        table.insert(App.conns, serverToClient.show_roguelike_vote_result.OnClientEvent:Connect(function(arg1, arg2)
            if type(arg2) == "table" then
                Match.fhMult = 1 + (tonumber(arg2.candy_multiplier) or 0)
                local list, list2 = {
                }, {
                }
                for _, persistentEffect in pairs(arg2.persistent_effects or {
                }) do
                    if type(persistentEffect) == "table" then
                        table.insert(list, Match.effectText(persistentEffect) .. (persistentEffect.damage_type and (" " .. tostring(persistentEffect.damage_type)) or ""))
                        if persistentEffect.type == "enemy_resistance_specific" and persistentEffect.damage_type then
                            list2 [persistentEffect.damage_type] = (list2 [persistentEffect.damage_type] or 0) + (tonumber(persistentEffect.amount) or 0)
                        end
                    end
                end
                Match.fhEffects, Match.fhResist = list, list2
            end
            Match.fhPicks = Match.fhPicks or {
            }
            table.insert(Match.fhPicks, string.format("w%d %s", Match.wave(), tostring(type(arg1) == "table" and (arg1.title or arg1.name) or arg1)))
        end))
    end
    if serverToClient:FindFirstChild("start_vote_wave_skip") then
        table.insert(App.conns, serverToClient.start_vote_wave_skip.OnClientEvent:Connect(function()
            local calRun = Match.calRun
            if not (calRun and calRun.lastWT and Match.info) then
                return
            end
            local wave = Match.wave()
            local waveCount = # (Simulator.wave(Match.info, wave))
            table.insert(calRun.votes, {
                w = wave,
                t = Utils.now() - calRun.lastWT,
                n = waveCount,
                alive = # (Match.enemies or {
                }),
                out = (tonumber(calRun.spawn [tostring(wave)]) or 0) >= waveCount
            })
        end))
    end
    local label = Match.label()
    App.log(1, "MATCH", string.format("%s · %d waves · %d road samples · %d spots to try%s", label, Match.total, # Match.samples, # Match.cands, Match.joinedMid and " · joined mid-way" or ""))
    App.status("Match", label .. (Brain.pending and Brain.pending.key == Match.key and "" or " (not launched by the farm)"))
    local flag, num, now2 = false, - 1, Utils.now()
    local value, now3 = nil, nil
    while App.alive do
        if Config.master and Config.battle then
            local ok2, res2 = pcall(function()
                Match.hadCompany = Match.hadCompany or # Players:GetPlayers() > 1
                if workspace._DATA.GameFinished.Value then
                    pcall(Match.scan)
                    Match.finish()
                    return
                end
                Match.scan()
                local ok, res = pcall(Match.measure)
                if not ok and FarmHub.every("measErr", 30) then
                    App.log(1, "ERROR", "measure: " .. tostring(res))
                end
                if Config.autoStart and not Match.noBuy and not workspace._DATA.GameStarted.Value and (# Match.mine > 0 or Utils.now() - now > 6) and (not flag or (value and Utils.now() - flag > 6 and Utils.now() - now3 < 60)) then
                    now3 = now3 or Utils.now()
                    local ok, res = App.request("vstart", "vote_start")
                    if ok and value then
                        App.log(1, "MATCH", string.format("the start vote went through %.0f s after the first one failed", Utils.now() - now3))
                    end
                    flag, value = Utils.now(), (not ok) and ((res == "waiting" or res == "slowing down") and value or tostring(res)) or nil
                    if value and Utils.now() - now3 >= 54 then
                        App.log(1, "MATCH", "the start vote kept failing (" .. value .. "): the game starts on its own timer")
                    end
                end
                local roguelike = workspace._DATA:FindFirstChild("Roguelike")
                if roguelike and roguelike:FindFirstChild("WaitingForRoguelikeChoice") and roguelike.WaitingForRoguelikeChoice.Value and FarmHub.every("rogue", 3) then
                    Match.pickRogue()
                end
                if not Match.infinite and FarmHub.every("lastCash", 2) then
                    local ok, res = pcall(Match.lastWaveCash)
                    if not ok and FarmHub.every("lastCashErr", 30) then
                        App.log(1, "ERROR", "last-wave cash-in: " .. tostring(res))
                    end
                end
                if Match.random and FarmHub.every("adapt", 2) then
                    local ok, res = pcall(Match.adapt)
                    if not ok and FarmHub.every("adaptErr", 60) then
                        App.log(1, "ERROR", "adaptation: " .. tostring(res))
                    end
                end
                if Match.random and FarmHub.every("watch", 45) then
                    local ok, res = pcall(Match.watchLine)
                    if not ok and FarmHub.every("watchErr", 60) then
                        App.log(1, "ERROR", "watch line: " .. tostring(res))
                    end
                end
                if Match.random and FarmHub.every("merge", 1) then
                    local ok, res = pcall(Match.mergeScan)
                    if not ok and FarmHub.every("mergeErr", 30) then
                        App.log(1, "ERROR", "merge plan: " .. tostring(res))
                    end
                end
                if FarmHub.every("bossStep", 1) then
                    local ok, res = pcall(Match.bossStep)
                    if not ok and FarmHub.every("bossErr", 30) then
                        App.log(1, "ERROR", "boss step: " .. tostring(res))
                    end
                end
                if not Match.stopping then
                    Match.econ()
                end
                if FarmHub.every("act", 0.5) then
                    Match.actives()
                end
                if Match.namekTest and FarmHub.every("namekTestSample", 1) then
                    Match.sampleNamekTest()
                end
                if FarmHub.every("prio", 2) then
                    local ok, res = pcall(Match.targeting)
                    if not ok and FarmHub.every("prioErr", 30) then
                        App.log(1, "ERROR", "targeting: " .. tostring(res))
                    end
                end
                if Match.trainee and FarmHub.every("train", 2) then
                    pcall(Match.trainCount)
                end
                if Match.random and FarmHub.every("dealt", 2) then
                    Match.team = Match.randomTeam()
                end
                if Match.random and FarmHub.every("dealtStats", 30) then
                    pcall(Units.capture)
                end
                if Match.random and FarmHub.every("room", 3) then
                    local ok, res = pcall(Match.makeRoom)
                    if not ok and FarmHub.every("roomErr", 30) then
                        App.log(1, "ERROR", "make room: " .. tostring(res))
                    end
                    local ok, res = pcall(Match.refund)
                    if not ok and FarmHub.every("refundErr", 30) then
                        App.log(1, "ERROR", "refund: " .. tostring(res))
                    end
                    local ok, res = pcall(Match.fish)
                    if not ok and FarmHub.every("fishErr", 30) then
                        App.log(1, "ERROR", "card fishing: " .. tostring(res))
                    end
                end
                if Config.actives and FarmHub.every("spells", 1) then
                    local ok, res = pcall(Match.spells)
                    if not ok and FarmHub.every("spellErr", 30) then
                        App.log(1, "ERROR", "spells: " .. tostring(res))
                    end
                end
                local wave = Match.wave()
                if Match.random and wave ~= Match.fhWaveSeen then
                    Match.fhWaveSeen = wave
                    pcall(Match.fhSnap)
                end
                if wave ~= num then
                    num, now2 = wave, Utils.now()
                    if Match.infinite then
                        pcall(Match.infWave, wave)
                    end
                end
                local enemyCount = # (Match.enemies or {
                })
                if enemyCount > 0 then
                    Match.emptyAt = nil
                elseif not Match.emptyAt then
                    Match.emptyAt = Utils.now()
                end
                local value = Match.total and wave >= Match.total and (enemyCount > 0 or Utils.now() - Match.emptyAt < 30)
                if workspace._DATA.GameStarted.Value and Utils.now() - now2 > (value and 1800 or 360) then
                    App.log(1, "MATCH", string.format("no progress for %d min — back to the lobby", value and 30 or 6))
                    App.flush()
                    now2 = Utils.now()
                    App.request("lobby", "teleport_back_to_lobby")
                end
            end)
            if not ok2 then
                App.log(1, "ERROR", "match loop: " .. tostring(res2))
                task.wait(1)
            end
        end
        if Match.finished then
            break
        end
        task.wait(0.3)
    end
end

function Reports.record(arg1)
    arg1.v = VERSION
    arg1.at = os.time()
    table.insert(Brain.hiveQueue, arg1)
    while # Brain.hiveQueue > 50 do
        table.remove(Brain.hiveQueue, 1)
    end
end
Reports.SETTINGS_SKIP = {
    seenVersion = true,
    shareNoticed = true,
    shareChosen = true,
    autoTeamChosen = true,
    studiedSeeded = true
}

function Reports.settingsOf()
    local list, count = {
    }, 0
    for defaultKey, default in pairs(Core.DEFAULTS) do
        local value = Config [defaultKey]
        local kind = type(value)
        local flag = kind == "boolean" or kind == "number" or (kind == "string" and # value <= 24 and not value:find("[{}%-]") and not tostring(defaultKey):lower():find("unit"))
        if value ~= default and flag and not Reports.SETTINGS_SKIP [defaultKey] and not tostring(defaultKey):find("At$") and not tostring(defaultKey):find("Sig$") then
            list [defaultKey] = kind == "number" and math.floor(value * 100 + 0.5) / 100 or value
            count = count + 1
        end
    end
    return count > 0 and list or nil
end

function Reports.searchOf(arg1)
    local simResult = Brain.simTeam [arg1]
    if type(simResult) ~= "table" or type(simResult.ids) ~= "table" or os.time() - (tonumber(simResult.at) or 0) > 7200 then
        return nil
    end
    local list = {
    }
    for _, member in ipairs(Match.team or {
    }) do
        list [member.id] = true
    end
    local flag = # simResult.ids > 0
    for _, value in ipairs(simResult.ids) do
        if not list [value] then
            flag = false
        end
    end
    return {
        ids = simResult.ids,
        won = simResult.won and true or false,
        wave = simResult.wave,
        cur = simResult.cur,
        better = simResult.better and true or nil,
        played = flag,
        ago = os.time() - (tonumber(simResult.at) or 0)
    }
end

function Reports.modsOf()
    local function helper(arg1)
        local value
        for key, value2 in pairs(type(arg1) == "table" and arg1 or {
        }) do
            value = value or {
            }
            value [key] = type(value2) == "number" and math.floor(value2 * 1000 + 0.5) / 1000 or value2
        end
        return value
    end
    local list = {
    }
    if Match.mod then
        list.weak, list.res, list.strong = helper(Match.mod.weak), helper(Match.mod.res), helper(Match.mod.strong)
    end
    list.seed = Match.ld._is_daily_challenge and tonumber(Match.ld._challenge_uuid) or nil
    local list2 = {
    }
    for _, config in pairs(Match.info and Match.info.configs or {
    }) do
        local unit = type(config) == "table" and Core.Units [config.unit_id]
        if type(unit) == "table" then
            local enemyModifiers = type(unit.enemy_modifiers) == "table" and unit.enemy_modifiers or {
            }
            for enemyModifierKey, enemyModifier in pairs(enemyModifiers) do
                if enemyModifier then
                    list2 [enemyModifierKey] = (list2 [enemyModifierKey] or 0) + 1
                end
            end
            if not enemyModifiers.Flying and Simulator.flies(unit) then
                list2.Flying = (list2.Flying or 0) + 1
            end
        end
    end
    if next(list2) then
        list.enemy = list2
    end
    for _, value in ipairs({
        "Armor",
        "Ice",
        "Ice@snow"
    }) do
        local enemyMod = Brain.enemyMods [value]
        local modRead = Simulator.modRead(enemyMod)
        if modRead then
            list.measured = list.measured or {
            }
            list.measured [value] = {
                f = math.floor(modRead * 1000 + 0.5) / 1000,
                n = # enemyMod.r
            }
        end
    end
    return next(list) and list or nil
end

function Reports.mapOf(arg1)
    local mapKey = Match.mapKey()
    local map = Brain.maps [mapKey] or {
    }
    local value = Brain.simCal[Simulator.calKey(arg1, Match.ld, Match.challenge, Match.rotation)] or {}
    local function helper(arg1)
        arg1 = tonumber(arg1)
        return arg1 and math.floor(arg1 * 10000 + 0.5) / 10000 or nil
    end
    local value2
    if type(map.dens) == "table" then
        value2 = {
        }
        for i = 1, Simulator.BINS do
            value2 [i] = math.floor((tonumber(map.dens [i]) or 0) * 100 + 0.5) / 100
        end
    end
    return {
        key = mapKey,
        walk = helper(Simulator.mapWalk(mapKey)),
        spots = tonumber(map.spots),
        hill = map.hill,
        lanes = type(map.lanes) == "table" and # map.lanes or nil,
        dens = value2,
        cal = {
            waveSec = helper(value.waveSec),
            spawnGap = helper(value.spawnGap),
            yenCal = helper(value.yenCal),
            bountyCal = helper(value.bountyCal),
            baseRel = helper(value.baseRel),
            countCal = helper(value.countCal),
            skipDelay = helper(value.skipDelay)
        }
    }
end

function Reports.match(arg1)
    local playerCount, count = # game:GetService("Players"):GetPlayers() - 1, 0
    for _, child in ipairs(workspace._UNITS:GetChildren()) do
        local stats = child:FindFirstChild("_stats")
        local player = stats and stats:FindFirstChild("player")
        local parentUnit = stats and stats:FindFirstChild("parent_unit")
        if player and player.Value ~= nil and player.Value ~= LocalPlayer and not (parentUnit and parentUnit.Value) then
            count = count + 1
        end
    end
    local list = {
    }
    local function helper(arg1)
        list [arg1] = list [arg1] or {
            dealt = 0,
            copies = 0,
            top = 0
        }
        return list [arg1]
    end
    for _, value in pairs(Match.ownDealt or {
    }) do
        local value2 = helper(value.id)
        value2.dealt = value2.dealt + (value.v or 0)
        value2.copies = value2.copies + 1
        value2.top = math.max(value2.top, value.lvl or 0)
    end
    for _, value in pairs(Match.helperDealt or {
    }) do
        if value.owner then
            local value2 = helper(value.owner)
            value2.helpers = (value2.helpers or 0) + (value.v or 0)
        end
    end
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit:FindFirstChild("_stats")
        local takedownCount = stats and stats:FindFirstChild("takedown_count")
        if stats and stats:FindFirstChild("id") and takedownCount then
            local value = helper(stats.id.Value)
            value.tk = (value.tk or 0) + (tonumber(takedownCount.Value) or 0)
        end
    end
    local list2 = {
    }
    for _, member in ipairs(Match.team or {
    }) do
        local item = list [member.id] or {
        }
        table.insert(list2, {
            id = member.id,
            lvl = Strategy.level(member.u),
            trait = (Units.trait(member.u)),
            relic = Units.relicName(member.u),
            skin = member.u.skin and member.u.skin._skin_id or nil,
            copies = item.copies or 0,
            top = item.top or 0,
            dealt = math.floor(item.dealt or 0),
            helpers = item.helpers and math.floor(item.helpers) or nil,
            tk = item.tk,
            eff = Match.lastEff and Match.lastEff [member.id] or nil
        })
    end
    local list = {
    }
    local calRun, pred = Match.calRun or {
    }, Match.pred or {
    }
    local function helper(arg1, arg2)
        return math.floor(tonumber(arg1 and (arg1 [arg2] or arg1 [tostring(arg2)])) or 0)
    end
    for i = 1, Match.wave() do
        table.insert(list, {
            i,
            helper(calRun.alive,
            i),
            helper(calRun.dpsAt,
            i),
            helper(pred.aliveAt,
            i),
            helper(pred.dpsAt,
            i)
        })
    end
    local list3 = {
    }
    for key, value in pairs(Match.layout or {
    }) do
        if value [1] then
            list3 [key] = {
                math.floor(value [1].X),
                math.floor(value [1].Z)
            }
        end
    end
    local simRe = Brain.simRes [arg1.key] or {
    }
    local info = {
        v = VERSION,
        at = os.time(),
        mode = arg1.key,
        kind = Match.kind,
        level = Match.ld.id,
        map = Match.ld.map,
        diff = Match.ld._difficulty,
        challenge = Match.ld._challenge or (Match.key == "dc" and Brain.live.daily and Brain.live.daily.challenge) or nil,
        portal = Match.kind == "portal" and Brain.portalMods or nil,
        weather = Hunt.is(Match.ld.id) and Hunt.weatherNow() or nil,
        players = playerCount,
        otherUnits = count,
        joinedMid = Match.joinedMid or nil,
        lanes = Match.laneCount and Match.laneCount.n or 1,
        result = {
            won = arg1.won and true or false,
            wave = Match.wave(),
            total = Match.total,
            sec = math.floor(tonumber(arg1.sec) or 0),
            gems = arg1.gems,
            coins = arg1.coins,
            spent = math.floor(Match.spent or 0),
            refused = Match.refusals or 0,
            items = (type(arg1.items) == "table" and next(arg1.items)) and arg1.items or nil
        },
        sim = {
            pred = Match.pred and {
                won = Match.pred.won,
                wave = Match.pred.wave,
                min = math.floor((Match.pred.t or 0) / 6) / 10
            } or nil,
            p = simRe.p,
            margin = simRe.playing or simRe.margin,
            trust = simRe.trust and simRe.trust.ratio or nil,
            style = Match.style,
            why = Match.styleWhy,
            hpCal = Match.info and Match.info.cal and Match.info.cal.hpCal or nil,
            hpRun = Match.hpRun
        },
        team = list2,
        placed = Match.placeLog,
        plan = list3,
        waves = list,
        trainee = Match.trainee and Brain.train.on and Brain.train.on.id or nil,
        trial = Match.trialId,
        hunt = Match.hunt and {
            picks = Match.fhPicks,
            how = Config.huntCards,
            strength = Match.fhP and math.floor(Match.fhP * 100 + 0.5) / 100 or nil,
            mult = Match.fhMult and math.floor(Match.fhMult * 100 + 0.5) / 100 or nil,
            starfall = Match.starSummary,
            floor = select(2,
            pcall(Hunt.floor))
        } or nil,
        settings = select(2,
        pcall(Reports.settingsOf)),
        toggles = (function()
            local value
            for key in pairs(Match.togglesSeen or {
            }) do
                local toggle = Brain.toggles [key]
                if toggle then
                    value = value or {
                    }
                    value [key] = {
                        from = toggle.from,
                        fill = math.floor((toggle.fill or 0) * 100 + 0.5) / 100,
                        drain = math.floor((toggle.drain or 0) * 100 + 0.5) / 100
                    }
                end
            end
            return value
        end)(),
        traineeTk = Match.trainee and Brain.train.on and Match.trainTk or nil,
        trainWhat = Match.trainee and Brain.train.on and Brain.train.on.what or nil,
        search = select(2,
        pcall(Reports.searchOf,
        arg1.key)),
        mods = select(2,
        pcall(Reports.modsOf)),
        mapData = select(2,
        pcall(Reports.mapOf,
        arg1.key))
    }
    for _, value in ipairs({
        "search",
        "mods",
        "mapData"
    }) do
        if type(info [value]) ~= "table" then
            info [value] = nil
        end
    end
    Brain.hiveN = (tonumber(Brain.hiveN) or 0) + 1
    local text = Core.FOLDER .. "/hive"
    pcall(makefolder, text)
    local text2 = string.format("%s/matches_%d.jsonl", text, math.floor((Brain.hiveN - 1) / 500) + 1)
    local text = Utils.json(info) .. "\n"
    if appendfile and isfile and isfile(text2) then
        pcall(appendfile, text2, text)
    else
        local ok, res = pcall(readfile, text2)
        pcall(writefile, text2, (ok and res or "") .. text)
    end
    if Config.shareStats and Core.WEBHOOK_URL ~= "" then
        info.id = Brain.anonId
        table.insert(Brain.aaHiveQ, Reports.fit(info))
        while # Brain.aaHiveQ > 30 do
            table.remove(Brain.aaHiveQ, 1)
        end
        task.spawn(function()
            pcall(Reports.sendHive)
        end)
    end
    App.saveSoon()
end

function Reports.fit(arg1)
    local json = Utils.json(arg1)
    if # json <= 3900 then
        return json
    end
    for _, value in ipairs({
        2,
        5,
        10
    }) do
        local list = {
        }
        for i, wave in ipairs(arg1.waves or {
        }) do
            if i % value == 0 or i == # arg1.waves then
                table.insert(list, wave)
            end
        end
        arg1.waves = list
        json = Utils.json(arg1)
        if # json <= 3900 then
            return json
        end
    end
    for _, value in ipairs(arg1.placed or {
    }) do
        value.why = nil
    end
    json = Utils.json(arg1)
    if # json <= 3900 then
        return json
    end
    if arg1.mapData then
        arg1.mapData.dens = nil
    end
    json = Utils.json(arg1)
    if # json <= 3900 then
        return json
    end
    arg1.placed, arg1.plan = nil, nil
    return Utils.json(arg1):sub(1, 3900)
end

function Reports.postEmbed(arg1, arg2)
    local httpRequest = (syn and syn.request) or (http and http.request) or http_request or request
    if not httpRequest or Core.WEBHOOK_URL == "" then
        return false
    end
    local ok, res = pcall(httpRequest, {
        Url = Core.WEBHOOK_URL,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = Utils.json({
            username = "awaqwaa",
            allowed_mentions = {
                parse = {
                }
            },
            embeds = {
                {
                    title = arg1,
                    description = arg2,
                    color = 15418782
                }
            }
        })
    })
    local statusCode = ok and type(res) == "table" and tonumber(res.StatusCode or res.Status) or nil
    return ok and (not statusCode or statusCode < 300)
end

function Reports.sendHive()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") or # Brain.aaHiveQ == 0 or Reports.sending then
        return
    end
    Reports.sending = true
    local ok, res = pcall(Reports.postEmbed, string.format("🎌 AA · match · %s · v%s", tostring(Brain.anonId), VERSION), "```json\n" .. Brain.aaHiveQ [1] .. "\n```")
    Reports.sending = nil
    if ok and res then
        table.remove(Brain.aaHiveQ, 1)
        Brain.hiveSent = (tonumber(Brain.hiveSent) or 0) + 1
        pcall(App.saveNow)
    end
end

function Reports.sendAll()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") then
        return 0, # Brain.aaHiveQ
    end
    local count = 0
    for i = 1, 10 do
        local aaHiveQCount = # Brain.aaHiveQ
        if aaHiveQCount == 0 then
            break
        end
        Reports.sendHive()
        if # Brain.aaHiveQ >= aaHiveQCount then
            break
        end
        count = count + 1
        task.wait(1.5)
    end
    return count, # Brain.aaHiveQ
end

function Reports.post(arg1)
    if Core.WEBHOOK_URL == "" then return false, "not connected" end
    local httpRequest = (syn and syn.request) or (http and http.request) or http_request or request
    if not httpRequest then
        return false, "no http"
    end
    local ok, res = pcall(httpRequest, {
        Url = Core.WEBHOOK_URL,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = Utils.json({
            content = arg1,
            allowed_mentions = {
                parse = {
                }
            }
        })
    })
    return ok and res and (res.StatusCode == 200 or res.StatusCode == 204), res
end

function Reports.flush()
    if Core.WEBHOOK_URL == "" or not Config.shareStats or # Brain.hiveQueue == 0 then
        return false, "not connected"
    end
    local post = Reports.post("📊 AA " .. Utils.json({
        id = Brain.anonId,
        v = VERSION,
        runs = Brain.hiveQueue
    }))
    if post then
        table.clear(Brain.hiveQueue)
        App.saveSoon()
    end
    return post
end
Reports.HIVE_FILE = Core.FOLDER .. "/hive_shared.json"

function Reports.hive()
    if not Config.useHive then
        return nil
    end
    if Reports.shared == nil then
        local readJson = Utils.readJson(Reports.HIVE_FILE)
        Reports.shared = type(readJson) == "table" and type(readJson.units) == "table" and readJson or false
    end
    return Reports.shared or nil
end

function Reports.hiveUnit(unitKey)
    local hive = Reports.hive()
    local unit = hive and hive.units [unitKey]
    if type(unit) == "table" and (tonumber(unit.eff) or 0) > 0 and ((tonumber(unit.matches) or 0) >= 5 or (tonumber(unit.players) or 0) >= 2) then
        return unit
    end
end

function Reports.hiveTrain(arg1, arg2)
    local hive = Reports.hive()
    local value = hive and type(hive.train) == "table" and hive.train [arg1]
    if type(value) ~= "table" then
        return nil
    end
    local unit = arg2 and type(value.units) == "table" and value.units [arg2]
    if type(unit) == "table" and (tonumber(unit.runs) or 0) >= 3 then
        return tonumber(unit.perRun)
    end
    if (tonumber(value.runs) or 0) >= 3 then
        return tonumber(value.perRun)
    end
end

function Reports.hiveToggle(arg1)
    local hive = Reports.hive()
    local toggle = hive and type(hive.toggles) == "table" and hive.toggles [arg1]
    return type(toggle) == "table" and toggle or nil
end

function Reports.hiveStat(arg1)
    local hive = Reports.hive()
    local stat = hive and type(hive.stats) == "table" and hive.stats [arg1]
    return type(stat) == "table" and stat or nil
end

function Reports.hiveHp(mapKey)
    local hive = Reports.hive()
    local map = hive and type(hive.maps) == "table" and hive.maps [mapKey]
    return type(map) == "table" and (tonumber(map.runs) or 0) >= 3 and tonumber(map.hpCal) or nil
end

function Reports.hiveDrops(dropKey)
    local hive = Reports.hive()
    local drop = dropKey and hive and type(hive.drops) == "table" and hive.drops [dropKey]
    if type(drop) ~= "table" or (tonumber(drop.runs) or 0) < 3 or type(drop.items) ~= "table" then
        return nil
    end
    return drop.items
end

function Reports.sendUnit()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") or Reports.sending then
        return
    end
    local hive = Reports.hive()
    local stats = hive and type(hive.stats) == "table" and hive.stats or {
    }
    for key, value in pairs(Brain.unitData) do
        if not Brain.unitSent [key] and not stats [key] and type(value) == "table" and value.upgrade then
            local list = {
            }
            for key, value in pairs(value) do
                if key ~= "passives" then
                    list [key] = value
                end
            end
            local ok, res = pcall(Utils.json, {
                id = key,
                data = list
            })
            if ok and # res <= 3900 then
                Reports.sending = true
                local ok, res2 = pcall(Reports.postEmbed, string.format("🎌 AA · unit · %s · v%s", tostring(Brain.anonId), VERSION), "```json\n" .. res .. "\n```")
                Reports.sending = nil
                if ok and res2 then
                    Brain.unitSent [key] = os.time()
                    App.saveSoon()
                end
            else
                Brain.unitSent [key] = - 1
                App.saveSoon()
            end
            return
        end
    end
end

function Reports.hiveTrainRate(key)
    local hive = Reports.hive()
    local value = hive and type(hive.train) == "table" and hive.train [key]
    return type(value) == "table" and (tonumber(value.runs) or 0) >= 3 and tonumber(value.perMin) or nil
end

function Reports.hiveFetch()
    if Core.HIVE_URL == "" or not Config.useHive then
        return
    end
    local ok, res = pcall(game.HttpGet, game, Core.HIVE_URL .. "?t=" .. os.time())
    if not ok or type(res) ~= "string" or res:sub(1, 1) ~= "{" then
        return
    end
    local ok, res2 = pcall(HttpService.JSONDecode, HttpService, res)
    if not (ok and type(res2) == "table" and tonumber(res2.v) == 1 and type(res2.units) == "table") then
        return
    end
    local hive = Reports.hive()
    if hive and hive.updated == res2.updated then
        return
    end
    pcall(Utils.writeJson, Reports.HIVE_FILE, res2)
    Reports.shared = res2
    table.clear(Units._rows)
    table.clear(Simulator._holds)
    Adventure._src = nil
    local count, count2 = 0, 0
    for _ in pairs(res2.units) do
        count = count + 1
    end
    for _ in pairs(type(res2.train) == "table" and res2.train or {
    }) do
        count2 = count2 + 1
    end
    App.log(1, "HIVE", string.format("learned from %d players' %d matches: readings for %d units, takedown rates on %d maps", tonumber(res2.players) or 0, tonumber(res2.matchRecords) or 0, count, count2))
    local list = {
    }
    for _, unitId in ipairs(type(res2.under) == "table" and res2.under or {
    }) do
        if Units.owns(unitId) and not (Brain.learn [unitId] and (Brain.learn [unitId].n or 0) >= 3) then
            table.insert(list, string.format("%s (×%.1f)", Units.name(unitId), tonumber(res2.units [unitId] and res2.units [unitId].eff) or 0))
        end
    end
    if # list > 0 then
        App.log(1, "HIVE", "other players' runs say the simulator reads these of yours far too low: " .. table.concat(list, ", ") .. ". A trial run would check them")
        if App.notify then
            App.notify("Local learning", "Units the simulator underrates: " .. table.concat(list, ", "), "info")
        end
    end
end

function Reports.hiveText()
    if not Config.useHive then
        return "Off: the farm learns only from your own runs."
    end
    local hive = Reports.hive()
    if not hive then
        return "Nothing shared yet. Once other players' farms send their matches, the farm reads what they learned here every 6 hours."
    end
    local count, count2, count3, count4, count5, count6 = 0, 0, 0, 0, 0, 0
    for unitKey in pairs(hive.units) do
        if Reports.hiveUnit(unitKey) and not (Brain.learn [unitKey] and (Brain.learn [unitKey].n or 0) >= 3) then
            count = count + 1
        end
    end
    for _ in pairs(type(hive.train) == "table" and hive.train or {
    }) do
        count2 = count2 + 1
    end
    for statKey in pairs(type(hive.stats) == "table" and hive.stats or {
    }) do
        if not Brain.unitData [statKey] then
            count3 = count3 + 1
        end
    end
    for mapKey in pairs(type(hive.maps) == "table" and hive.maps or {
    }) do
        if Reports.hiveHp(mapKey) and not (Brain.simCal [mapKey] and Brain.simCal [mapKey].hpCal) then
            count4 = count4 + 1
        end
    end
    for dropKey in pairs(type(hive.drops) == "table" and hive.drops or {
    }) do
        if Reports.hiveDrops(dropKey) then
            count5 = count5 + 1
        end
    end
    for toggleKey in pairs(type(hive.toggles) == "table" and hive.toggles or {
    }) do
        if not Brain.toggles [toggleKey] then
            count6 = count6 + 1
        end
    end
    local list = {
        string.format("From %d players' %d matches, updated %s.",
        tonumber(hive.players) or 0,
        tonumber(hive.matchRecords) or 0,
        os.date("%b %d %H:%M",
        tonumber(hive.updated) or 0)),
        string.format("What it fills in that your own runs haven't: %d units' readings, %d hidden units' real stats, %d switch abilities, how tough %d maps really are, what %d levels really drop, and takedown rates on %d maps.",
        count,
        count3,
        count6,
        count4,
        count5,
        count2)
    }
    local list2 = {
    }
    for _, unitId in ipairs(type(hive.under) == "table" and hive.under or {
    }) do
        table.insert(list2, Units.name(unitId) .. (Units.owns(unitId) and " (yours)" or ""))
    end
    if # list2 > 0 then
        table.insert(list, "The simulator reads these far too low: " .. table.concat(list2, ", ") .. ".")
    end
    return table.concat(list, "\n")
end

function Reports.suggest(arg1)
    arg1 = tostring(arg1 or ""):sub(1, 500):gsub("https?://%S+", "[link]"):gsub("@", "(at)")
    if arg1:gsub("%s", "") == "" then
        return false, "empty"
    end
    if Core.WEBHOOK_URL == "" then
        return false, "suggestions aren't connected yet"
    end
    if os.time() - (Brain.lastSuggest or 0) < 600 then
        return false, "one suggestion per 10 minutes"
    end
    local postEmbed = Reports.postEmbed(string.format("🎌 AA · suggestion · %s · v%s", tostring(Brain.anonId), VERSION), arg1)
    if postEmbed then
        Brain.lastSuggest = os.time()
    end
    return postEmbed, postEmbed and nil or "send failed"
end

