function Window:_buildWindowControls(content, options)
    local function addButton(name, glyph, offset, callback, close)
        local button = create("TextButton", {
            Name = name, Text = glyph, TextSize = 19, FontFace = Fonts.Medium,
            TextColor3 = Theme.Text, BackgroundColor3 = close and Theme.Error or Theme.Surface3,
            BackgroundTransparency = 1, BorderSizePixel = 0, AutoButtonColor = false,
            AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -offset, 0, 14),
            Size = UDim2.fromOffset(34, 34), ZIndex = 5, Parent = content,
        })
        button:SetAttribute("NoDrag", true)
        corner(button, UDim.new(0, 5))
        button.MouseEnter:Connect(function()
            button.BackgroundTransparency = 0
        end)
        button.MouseLeave:Connect(function()
            button.BackgroundTransparency = 1
        end)
        button.Activated:Connect(callback)
        return button
    end

    self._windowControlsWidth = 68
    self.MinimizeButton = addButton("Minimize", "−", 82, function()
        self:ToggleVisibility(true)
    end)
    self._maximizeButton = addButton("Maximize", "□", 48, function()
        self:_toggleMaximized()
    end)
    addButton("Close", "×", 14, function()
        self:ToggleVisibility(not UserInputService.KeyboardEnabled)
    end, true)
    self._restoreLogo = options.RestoreLogo
end

function Window:_showRestoreTile()
    if not self._restoreGui then
        local gui = create("ScreenGui", {
            Name = "AWRestore", IgnoreGuiInset = true, ResetOnSpawn = false,
            DisplayOrder = self.Gui.DisplayOrder, Enabled = false, Parent = self.Gui.Parent,
        })
        local button = create("TextButton", {
            Name = "Restore", Text = self._restoreLogo and "" or "AW",
            TextSize = 17, FontFace = Fonts.Bold, TextColor3 = Theme.Text,
            BackgroundColor3 = Theme.Surface2, BorderSizePixel = 0,
            AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 16, 1, -92),
            Size = UDim2.fromOffset(48, 48), Parent = gui,
        })
        corner(button, UDim.new(0, 8))
        stroke(button, Theme.Accent)
        if self._restoreLogo then
            local icon = create("ImageLabel", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(32, 32), BackgroundTransparency = 1,
                ScaleType = Enum.ScaleType.Fit, Image = self._restoreLogo, Parent = button,
            })
            icon.Active = false
        end
        table.insert(self._connections, button.Activated:Connect(function()
            self:ToggleVisibility()
        end))
        self._restoreGui = gui
    end
    self._restoreGui.Enabled = true
end

function Window:_fitMaximized()
    local viewport = self.Gui.AbsoluteSize
    if viewport.X <= 24 or viewport.Y <= 24 then return end
    local scale = (self._uiScale or 1) * (self._adaptive ~= false and Library._adaptiveFactor(viewport) or 1)
    self.Root.Position = UDim2.fromScale(0.5, 0.5)
    self:SetSize(Vector2.new((viewport.X - 24) / scale, (viewport.Y - 24) / scale), true)
    self:_fitToScreen(true)
end

function Window:_toggleMaximized()
    if self._destroyed or not self._introDone or self._resizeActive then return end
    if self._clampTween then
        self._clampTween:Cancel()
        self._clampTween = nil
    end
    local previous = self._beforeMaximize
    if previous then
        self._beforeMaximize = nil
        self.Root.Position = previous.position
        self:SetSize(previous.size, true)
        self:_fitToScreen(true)
    else
        self._beforeMaximize = { position = self.Root.Position, size = self:GetSize() }
        self:_fitMaximized()
    end
    self._maximizeButton.Text = self._beforeMaximize and "❐" or "□"
    if self._grip then self._grip.Visible = not self._beforeMaximize end
end

function Window:ToggleVisibility(showTile)
    if self._destroyed or not self._introDone then
        return
    end
    if self.Gui.Enabled then
        self:_closePopups()
        if showTile then self:_showRestoreTile() end
        self.Gui.Enabled = false
        return
    end
    self.Gui.Enabled = true
    if self._restoreGui then self._restoreGui.Enabled = false end
    if self.Minimized or not self.Open then
        self:Toggle(true)
    end
end
