function GUI.snipeOptions()
    local list = {
        {
            text = "Pick a unit",
            value = ""
        }
    }
    local snipe = Brain.snipe or {
    }
    if not GUI.evolvedIds then
        GUI.evolvedIds = {
        }
        for _, unit in pairs(Core.Units) do
            if type(unit) == "table" and type(unit.evolve) == "table" and unit.evolve.evolve_unit then
                GUI.evolvedIds [unit.evolve.evolve_unit] = true
            end
        end
    end
    local list2, list3 = {
    }, {
    }
    local function helper(unitId, arg2, arg3)
        if list3 [unitId] or not Core.Units [unitId] then
            return
        end
        list3 [unitId] = true
        local snipeHas = FarmHub.snipeHas(unitId)
        table.insert(list2, {
            id = unitId,
            text = Units.name(unitId) .. arg2 .. (snipeHas and " · owned" or ""),
            key = arg3 * 10 + (snipeHas and 0 or 5),
            name = Units.name(unitId)
        })
    end
    if Config.snipeUnit ~= "" then
        helper(Config.snipeUnit, "", 9)
    end
    for key, value in pairs(snipe.feat or {
    }) do
        for _, value in ipairs(value) do
            helper(value, " · featured on " .. (FarmHub.BANNER_NAME [key] or key), 3)
        end
    end
    for key, value in pairs(snipe.seen or {
    }) do
        if type(value) == "table" then
            helper(key, string.format(" · seen on %s %s", FarmHub.BANNER_NAME [value.banner] or tostring(value.banner), os.date("%b %d", tonumber(value.at) or os.time())), 2)
        end
    end
    for unitKey, unit in pairs(Core.Units) do
        if type(unitKey) == "string" and type(unit) == "table" and unit.rarity == "Mythic" and not unit.hide_from_banner and not unit.limited and not GUI.evolvedIds [unitKey] and not unitKey:find(":") then
            helper(unitKey, "", 1)
        end
    end
    table.sort(list2, function(arg1, arg2)
        if arg1.key ~= arg2.key then
            return arg1.key > arg2.key
        end
        return arg1.name < arg2.name
    end)
    for _, item in ipairs(list2) do
        table.insert(list, {
            text = item.text,
            value = item.id
        })
    end
    return list
end

function GUI.unitOptions(fuseXpUnit, arg2)
    local list = {
        {
            text = "Pick a unit",
            value = ""
        }
    }
    local session = Core.session()
    if not session then
        return list
    end
    local list2 = {
    }
    for _, item in ipairs(Units.equipped()) do
        list2 [item.uuid] = true
    end
    local list3 = {
    }
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and (list2 [ownedUnitKey] or ownedUnit._locked or unit.rarity == "Secret" or unit.rarity == "Mythic" or ownedUnitKey == fuseXpUnit) then
            local ok, res = pcall(Core.USC.calculate_level, ownedUnit.unit_id, ownedUnit.xp)
            res = ok and tonumber(res) or 0
            table.insert(list3, {
                uuid = ownedUnitKey,
                u = ownedUnit,
                lvl = res,
                team = list2 [ownedUnitKey],
                key = (list2 [ownedUnitKey] and 4000 or 0) + (ownedUnit._locked and 2000 or 0) + (unit.rarity == "Secret" and 1000 or 0) + res
            })
        end
    end
    table.sort(list3, function(item, item2)
        if item.key ~= item2.key then
            return item.key > item2.key
        end
        return item.uuid < item2.uuid
    end)
    for _, item in ipairs(list3) do
        local flag, str = true, ""
        if arg2 then
            flag, str = pcall(arg2, item.u)
        end
        if flag and (str ~= false or item.uuid == fuseXpUnit) and (# list <= 60 or item.uuid == fuseXpUnit) then
            table.insert(list, {
                text = string.format("%s · lvl %d%s%s",
                Units.name(item.u.unit_id),
                item.lvl,
                item.team and " · team" or "",
                type(str) == "string" and str or ""),
                value = item.uuid
            })
        end
    end
    return list
end

