function FarmHub.setFocus(arg1)
    Config.evolveUnit = arg1 or ""
    Config.autoEvolve = Config.evolveUnit ~= ""
    Config.focusNext = ""
    FarmHub.pickNote.autoEvolve = nil
    FarmHub.last.goals, FarmHub.last.trainScan, Training._at, Modes.lastScored = nil, nil, nil, nil
    local ok, res = pcall(Adventure.refresh)
    if not ok then
        App.log(1, "ERROR", "focus goals: " .. tostring(res))
    end
    local ok, res = pcall(Strategy.core, true)
    if not ok then
        App.log(1, "ERROR", "focus core: " .. tostring(res))
    end
    App.saveSoon()
end

function FarmHub.focusText()
    if GUI.focusNow() ~= "" then
        return "Your focus. " .. FarmHub.evolveText() .. (Config.focusNext ~= "" and ("\nNext up: " .. Units.name(Config.focusNext) .. ", once this one has evolved.") or "")
    end
    local on = Brain.train.on
    local on2 = on or Training.target()
    if on2 then
        return string.format("Smart Play is working on %s → %s (%s %s/%s)", Units.name(on2.id), Units.name(on2.to), tostring(on2.what), Utils.fmt((tonumber(on2.have) or 0) + (tonumber(on2.got) or 0)), Utils.fmt(tonumber(on2.need) or 0))
    end
    local goal = (Brain.goals or {
    }) [1]
    if goal then
        return "Smart Play is working on " .. Units.name(goal.from) .. " → " .. Units.name(goal.to)
    end
    return "Smart Play: goals are worked out in the lobby"
end

function GUI.evolveOptions(focusNow)
    local list = {
        {
            text = "Pick a unit",
            value = ""
        }
    }
    local session = Core.session()
    if not session then
        return list
    end
    local list2 = {
    }
    for _, item in ipairs(Units.equipped()) do
        list2 [item.uuid] = true
    end
    local list3 = {
    }
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and unit.evolve and unit.evolve.evolve_unit and not unit.evolve.hide_from_ui and Core.Units [unit.evolve.evolve_unit] then
            local num = (ownedUnitKey == focusNow and 1e9 or 0) + (list2 [ownedUnitKey] and 1e6 or 0) + (tonumber(ownedUnit.xp) or 0)
            if not list3 [ownedUnit.unit_id] or num > list3 [ownedUnit.unit_id].key then
                list3 [ownedUnit.unit_id] = {
                    uuid = ownedUnitKey,
                    id = ownedUnit.unit_id,
                    to = unit.evolve.evolve_unit,
                    key = num
                }
            end
        end
    end
    local list4 = {
    }
    for _, item in pairs(list3) do
        table.insert(list4, item)
    end
    table.sort(list4, function(item, item2)
        if item.key ~= item2.key then
            return item.key > item2.key
        end
        return item.uuid < item2.uuid
    end)
    for _, item in ipairs(list4) do
        local unitObj = session.collection:get_unit_by_uuid(item.uuid)
        local ok, res = pcall(Core.USC.calculate_level, item.id, unitObj and unitObj.xp or 0)
        table.insert(list, {
            text = string.format("%s → %s · lvl %d%s",
            Units.name(item.id),
            Units.name(item.to),
            ok and tonumber(res) or 0,
            list2 [item.uuid] and " · team" or ""),
            value = item.uuid
        })
    end
    return list
end

function GUI.modeOptions(arg1)
    local list = {
    }
    local value = ({
        raid = "pickRaid",
        story = "pickStory",
        legend = "pickLegend",
        infinite = "pickInfinite",
        portal = "pickPortal"
    }) [arg1]
    local function helper(arg1, arg2)
        for _, item in ipairs(Utils.list(arg1)) do
            local world = Core.Worlds [item]
            for _, item in ipairs(Utils.list(world and world.levels)) do
                if Modes.open(item.id) then
                    arg2(item.id, world)
                end
            end
        end
    end
    if arg1 == "story" then
        list = {
            {
                text = "🤖 Smart: first clears, then farm runs",
                value = ""
            },
            {
                text = "📈 Progress: the next map you haven't beaten",
                value = "progress"
            }
        }
        helper(Core.WLO.WORLD_ORDER, function(arg1, arg2)
            if not arg2.legend_stage and not arg2.raid_world then
                for _, value in ipairs({
                    "Normal",
                    "Hard"
                }) do
                    if Modes.diffOpen(arg1, value) then
                        table.insert(list, {
                            text = Modes.levelName(arg1) .. " (" .. value .. ")",
                            value = "st:" .. arg1 .. ":" .. value
                        })
                    end
                end
            end
        end)
    elseif arg1 == "legend" then
        list = {
            {
                text = "🤖 Smart: when it drops what a goal needs",
                value = ""
            },
            {
                text = "📈 Progress: the next legend stage you haven't beaten",
                value = "progress"
            }
        }
        helper(Core.WLO.LEGEND_WORLD_ORDER, function(arg1)
            table.insert(list, {
                text = Modes.levelName(arg1),
                value = "st:" .. arg1 .. ":Hard"
            })
        end)
    elseif arg1 == "raid" then
        list = {
            {
                text = "🤖 Smart: the raid worth the most",
                value = ""
            }
        }
        helper(Core.WLO.RAID_WORLD_ORDER, function(arg1)
            table.insert(list, {
                text = Modes.levelName(arg1),
                value = "rd:" .. arg1
            })
        end)
    elseif arg1 == "infinite" then
        list = {
            {
                text = "🤖 Smart: daily gems and takedowns",
                value = ""
            }
        }
        for _, infId in ipairs(Modes.infIds()) do
            if Modes.open(infId) then
                table.insert(list, {
                    text = Modes.levelName(infId),
                    value = "inf:" .. infId
                })
            end
        end
    elseif arg1 == "portal" then
        list = {
            {
                text = "🤖 Smart: portals whose map drops what your evolutions need",
                value = "smart"
            }
        }
        local list2 = {
        }
        for _, portalKind in ipairs(Modes.portalKinds()) do
            local portalsHeldCount = # Modes.portalsHeld(portalKind.pid)
            local info = {
                text = string.format("%s (%s)%s",
                portalKind.name,
                tostring(portalKind.rarity or "?"),
                portalsHeldCount > 0 and (" · you hold " .. portalsHeldCount) or ""),
                value = portalKind.pid
            }
            table.insert(portalsHeldCount > 0 and list or list2, info)
        end
        for _, item in ipairs(list2) do
            table.insert(list, item)
        end
    end
    local str = value and Config [value] or ""
    local flag = false
    for _, item in ipairs(list) do
        if item.value == str then
            flag = true
        end
    end
    if not flag then
        table.insert(list, {
            text = "your pick (not open right now)",
            value = str
        })
    end
    return list
end
