function GUI.lbTargetOptions()
    local list = {
        {
            text = "Pick a unit",
            value = ""
        }
    }
    local session = Core.session()
    if not session then
        return list
    end
    local list2 = {
    }
    for _, item in ipairs(Units.equipped()) do
        list2 [item.uuid] = true
    end
    local list3 = {
    }
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unitObj = session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit
        local unit = Core.Units [unitObj.unit_id]
        if unit and (unit.rarity == "Mythic" or unit.rarity == "Secret" or list2 [ownedUnitKey] or ownedUnitKey == Config.fuseUnit) then
            local ok, res = pcall(Core.USC.get_max_limit_break, unitObj)
            local currentLimitBreak = unitObj.further_modifiers and unitObj.further_modifiers.limit_break and tonumber(unitObj.further_modifiers.limit_break.current_limit_break) or 0
            if (ok and (tonumber(res) or 0) > currentLimitBreak) or ownedUnitKey == Config.fuseUnit then
                local ok, res = pcall(Units.score, unitObj)
                local level, cap = Strategy.level(unitObj), Strategy.cap(unitObj)
                table.insert(list3, {
                    uuid = ownedUnitKey,
                    id = unitObj.unit_id,
                    lvl = level,
                    cap = cap,
                    team = list2 [ownedUnitKey],
                    sc = ok and res or 0,
                    key = (ownedUnitKey == Config.fuseUnit and 4 or 0) + (list2 [ownedUnitKey] and 2 or 0) + (level >= cap and 1 or 0)
                })
            end
        end
    end
    table.sort(list3, function(item, item2)
        if item.key ~= item2.key then
            return item.key > item2.key
        end
        if item.sc ~= item2.sc then
            return item.sc > item2.sc
        end
        return item.uuid < item2.uuid
    end)
    for i, item in ipairs(list3) do
        if i > 60 then
            break
        end
        table.insert(list, {
            text = string.format("%s · Lv %d/%d%s%s",
            Units.name(item.id),
            item.lvl,
            item.cap,
            item.team and " · team" or "",
            item.lvl >= item.cap and " · at cap" or ""),
            value = item.uuid
        })
    end
    return list
end

function GUI.fodderTable(page)
    local group = GUI.block("Units", "Fusion", "Fodder units", "Left")
    local handle = { data = {} }
    local board, selectionFlag
    local summary = group:CreateStatus({ Name = "Fodder", Value = "Farm picks", Style = "Plain" })
    GUI.paragraph(group, "Click a row to select a unit. ★ marks the farm's safe picks; ⚠ marks something worth keeping. Empty selection uses the farm's safe rule. Locked and equipped units never show.")
    local function selected()
        local result = {}
        for _, uuid in ipairs(Config.fuseFodder or {}) do result[uuid] = true end
        return result
    end
    function handle.points()
        local picked, total = selected(), 0
        for _, unit in ipairs(handle.data) do
            if picked[unit.uuid] then total = total + unit.pts end
        end
        return total
    end
    function handle.summary()
        local requirement = Brain.fuseInfo and Brain.fuseInfo.uuid == Config.fuseUnit and tonumber(Brain.fuseInfo.requirement)
        local count, points = #(Config.fuseFodder or {}), handle.points()
        summary:Set(count == 0 and "Farm picks" or string.format("%d selected · %d%s points", count, points, requirement and (" / " .. requirement) or ""))
        summary:SetColor(requirement and points >= requirement and "Success" or "Accent")
    end
    local function render()
        local picked, rows = selected(), {}
        for _, unit in ipairs(handle.data) do
            local details = { unit.rarity, "Lv " .. tostring(unit.lvl) }
            if unit.evolved then table.insert(details, "evolved") end
            if #(unit.flags or {}) > 0 then table.insert(details, "⚠ " .. table.concat(unit.flags, ", ")) end
            table.insert(rows, {
                picked[unit.uuid] and "✓" or "", GUI.escape(unit.name .. (unit.safe and " ★" or "")),
                GUI.escape(table.concat(details, " · ")), unit.pts,
                UUID = unit.uuid, Highlight = picked[unit.uuid] == true,
            })
        end
        board:SetRows(rows)
        handle.summary()
    end
    local function persist()
        Config.fuseArmSig = ""
        App.saveSoon()
        if selectionFlag then selectionFlag:Set(Utils.json(Config.fuseFodder or {}), true) end
        render()
    end
    board = group:CreateTable({
        Name = "Available fodder", MaxRows = 6, Search = true,
        Columns = {
            { Name = "Pick", Width = 40 }, { Name = "Unit", Width = 0.32 },
            { Name = "Details" }, { Name = "Points", Width = 55, Align = "Right" },
        },
        Rows = {},
        Callback = function(row)
            local picked, result = selected(), {}
            for _, uuid in ipairs(Config.fuseFodder or {}) do
                if uuid ~= row.UUID then table.insert(result, uuid) end
            end
            if not picked[row.UUID] then table.insert(result, row.UUID) end
            Config.fuseFodder = result
            persist()
        end,
    })
    local ready, generation = false, 0
    selectionFlag = group:CreateInput({
        Name = "Fodder selection", Visible = false, Flag = "AA/Fuse/FodderUUIDs",
        CurrentValue = Utils.json(Config.fuseFodder or {}),
        Callback = function(text)
            if not ready then return end
            local values = Utils.unjson(text)
            if type(values) ~= "table" then return end
            local ids = {}
            for _, uuid in ipairs(values) do if type(uuid) == "string" then table.insert(ids, uuid) end end
            generation = generation + 1
            local revision = generation
            -- Profile flags load in arbitrary order. Restore the fodder after the
            -- target-unit callback, which intentionally clears a previous pick.
            task.defer(function()
                if not App.alive or revision ~= generation then return end
                Config.fuseFodder = ids
                persist()
            end)
        end,
    })
    ready = true
    function handle.Refresh(data, emptyText)
        handle.data = data or {}
        summary:SetName(#handle.data == 0 and GUI.escape(emptyText or "No eligible units") or "Fodder")
        selectionFlag:Set(Utils.json(Config.fuseFodder or {}), true)
        render()
    end
    group:CreateButtonRow({
        { Name = "Use farm picks", Callback = function()
            task.spawn(function()
                local session = Core.session()
                local unit = session and session.collection:get_unit_by_uuid(Config.fuseUnit)
                if not unit then return end
                local need = Brain.fuseInfo and Brain.fuseInfo.uuid == unit.uuid and tonumber(Brain.fuseInfo.requirement) or 12
                local fuel, ids = FarmHub.fuseFuel(unit, need), {}
                for _, entry in ipairs(fuel) do table.insert(ids, entry.uuid) end
                Config.fuseFodder = ids
                persist()
            end)
        end },
        { Name = "Clear", Callback = function() Config.fuseFodder = {}; persist() end },
        { Name = "Refresh", Callback = function() GUI.fodderSig = nil end },
    })
    return handle
end

function GUI.lbStatus()
    local joined = table.concat({
        tostring(Config.fuseUnit),
        table.concat(Config.fuseFodder or {
        },
        ","),
        tostring(Config.autoFuse),
        tostring(FarmHub.pickNote.autoFuse),
        tostring(Brain.fuseInfo and Brain.fuseInfo.uuid),
        tostring(App.where)
    }, "|")
    local lb = GUI._lb
    if lb and lb.key == joined and Utils.now() - lb.at < 15 then
        return lb.v
    end
    local lbStatusNow = GUI.lbStatusNow()
    GUI._lb = {
        key = joined,
        at = Utils.now(),
        v = lbStatusNow
    }
    return lbStatusNow
end

function GUI.lbStatusNow()
    local col = GUI.COL or {
    }
    if Config.fuseUnit == "" then
        return {
            icon = "🔥",
            title = "Pick a unit to limit break",
            text = "A limit break raises a unit's level cap (100 → 110). It takes a Divine Wish and fodder units, which are destroyed.",
            sub = "",
            tag = "",
            progress = false,
            color = col.accent
        }
    end
    local session = Core.session()
    local unitObj = session and session.collection:get_unit_by_uuid(Config.fuseUnit)
    if not unitObj then
        return {
            icon = "🔥",
            title = "That unit is gone",
            text = "Pick another one.",
            sub = "",
            tag = "",
            progress = false,
            color = col.red
        }
    end
    if App.where == "lobby" and not (Brain.fuseInfo and Brain.fuseInfo.uuid == unitObj.uuid) and FarmHub.every("lbInfo", 10) then
        task.spawn(function()
            local ok, res = App.request("fuseInfo", "request_fusion_information", unitObj.uuid)
            if ok and type(res) == "table" then
                Brain.fuseInfo = {
                    requirement = res.requirement,
                    divine_wish = res.divine_wish,
                    allowed = res.allowed,
                    uuid = unitObj.uuid
                }
                GUI._lb = nil
            end
        end)
    end
    local value = Brain.fuseInfo and Brain.fuseInfo.uuid == unitObj.uuid
    local requirement = value and tonumber(Brain.fuseInfo.requirement) or 12
    local divineWish = value and tonumber(Brain.fuseInfo.divine_wish) or 1
    local level, cap = Strategy.level(unitObj), Strategy.cap(unitObj)
    local value2
    if # (Config.fuseFodder or {
    }) > 0 then
        _, value2 = FarmHub.fodderPicked(unitObj)
    else
        _, value2 = FarmHub.fuseFuel(unitObj, requirement)
    end
    local have = Adventure.have("divine_wish")
    local flag = level >= cap and have >= divineWish and value2 >= requirement and not (value and Brain.fuseInfo.allowed == false)
    local fn = function(arg1)
        return arg1 and "✓" or "✗"
    end
    return {
        icon = "🔥",
        title = Units.name(unitObj.unit_id) .. (value and Brain.fuseInfo.allowed == false and " · can't be limit broken" or ""),
        text = string.format("Level %d/%d %s   ·   Divine Wish %d/%d %s   ·   Fodder %d/%d points %s%s",
        level,
        cap,
        fn(level >= cap),
        have,
        divineWish,
        fn(have >= divineWish),
        value2,
        requirement,
        fn(value2 >= requirement),
        value and "" or " (requirement checked in the lobby)"),
        sub = FarmHub.pickNote.autoFuse or (Config.autoFuse and "Auto Limit Break is on: it fuses once everything is ✓, after showing what it uses for 30 s." or "Limit break is off. Review the fodder, then enable it in the target panel."),
        tag = flag and "READY" or "WAITING",
        tagColor = flag and col.green or col.orange,
        progress = math.min(1,
        value2 / math.max(1,
        requirement)),
        color = flag and col.green or col.accent
    }
end

function GUI.homeRows()
    local function helper(arg1)
        local match = tostring(arg1 or ""):match("^[^\n]+") or ""
        if # match > 130 then
            match = match:sub(1, 127):gsub("%s+%S*$", "") .. "…"
        end
        return match
    end
    local function helper2(arg1)
        local ok, res = pcall(arg1)
        return ok and helper(res) or "…"
    end
    local list = {
    }
    list.Playing = Modes.onlyOn() and ("Only " .. Modes.onlyText()) or "Smart: whatever pays best (Farm → Stages)"
    list.Focus = helper2(FarmHub.focusText)
    list.Training = Config.trainTakedowns and helper2(Training.text) or "off"
    list.Snipe = Config.snipeOn and Config.snipeUnit ~= "" and helper2(FarmHub.snipeText) or "off"
    if Config.fuseUnit ~= "" then
        local ok, res = pcall(GUI.lbStatus)
        list ["Limit Break"] = ok and helper(res.title .. " · " .. tostring(res.tag):lower() .. " · " .. (tostring(res.text):gsub("%s+·%s+", " · "))) or "…"
    else
        list ["Limit Break"] = "Choose a target in Units → Fusion"
    end
    list.Team = Config.team and helper2(Strategy.text) or "off"
    return list
end
GUI.HOME_KEYS = {
    "Playing",
    "Focus",
    "Training",
    "Snipe",
    "Limit Break",
    "Team"
}

function GUI.build()
    local load = GUI.load()
    if not load then
        warn("[AA] awaqwaa airflow failed to load — running without a window")
        return
    end
    GUI.theme(load)
    local window = GUI.window(load)
    GUI.Win = window
    local ui, live = GUI.UI, GUI.LIVE
    local function helper(arg1, arg2)
        Config [arg1] = arg2
        App.saveSoon()
    end
    local function helper2(arg1, arg2, arg3, arg4)
        ui [arg4] = arg1:Toggle(arg2, arg3, Config [arg4], function(arg1)
            helper(arg4, arg1)
        end)
    end
    local function helper3(arg1, arg2, arg3, arg4, arg5)
        arg5.default = Config [arg4]
        ui [arg4] = arg1:Slider(arg2, arg3, arg5, function(arg1)
            helper(arg4, arg1)
        end)
    end
    local function helper4(arg1)
        return tostring(math.floor(arg1 + 0.5))
    end
    local function helper5(arg1)
        return Utils.fmt(arg1)
    end
    local fn = function(arg1)
        return string.format("%d%%", math.floor(arg1 * 100 + 0.5))
    end
    local function helper6(arg1, arg2, arg3)
        pcall(function()
            window:Notify(arg1, arg2, 4, arg3 or "default")
        end)
    end
    local function helper7(arg1, arg2)
        local ok = pcall(GUI.banner, arg1, arg2)
        if not ok then
            arg1:Label(arg2)
        end
    end
    local tab = window:Tab("🏠", "Home")
    helper7(tab, "Turn it on and watch it work. Every other tab is for when you want to choose something yourself.")
    local startGroup = GUI.block("Home", "", "Start here", "Left")
    startGroup:CreateLabel({ Text = "<b>How to start:</b> turn the main switch on. When the four lines below are green, it runs by itself." })
    ui.master = tab:Toggle("Auto Farm", "Picks the modes, plays them and runs your picks. Off: it plays nothing, but the summons, fuses and stars you switched on still run in the lobby", Config.master, function(arg1)
        helper("master", arg1)
        window:Status(arg1 and "▶ Farming" or "⏸ Paused")
    end)
    GUI.start = GUI.startCard(startGroup, {
        everything = function()
            -- The switches a run needs. Auto-equip is left alone: it changes your team, so it stays your choice.
