GUI.ICONS = {
    daily = "📅",
    challenge = "🏆",
    story = "⚔️",
    raid = "👹",
    event = "🃏",
    infinite = "♾️",
    dungeon = "🏰"
}

function GUI.keyName(key)
    if key == "dc" then
        return "📅 Daily Challenge"
    end
    if key == "ch" then
        return "🏆 Challenge"
    end
    if key == "dg" then
        return "🏰 Dungeon"
    end
    local match, match2, match3 = tostring(key):match("^(%a+):([^:]+):?(%a*)$")
    if not match2 then
        return tostring(key)
    end
    return (({
        st = "⚔️ ",
        rd = "👹 ",
        ev = "🃏 ",
        inf = "♾️ "
    }) [match] or "") .. Modes.levelName(match2) .. ((match3 and match3 ~= "") and (" " .. match3) or "")
end

function GUI.plainMode(mode)
    return string.format("%s · %.0f%% win · ≈%.0f gems/min", mode.label, (mode.p or 0) * 100, mode.score or 0)
end

function GUI.upNext(mode, arg2)
    if not mode then
        return "deciding…", ""
    end
    if App.where == "match" and mode.kind == "story" and mode.first and mode.key == Match.key then
        local str = "once this act is won. If it's lost, this act again"
        local ok, res = pcall(Core.PSC.get_next_story_level, mode.level)
        if Config.onlyStory and ok and res then
            return Modes.levelName(res) .. " (" .. tostring(mode.diff) .. ")", "The next act, " .. str
        end
        if arg2 then
            return GUI.plainMode(arg2), "The next best mode, " .. str
        end
    end
    return GUI.plainMode(mode), mode.why or ""
end
GUI.STYLE_NAMES = {
    fast = "fast clear, at the road's start",
    balanced = "spread out along the road",
    box = "kill box, on the road's last stretch"
}

function GUI.simView(arg1)
    if App.where == "match" and Match.ld then
        local pred = Match.pred
        local str
        if not pred then
            str = (Match.planning or (Match.laneWant and not Match.laneCut)) and "Simulator: choosing spots…" or "Simulator: no prediction for this run"
        elseif Match.infinite then
            str = string.format("Simulator: the base falls at wave %d (%.0f min)", pred.wave or 0, (pred.t or 0) / 60)
        else
            str = string.format("Simulator: %s at wave %d (%.0f min)", pred.won and "a win" or "a loss", pred.wave or 0, (pred.t or 0) / 60)
        end
        local list = {
        }
        if Match.style then
            table.insert(list, "Placement: " .. (GUI.STYLE_NAMES [Match.style] or Match.style) .. (Match.styleWhy and (" (" .. tostring(Match.styleWhy) .. ")") or ""))
        end
        if Match.laneWant then
            table.insert(list, Match.laneCut and string.format("lane %s, the one this portal opened (%d of %d)", Match.laneCut, Match.laneWant, Match.laneTotal or 0) or string.format("waiting for the first enemies to show which lane this portal opened (%d of %d)", Match.laneWant, Match.laneTotal or 0))
        end
        if Match.trainee and Brain.train.on then
            table.insert(list, "training " .. Units.name(Brain.train.on.id))
        end
        local str2, green, str3 = "", nil, "no wave measured yet"
        local alive = Match.calRun and Match.calRun.alive or {
        }
        for i = Match.wave(), 1, - 1 do
            local value, value2 = tonumber(alive [tostring(i)]), pred and pred.aliveAt and tonumber(pred.aliveAt [i])
            if value and value2 then
                local num = 1000
                if value < num and value2 < num then
                    str2, green, str3 = "ON TRACK", arg1.green, string.format("wave %d started with every enemy before it cleared, as the simulator expected", i)
                elseif value2 < num then
                    str2, green, str3 = "BEHIND", arg1.red, string.format("wave %d started with %s HP still alive where the simulator expected none", i, Utils.fmt(value))
                elseif value < num then
                    str2, green, str3 = "AHEAD", arg1.green, string.format("wave %d started with nothing left where the simulator expected %s HP", i, Utils.fmt(value2))
                else
                    local ratio = value / value2
                    str2 = ratio <= 0.8 and "AHEAD" or (ratio <= 1.25 and "ON TRACK" or (ratio <= 2 and "BEHIND" or "FAR BEHIND"))
                    green = ratio <= 1.25 and arg1.green or (ratio <= 2 and arg1.orange or arg1.red)
                    str3 = string.format("wave %d started with %s HP alive, the simulator expected %s (%s)", i, Utils.fmt(value), Utils.fmt(value2), ratio <= 0.8 and string.format("%.1f× easier", 1 / ratio) or (ratio <= 1.25 and "close" or string.format("%.1f× harder", ratio)))
                end
                break
            end
        end
        if FarmHub.every("simCardShares", 5) then
            local ok, res = pcall(Match.damageShares)
            local list = {
            }
            for key, value in pairs(ok and type(res) == "table" and res or {
            }) do
                if value >= 0.01 then
                    table.insert(list, {
                        n = Units.name(key):gsub(" %(.+%)",
                        ""),
                        v = value
                    })
                end
            end
            table.sort(list, function(arg1, arg2)
                return arg1.v > arg2.v
            end)
            local list2 = {
            }
            for i = 1, math.min(4, # list) do
                table.insert(list2, string.format("%s %d%%", list [i].n, math.floor(list [i].v * 100 + 0.5)))
            end
            GUI.simShares = # list2 > 0 and ("damage: " .. table.concat(list2, ", ")) or nil
        end
        return {
            icon = "🔮",
            title = str,
            text = # list > 0 and table.concat(list,
            " · ") or "",
            sub = str3 .. (GUI.simShares and (" · " .. GUI.simShares) or ""),
            tag = str2,
            tagColor = green
        }
    end
    local value = Modes.lastScored and Modes.lastScored [1]
    local simRe = value and Brain.simRes [value.key]
    local value2 = value and Brain.simTeam and Brain.simTeam [value.key]
    if not value then
        return {
            icon = "🔮",
            title = "Simulator",
            text = "waiting for the next pick",
            sub = "",
            tag = ""
        }
    end
    return {
        icon = "🔮",
        title = "Simulator: " .. tostring(value.label),
        text = simRe and (tostring(simRe.margin) .. (simRe.playing and (" · " .. tostring(simRe.playing)) or "")) or "no reading yet for this mode",
        sub = value2 and type(value2.names) == "table" and ("team: " .. table.concat(value2.names,
        ", ") .. (value2.why and (" · " .. tostring(value2.why)) or "")) or "",
        tag = simRe and (simRe.hopeless and "HOPELESS" or string.format("%d%%",
        math.floor((tonumber(value.p) or 0) * 100 + 0.5))) or "",
        tagColor = simRe and (simRe.hopeless and arg1.red or ((tonumber(value.p) or 0) >= 0.7 and arg1.green or arg1.orange)) or nil
    }
end

function GUI.update()
    local col = GUI.COL or {
    }
    local prof = Core.prof() or {
    }
    if GUI.nowCard then
        local value
        if not Config.master then
            value = {
                icon = "⏸",
                title = "Paused",
                text = "Turn Auto Farm on to resume",
                sub = "",
                tag = "",
                progress = false,
                color = col.sub
            }
        elseif App.where == "match" and Match.ld then
            local text = Modes.levelName(Match.ld.id or "?") .. (Match.ld._difficulty and (" (" .. Match.ld._difficulty .. ")") or "")
            local pressure = Match.pressure or 0
            local str = (Brain.pending and Brain.pending.key == Match.key and Brain.pending.label) and "launched by the farm" or "playing this match"
            local depth = Match.depth or {
            }
            local clamp = (depth.units or 0) > 0 and Utils.clamp(depth.covEnd or 0.6, 0.1, 1) or 0.6
            local leak = depth.leak or pressure >= math.min(Config.dangerReach, clamp * 0.9)
            local flag = pressure >= math.min(Config.safeReach, clamp * 0.75)
            value = {
                icon = GUI.ICONS [Match.kind or ""] or "⚔️",
                title = text,
                text = tostring(Status.Economy or str),
                sub = string.format("Wave %d/%d · ¥%s · %d enemies · front at %d%% of the road, your units reach %d%% · kills all in %s",
                Match.wave(),
                Match.total or 0,
                Utils.fmt(Match.money()),
                # (Match.enemies or {
                }),
                math.floor(pressure * 100),
                math.floor(((depth.units or 0) > 0 and depth.covEnd or 0) * 100),
                (Match.clearSec or 0) >= 999 and "never" or (math.floor(Match.clearSec or 0) .. "s")),
                tag = depth.leak and "LEAK" or (leak and "DANGER" or (flag and "PRESSURE" or "SAFE")),
                tagColor = leak and col.red or (flag and col.orange or col.green),
                progress = (Match.total or 0) > 0 and Match.wave() / Match.total or false,
                color = col.accent
            }
        else
            value = {
                icon = "🏰",
                title = "In the lobby",
                text = tostring(Status.Mode or "planning the next run"),
                sub = tostring(Status.Rewards or ""),
                tag = "",
                progress = false,
                color = col.accent
            }
        end
        pcall(GUI.nowCard.Set, value)
        pcall(function()
            GUI.Win:Status((value.icon or "") .. " " .. tostring(value.title), value.tagColor or value.color)
        end)
    end
    if GUI.simCard then
        local ok, res = pcall(GUI.simView, col)
        if ok and res then
            pcall(GUI.simCard.Set, res)
        end
    end
    if GUI.nextCard then
        local value = Modes.lastScored and Modes.lastScored [1]
        if not value and Utils.now() - (GUI.pickAt or 0) > 15 then
            GUI.pickAt = Utils.now()
            pcall(Modes.pick)
            value = Modes.lastScored and Modes.lastScored [1]
        end
        local lastResult = Brain.lastResult
        local list = {
        }
        if lastResult then
            if (lastResult.gems or 0) > 0 then
                table.insert(list, lastResult.gems .. " gems")
            end
            if (lastResult.coins or 0) > 0 then
                table.insert(list, lastResult.coins .. " " .. Modes.coinName())
            end
            for itemKey, item in pairs(lastResult.items or {
            }) do
                table.insert(list, string.format("%s×%s", (Core.Items [itemKey] and Core.Items [itemKey].name) or itemKey, tostring(item)))
            end
        end
        local upNext, upNext2 = GUI.upNext(value, Modes.lastScored and Modes.lastScored [2])
        pcall(GUI.nextCard.Set, {
            icon = "⏭",
            title = "Up next: " .. upNext,
            text = upNext2,
            sub = lastResult and ("Last run: " .. lastResult.text .. (# list > 0 and (" · " .. table.concat(list,
            ", ")) or "")) or "",
            tag = lastResult and (lastResult.won and "WON" or "LOST") or "",
            tagColor = lastResult and (lastResult.won and col.green or col.red) or nil
        })
    end
    if GUI.goals then
        local goals = GUI.goals
        pcall(goals.Set, "Gems", Utils.fmt(prof.gem_amount), string.format("gold %s", Utils.fmt(prof.gold_amount)), nil, nil)
        local daily = Brain.live.daily
        local value = daily and daily.uuid and (daily.uuid == prof.last_completed_daily_challenge_uuid or daily.uuid == daily.doneUuid)
        pcall(goals.Set, "Daily Challenge", value and "done ✓" or (daily and "ready" or "…"), daily and string.format("worth ≈%s gems", Utils.fmt(daily.value or 0)) or "", value and col.green or col.gold, nil)
        local normal = Brain.live.normal
        local value = normal and normal.uuid and (normal.uuid == prof.last_completed_challenge_uuid or normal.uuid == normal.doneUuid)
        local value2 = normal and normal.expires and math.max(0, math.floor((normal.expires - os.time()) / 60)) or 0
        pcall(goals.Set, "Challenge", value and "done ✓" or (normal and "open" or "…"), normal and string.format("new one in %d min", value2) or "", value and col.green or col.gold, nil)
        local count = 0
        for _, value in ipairs(Modes.lastScored or {
        }) do
            if value.first then
                count = count + 1
            end
        end
        pcall(goals.Set, "First Clears Left", tostring(count), "acts you can clear for 60 gems now", count > 0 and col.purple or col.green, nil)
        pcall(goals.Set, "Summer Pearls", Utils.fmt(prof.resources and prof.resources.SummerPearls or 0), "a Sunny Star costs 150", nil, nil)
        pcall(goals.Set, "Record", string.format("%d W · %d L", Brain.totals.wins or 0, Brain.totals.losses or 0), string.format("+%s gems by the farm", Utils.fmt(Brain.totals.gems or 0)), nil, nil)
    end
    if GUI.systems then
        for _, system in ipairs(GUI.SYSTEMS) do
            local Statu = Status [system]
            local Statu2 = tostring(Statu or "—")
            pcall(GUI.systems.Set, system, Statu2, (Statu2:find("refused") or Statu2:find("error")) and col.red or (Statu and col.text or col.sub))
        end
    end
    if GUI.rank then
        local lastScored = Modes.lastScored or {
        }
        for i = 1, 6 do
            local value = lastScored [i]
            if value then
                pcall(GUI.rank.Set, "#" .. i, GUI.plainMode(value) .. "\n" .. (value.why or ""), i == 1 and col.green or col.text)
            else
                pcall(GUI.rank.Set, "#" .. i, i == 1 and "no ranking yet" or "", col.sub, i == 1 and "#1" or "")
            end
        end
    end
    if GUI.records then
        local list = {
        }
        for modeKey, mode in pairs(Brain.modes) do
            if mode.runs > 0 then
                table.insert(list, {
                    key = modeKey,
                    r = mode
                })
            end
        end
        table.sort(list, function(arg1, arg2)
            return (arg1.r.last or 0) > (arg2.r.last or 0)
        end)
        for i = 1, 8 do
            local item = list [i]
            if item then
                local str = item.key == "dc" and "📅 Daily Challenge" or item.key == "ch" and "🏆 Challenge" or Modes.levelName((item.key:match("^%a+:([^:]+)") or item.key)) .. (item.key:match(":(%a+)$") and (" " .. item.key:match(":(%a+)$")) or "")
                pcall(GUI.records.Set, tostring(i), string.format("%d/%d won · %.1f min avg · %d gems", item.r.wins, item.r.runs, item.r.sec / math.max(1, item.r.runs) / 60, item.r.gems), nil, str)
            else
                pcall(GUI.records.Set, tostring(i), "", nil, i == 1 and "no runs yet" or "")
            end
        end
    end
    if GUI.team then
        local equipped = Units.equipped()
        for i = 1, 6 do
            local value = equipped [i]
            if value then
                local trait, trait2 = Units.trait(value.u)
                local name = trait and (Core.traitInfo(trait) or {
                }).name or "no trait"
                local relicName = Units.relicName(value.u)
                local text
                if Units.isFarm(value.id) then
                    text = string.format("farm unit · ¥%s a wave at full upgrade · %s%s", Utils.fmt(Units.farm(value.u, Units.rows(value.id).max)), name, trait2 and trait2 ~= "1" and (" " .. trait2) or "")
                else
                    local types, types2 = Units.types(value.id)
                    local list = {
                    }
                    for typeKey in pairs(types) do
                        if typeKey ~= types2 then
                            table.insert(list, (typeKey:gsub("_damage", "")))
                        end
                    end
                    text = string.format("score %s · %s · up to %d on the field · %s%s%s", Utils.fmt(Units.score(value.u, Match.mod)), name .. (trait2 and trait2 ~= "1" and (" " .. trait2) or ""), Units.cap(value.u), types2, # list > 0 and ("+" .. table.concat(list, "/")) or "", relicName and (" · relic: " .. relicName) or "")
                end
                pcall(GUI.team.Set, tostring(i), text, nil, Units.name(value.id))
            else
                pcall(GUI.team.Set, tostring(i), "", nil, "")
            end
        end
    end
    if GUI.start then
        local ok, res = pcall(GUI.startView, col)
        if ok and res then
            pcall(GUI.start.Set, res)
        end
    end
    if GUI.plan then
        local ok, res = pcall(GUI.planView, col)
        if ok and res then
            pcall(GUI.plan.Set, res)
        end
    end
    if GUI.fusionCompare and GUI.fusionRunning and Simulator.progress then
        pcall(GUI.fusionCompare.Set, "Result", string.format("Simulating… %d%% · %s", math.floor((Simulator.progress.frac or 0) * 100 + 0.5), tostring(Simulator.progress.text)))
    end
    if GUI.sim then
        local value = Modes.lastScored and Modes.lastScored [1]
        local simRe = value and Brain.simRes [value.key]
        pcall(GUI.sim.Set, "Next mode", value and (value.label .. ": " .. (simRe and (simRe.playing or simRe.margin) or (simRe and simRe.none and "can't simulate this one yet") or "not simulated yet")) or "—")
        local value, simResult
        for key, value2 in pairs(Brain.simTeam) do
            if not simResult or (value2.at or 0) > (simResult.at or 0) then
                value, simResult = key, value2
            end
        end
        local simRe = simResult and Brain.simRes [value]
        local pred = App.where == "match" and Match.pred
        pcall(GUI.sim.Set, "Your team", pred and string.format("this run: %s wave %d · now wave %d", Match.infinite and (pred.won and "lasts past" or "the base falls at") or (pred.won and "a win at" or "a loss at"), pred.wave, Match.wave()) or simResult and string.format("%s: %s%s", simResult.label or value, simRe and simRe.margin or (simResult.cur.won and "wins" or ("reaches wave " .. tostring(simResult.cur.wave))), simResult.better and " (before the best team went in)" or "") or "the planner runs in the lobby")
        pcall(GUI.sim.Set, "Best team", simResult and (table.concat(simResult.names or {
        }, ", ") .. (simResult.better and (" → " .. (simResult.won and "wins" or ("reaches wave " .. tostring(simResult.wave)))) or " (your team is already the best the sim found)")) or "—")
        local list = {
        }
        for _, value in ipairs(Brain.simEvo or {
        }) do
            table.insert(list, string.format("%s → %s: %s%s", value.from, value.to, value.gain, value.ready and " · ready" or (value.missing and (" · needs " .. value.missing) or "")))
        end
        pcall(GUI.sim.Set, "Evolutions", # list > 0 and table.concat(list, "\n") or "none ready (planner runs in the lobby)")
        local list = {
        }
        for key, value in pairs(Brain.simCal) do
            local lastPred = value.lastPred
            if lastPred then
                table.insert(list, string.format("%s: predicted %s (wave %d) · real %s (wave %d)", GUI.keyName(key), lastPred.won and "win" or "loss", lastPred.wave or 0, lastPred.realWon and "win" or "loss", lastPred.realWave or 0))
            end
        end
        pcall(GUI.sim.Set, "Accuracy", # list > 0 and table.concat(list, "\n") or "no predicted run yet")
    end
    if GUI.path then
        if App.where == "match" and FarmHub.every("goalsMatch", 300) then
            task.spawn(function()
                pcall(Adventure.refresh)
            end)
        end
        local focusNow = GUI.focusNow()
        local value = focusNow == "" and ((Brain.train.on and Brain.train.on.uuid) or ((Brain.goals or {
        }) [1] and Brain.goals [1].uuid)) or nil
        for i = 1, 11 do
            local item = (Brain.goalsTop or {
            }) [i]
            if item then
                local str = item.uuid == focusNow and "🎯 Your focus · " or (item.uuid == value and "🤖 Smart Play's pick · " or "")
                pcall(GUI.path.Set, tostring(i), str .. tostring(item.text), item.uuid == focusNow and col.gold or (item.ready and not item.hidden and col.green or (item.intoTeam and col.purple or ((item.unknown or item.hidden) and col.sub or col.text))), Units.name(item.to))
            else
                pcall(GUI.path.Set, tostring(i), i == 1 and "goals are worked out in the lobby" or "", col.sub, i == 1 and "—" or "")
            end
        end
        if GUI.UI.focusPick and FarmHub.every("focusList", 3) then
            local focusOptions, list = GUI.focusOptions(), {
                focusNow
            }
            for _, focusOption in ipairs(focusOptions) do
                table.insert(list, tostring(focusOption.text) .. "=" .. tostring(focusOption.value))
            end
            list = table.concat(list, "|")
            if GUI.focusSig and GUI.focusSig ~= list then
                pcall(GUI.UI.focusPick.Refresh, focusOptions, focusNow)
            end
            GUI.focusSig = list
        end
        local list = {
        }
        for _, goal in ipairs(Brain.goals) do
            if goal.ready then
                table.insert(list, Units.name(goal.from) .. " → " .. Units.name(goal.to))
            end
        end
        if GUI.readyLabel then
            pcall(GUI.readyLabel.Set, # list > 0 and ("Ready: " .. table.concat(list, " · ")) or "Nothing ready yet — the farm is collecting the items")
        end
    end
    local live = GUI.LIVE
    if live.only and FarmHub.every("onlyText", 2) then
        local value = Modes.lastScored and Modes.lastScored [1]
        local list = {
        }
        for _, value in pairs(Modes.skipped) do
            table.insert(list, "Skipped: " .. value)
        end
        table.sort(list)
        pcall(live.only.Set, GUI.modeSummary(value, list))
    end
    if live.summonPick and FarmHub.every("summonText", 3) then
        pcall(function()
            live.summonPick.Set(FarmHub.summonText())
        end)
    end
    if live.snipe and FarmHub.every("snipeText", 5) then
        pcall(function()
            live.snipe.Set(FarmHub.snipeText())
        end)
    end
    if live.study and FarmHub.every("studyText", 5) then
        pcall(function()
            live.study.Set(FarmHub.studyText())
        end)
    end
    if live.hive and FarmHub.every("hiveText", 15) then
        pcall(function()
            live.hive.Set(Reports.hiveText())
        end)
    end
    if GUI.homeKv and FarmHub.every("homeRows", 3) then
        local ok, res = pcall(GUI.homeRows)
        for _, homeKey in ipairs(GUI.HOME_KEYS) do
            pcall(GUI.homeKv.Set, homeKey, ok and res [homeKey] or "…", (ok and tostring(res [homeKey]):sub(1, 3) == "off") and col.sub or col.text)
        end
    end
    if GUI.lbCard and FarmHub.every("lbCard", 3) then
        local ok, res = pcall(GUI.lbStatus)
        if ok then
            pcall(GUI.lbCard.Set, res)
        end
    end
    if GUI.fodder and Core.session() and (GUI.fodderSig == nil or (App.where == "lobby" and FarmHub.every("fodderRows", 15))) then
        local session = Core.session()
        local unitObj = session and Config.fuseUnit ~= "" and session.collection:get_unit_by_uuid(Config.fuseUnit) or nil
        local ok, res = pcall(FarmHub.fodderRows, unitObj)
        res = ok and res or {
        }
        local list = {
            tostring(Config.fuseUnit)
        }
        for _, item in ipairs(res) do
            table.insert(list, item.uuid .. ":" .. item.pts .. ":" .. # item.flags .. (item.safe and "s" or ""))
        end
        list = table.concat(list, ",")
        if GUI.fodderSig ~= list then
            GUI.fodderSig = list
            pcall(GUI.fodder.Refresh, res, unitObj and "Nothing the game would take for this unit. Locked and equipped units never show." or "Pick a unit to limit break above, and the units it could use show here.")
        else
            pcall(GUI.fodder.summary)
        end
    end
    if live.hunt and FarmHub.every("huntText", 5) then
        pcall(function()
            live.hunt.Set(Hunt.text())
        end)
    end
    if live.skins and FarmHub.every("skinText", 8) then
        pcall(function()
            live.skins.Set(Hunt.skinText())
        end)
    end
    if live.fusePick and FarmHub.every("fuseText", 8) then
        pcall(function()
            live.fusePick.Set(FarmHub.fuseText())
        end)
    end
    if live.fuseXpPick and FarmHub.every("fuseXpText", 8) then
        pcall(function()
            live.fuseXpPick.Set(FarmHub.fuseXpText())
        end)
    end
    if live.focus and FarmHub.every("focusText", 3) then
        pcall(function()
            live.focus.Set(FarmHub.focusText())
        end)
    end
    if live.teamNext and FarmHub.every("teamText", 3) then
        pcall(function()
            live.teamNext.Set(Strategy.text())
        end)
    end
    if GUI.core and FarmHub.every("coreRows", 8) then
        local ok, res = pcall(Strategy.rows)
        for i = 1, 8 do
            local value = ok and res [i]
            if value then
                pcall(GUI.core.Set, tostring(i), value.text, value.text:find("next:") and col.text or col.green, value.name)
            else
                pcall(GUI.core.Set, tostring(i), "", nil, i == 1 and (ok and "no core units yet" or ("error: " .. tostring(res))) or "")
            end
        end
    end
    local flag = false
    for listKey in pairs(GUI.lists) do
        if GUI.listEmpty [listKey] then
            flag = true
            break
        end
    end
    if (App.where == "lobby" and FarmHub.every("pickLists", 30)) or (flag and Core.session() and FarmHub.every("pickListsEarly", 5)) then
        for listKey, list in pairs(GUI.lists) do
            if App.where == "lobby" or GUI.listEmpty [listKey] then
                local ok, res = pcall(list)
                if ok then
                    local sigOf = GUI.sigOf(res)
                    if GUI.listSig [listKey] ~= sigOf then
                        pcall(GUI.UI [listKey .. "Pick"].Refresh, res, Config [listKey])
                        if GUI.listEmpty [listKey] and # res > 1 then
                            App.log(1, "INFO", string.format("the window opened before the game had your units: %s's list filled in %d s later", listKey, math.floor(Utils.now() - (GUI.listAt or Utils.now()))))
                        end
                    end
                    GUI.listSig [listKey] = sigOf
                    if Core.session() then
                        GUI.listEmpty [listKey] = nil
                    end
                end
            end
        end
    end
    if live.train then
        pcall(live.train.Set, Training.text())
    end
    if live.community and FarmHub.every("communityText", 30) then
        pcall(live.community.Set, Adventure.communityText())
    end
    if live.goal and FarmHub.every("goalText", 5) then
        pcall(live.goal.Set, Adventure.goalText())
    end
    if live.fh and FarmHub.every("fhText", 10) then
        pcall(live.fh.Set, Match.fhText())
    end
    if live.dungeon and FarmHub.every("dgText", 5) then
        pcall(live.dungeon.Set, Dungeon.text())
    end
    if live.lb then
        pcall(live.lb.Set, Adventure.lbText())
    end
    if GUI.namekReport and FarmHub.every("namekTestUi", 2) then
        pcall(GUI.namekReport.Set, GUI.namekTestText())
    end
    if GUI.econCard and App.where == "match" then
        pcall(GUI.econCard.Set, {
            icon = "💰",
            title = string.format("¥%s now · farm ¥%s a wave",
            Utils.fmt(Match.money()),
            Utils.fmt(Match.farmNow or 0)),
            text = tostring(Status.Economy or ""),
            sub = string.format("coming yen ≈%s · still to buy ≈%s",
            Utils.fmt(Match.future or 0),
            Utils.fmt(Match.wantLeft or 0))
        })
    end
    local live = GUI.LIVE
    if live.spend then
        pcall(live.spend.Set, Spending.text())
    end
    if live.lastMatch then
        local lastMatch = Brain.lastMatch
        pcall(live.lastMatch.Set, lastMatch and string.format("Last match (%s): ¥%s spent on %d buys · %d refused spots", lastMatch.label, Utils.fmt(lastMatch.spent), lastMatch.actions or 0, lastMatch.refusals or 0) or "no match yet")
    end
    if live.totals then
        pcall(live.totals.Set, string.format("matches %d · wins %d · losses %d · gems %s · event coins %s", Brain.totals.matches or 0, Brain.totals.wins or 0, Brain.totals.losses or 0, Utils.fmt(Brain.totals.gems or 0), Utils.fmt(Brain.totals.coins or 0)))
    end
end

function GUI.loop()
    while App.alive do
        pcall(GUI.update)
        task.wait(1)
    end
end
table.insert(App.conns, LocalPlayer.Idled:Connect(function()
    if not Config.antiAfk then
        return
    end
    pcall(function()
        local VirtualUser = game:GetService("VirtualUser")
        VirtualUser:CaptureController()
        VirtualUser:ClickButton2(Vector2.new())
    end)
end))

function App.cleanup()
    GUI.setMapTexturesHidden(false)
    for _, conn in ipairs(App.conns) do
        pcall(function()
            conn:Disconnect()
        end)
    end
    pcall(function()
        GUI.Win:Destroy()
    end)
    pcall(function()
        if Match.probe then
            Match.probe:Destroy()
        end
    end)
    pcall(function()
        if Match.bounds then
            Match.bounds:Destroy()
        end
    end)
end

function App.unload()
    App.alive = false
    App.saveNow()
    pcall(FarmHub.quietFx, true)
    App.cleanup()
    _G.AA_SF = nil
end

function App.restart()
    local loadstring2, loadstring22 = loadstring(readfile(Core.SELF), "=awaqwaa_script_awaqwaa_airflow")
    assert(loadstring2, loadstring22)
    App.unload()
    loadstring2()
end
task.spawn(function()
    while App.alive do
        task.wait(1)
        if _G.AA_SF ~= App then
